// بيانات السور
Object.assign(quranData, {
    53: { // سورة النجم
        name: "النجم",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلنَّجْمِ إِذَا هَوَىٰ", tafsir: `قسما بالنجم ، والمنصرف جنس النجم ( إِذا هَوى ) نحو المغيب ، من وسط السماء ، أو من الأفق.` },
            { text: "مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ", tafsir: `ما عدل هو عن الطريق المستقيم ، ولعل وجه القسم بالنجم ، أن النبي صلى‌الله‌عليه‌وآله‌وسلم نجم معنوي في كل أحواله ، كما أن النجم نجم حتى في حال هويه ، ( وَما غَوى ) الناس في دعوته إلى الله ، بل هو مهتد في نفسه ودعوته للناس دعوة إلى الرشد.` },
            { text: "وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ", tafsir: `عن هوى النفس وميوله الشخصية كما كان الكافرون يقولون « تقوّله » .` },
            { text: "إِنْ هُوَ إِلَّا وَحْىٌ يُوحَىٰ", tafsir: `ما ( هُوَ ) الذي نطق به من القرآن وسائر إخباره عن الله تعالى ( إِلَّا وَحْيٌ يُوحى ) إليه من جانب الله وهل الوحي وقتي ، أو مستمر وإنما جهاز الاستقبال وقتي مثله مثل نور الشمس المستمرة منذ أن خلقت ، وإنما إذا وجدت زجاجة مقعرة أخذته وأحرقت به ما ينعكس إليه النور منها ، فحالة الرسول صلى‌الله‌عليه‌وآله‌وسلم الخاصة تأخذ الوحي المناسب في الوقت المناسب ، احتمالان : وإن كان ظاهر الأدلة الأول.` },
            { text: "عَلَّمَهُۥ شَدِيدُ ٱلْقُوَىٰ", tafsir: `أي علم الرسول صلى‌الله‌عليه‌وآله‌وسلم بالوحي ( شَدِيدُ الْقُوى ) جبرئيل ، فإن للملك قوى كما للإنسان قوى ، وقوى الملك شديدة ، مثلا علمه كثير ، ولا ينسى ، وقدرته كثيرة ولا تضعف إلى غير ذلك ، وظاهر الآية بسياق الآيات الآتية أن المراد به جبرئيل عليه‌السلام . ذُو مِرَّةٍ فَاسْتَوى (6) وَهُوَ بِالْأُفُقِ الْأَعْلى (7) ثُمَّ دَنا فَتَدَلَّى (8) فَكانَ قابَ قَوْسَيْنِ أَوْ أَدْنى (9) فَأَوْحى إِلى عَبْدِهِ ما أَوْحى (10)` },
            { text: "ذُو مِرَّةٍ فَٱسْتَوَىٰ", tafsir: `ذو قوة ، وأصل المرة خلط في العروق ، كالصفراء والسوداء ، وسمي مرة لقوة البدن به ، ثم استعملت في أصل القوة ، فكأنه قال مرة « قواه شديدة » ومرة « قوى بمجموعة » أو المراد بذي مرة حصانة في عقله ورأيه فالأول : لقواه المادية. والثاني : لقوته العقلية ، فلما أراد أن ينزل الوحي على الرسول صلى‌الله‌عليه‌وآله‌وسلم ( فَاسْتَوى ) استولى على الأرض لإتيان الوحي.` },
            { text: "وَهُوَ بِٱلْأُفُقِ ٱلْأَعْلَىٰ", tafsir: `جبرئيل عليه‌السلام ( بِالْأُفُقِ الْأَعْلى ) مكانه في أعالي السماوات.` },
            { text: "ثُمَّ دَنَا فَتَدَلَّىٰ", tafsir: `جبرئيل إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم ( فَتَدَلَّى ) في الهواء ، تدلي الدلو في البئر ، وأصل التدلي استرسال مع تعلق ، ولعل هذا التعبير باعتبار تعلق جبرئيل عليه‌السلام بالأعلى تعلقا.` },
            { text: "فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَىٰ", tafsir: `جبرئيل من محمد صلى‌الله‌عليه‌وآله‌وسلم ( قابَ قَوْسَيْنِ ) فإن قوسين إذا التصقت إحداهما بالأخرى يكون عرضهما مقدار ذراعين لأن « قاب » كل قوس مقدار ذراع تقريبا ، و « القاب » عبارة عن الفاصل بين رأسي القوس الواحد ، والمراد من هذه الآية ـ حسب الظاهر ـ إن قرب جبرئيل من رسول الله صلى‌الله‌عليه‌وآله‌وسلم كان بقدر ذراعين ( أَوْ أَدْنى ) ولعله كان يقترب ويبتعد ، كما هي عادة كل متكلّمين.` },
            { text: "فَأَوْحَىٰٓ إِلَىٰ عَبْدِهِۦ مَآ أَوْحَىٰ", tafsir: `الله في هذه الحالة ( إِلى عَبْدِهِ ) الرسول صلى‌الله‌عليه‌وآله‌وسلم ( ما أَوْحى ) ما أراد وحيه ، أو المراد ، ب « أوحى » جبرئيل ، مثل ( قُلْ يَتَوَفَّاكُمْ مَلَكُ ما كَذَبَ الْفُؤادُ ما رَأى (11) أَ فَتُمارُونَهُ عَلى ما يَرى (12) وَلَقَدْ رَآهُ نَزْلَةً أُخْرى (13) عِنْدَ سِدْرَةِ الْمُنْتَهى (14) عِنْدَها جَنَّةُ الْمَأْوى (15) الْمَوْتِ ) (1) أما الضمير في عبده راجع إلى الله سبحانه ، وفي تفسير الآية ذكر مصاديق وتأويلات لا تنافي ظاهرها الذي ذكرناه.` },
            { text: "مَا كَذَبَ ٱلْفُؤَادُ مَا رَأَىٰٓ", tafsir: `فؤاد رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( ما رَأى ) من جبرئيل وسمع من الوحي ، إذ قد يكذب الفؤاد الحواس ، كأن يرى الإنسان الشمس والقمر صغيرين ، أو ماء البحر أسود ، لكن القلب يقول ليس كما رأيت ، فالرسول صلى‌الله‌عليه‌وآله‌وسلم رأى جبرئيل بعينه وعرف صدق رؤيته بقلبه.` },
            { text: "أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ", tafsir: `أي أيها الكفار هل تجادلون محمد صلى‌الله‌عليه‌وآله‌وسلم ( عَلى ما يَرى ) ما رآه فتقولون له : قد اشتبهت ولم يكن جبرئيل ؟ ولعل الإتيان ب « يرى » بصيغة المستقبل ، لاستمرار علم الرسول صلى‌الله‌عليه‌وآله‌وسلم إلى وقت الكلام ، بأن ما رآه كان صدقا ، لا خيالا. [14] وهل يمكن أن يكون الرسول صلى‌الله‌عليه‌وآله‌وسلم قد اشتبه ( وَ ) الحال أن الرسول صلى‌الله‌عليه‌وآله‌وسلم ( لَقَدْ رَآهُ ) رأى جبرئيل ( نَزْلَةً أُخْرى ) حين نزل بالوحي إليه مرة ثانية ، والاشتباه لا يمكن مرتين. [15] وكانت رؤيته صلى‌الله‌عليه‌وآله‌وسلم الثانية لجبرئيل عليه‌السلام ( عِنْدَ سِدْرَةِ الْمُنْتَهى ) « المنتهى » مضاف إليه ، لعل المراد انتهاء عالم الدنيا إلى هناك بقرينة.` },
            { text: "وَلَقَدْ رَءَاهُ نَزْلَةً أُخْرَىٰ", tafsir: `` },
            { text: "عِندَ سِدْرَةِ ٱلْمُنتَهَىٰ", tafsir: `` },
            { text: "عِندَهَا جَنَّةُ ٱلْمَأْوَىٰٓ", tafsir: `أي عند تلك السدرة ( جَنَّةُ الْمَأْوى ) التي يأوي إليها ( 1) السجدة : 12. إِذْ يَغْشَى السِّدْرَةَ ما يَغْشى (16) ما زاغَ الْبَصَرُ وَما طَغى (17) لَقَدْ رَأى مِنْ آياتِ رَبِّهِ الْكُبْرى (18) أَ فَرَأَيْتُمُ اللاَّتَ وَالْعُزَّى (19) المؤمنون الصالحون.` },
            { text: "إِذْ يَغْشَى ٱلسِّدْرَةَ مَا يَغْشَىٰ", tafsir: `غشيه بمعنى أحاط به واستولى عليه ( ما يَغْشى ) مما لا يعلمه إلا الله تعالى ولعلها باعتبار كونها الحدّ الفاصل بين عالم الدنيا وعالم الآخرة ، يكون مهبط الأملاك من الجنة إلى السماوات والأرض ، ومصعد أرواح المؤمنين والملائكة الصاعدة من الأرضين والسماوات إلى طرف الجنة. [18] ولا يقول الكفار لعلّه اشتبه الرسول صلى‌الله‌عليه‌وآله‌وسلم هذه المرة أيضا ، لأنه ( ما زاغَ ) لم يمل ( الْبَصَرُ ) بصر رسول الله ، بأن رأى غير جبرئيل فزعم ( وَما طَغى ) بأن لم يكن شيء فيزعمه شيئا كما في من يرى السراب فيزعمه شيئا وهو ليس بشيء ، ثم لا يخفى أن رؤية الرسول صلى‌الله‌عليه‌وآله‌وسلم لجبرئيل مرتين ، إنما يراد به أنه رآه بصورته الواقعية ، كما ورد بذلك النص والتفاسير (1) ، وإما بغير صورته الواقعية ، كصورة « دحية » فقد رآه صلى‌الله‌عليه‌وآله‌وسلم مرات عديدة.` },
            { text: "مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ", tafsir: `` },
            { text: "لَقَدْ رَأَىٰ مِنْ ءَايَٰتِ رَبِّهِ ٱلْكُبْرَىٰٓ", tafsir: `الرسول صلى‌الله‌عليه‌وآله‌وسلم عند سدرة المنتهى ( مِنْ آياتِ رَبِّهِ الْكُبْرى ) أي الآيات العظام التي كانت حول شجرة السدرة. [20] هل الله وما شاهده الرسول صلى‌الله‌عليه‌وآله‌وسلم من آيات الله ، يقاس بما أنتم عاكفون عليها من الأصنام ؟ ( أَ فَرَأَيْتُمُ اللَّاتَ وَالْعُزَّى ) وهما صنمان كان ( 1) الاحتجاج : ج 1 ص 243. وَمَناةَ الثَّالِثَةَ الْأُخْرى (20) أَ لَكُمُ الذَّكَرُ وَلَهُ الْأُنْثى (21) تِلْكَ إِذاً قِسْمَةٌ ضِيزى (22) إِنْ هِيَ إِلاَّ أَسْماءٌ سَمَّيْتُمُوها أَنْتُمْ وَآباؤُكُمْ ما أَنْزَلَ اللهُ بِها مِنْ سُلْطانٍ يعبدهما قريش.` },
            { text: "أَفَرَءَيْتُمُ ٱللَّٰتَ وَٱلْعُزَّىٰ", tafsir: `` },
            { text: "وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلْأُخْرَىٰٓ", tafsir: `الصنم ( الثَّالِثَةَ الْأُخْرى ) ولعلها أخرى في المرتبة عندهم ؟ أقول : وحذف الجواب لزيادة الاستهجان ، فهو كما يقال « لزيد مليون دينار » ثم يقال أرأيتم كم لعمرو من الدنانير ؟ « فيما كان له ثلاثة دنانير مثلا » فإن قوله : أ رأيت ، يراد به الاستهجان ، وبيان عدم المقايسة بين الأمرين. [22] ثم استهجن القرآن كلاما أخرا للمشركين ، وهو قولهم أن الملائكة بنات الله فقال ( أَ لَكُمُ الذَّكَرُ وَلَهُ ) سبحانه ( الْأُنْثى ) فقد كانوا يزعمون بأنهم مخصصون بالأولاد الذكور ، ولا ولد ذكر الله تعالى ، ويحتمل أن يراد أنكم تكرهون الإناث ، فكيف جعلتم الأصنام الثلاثة « وكانوا يزعمون أنهم إناث » شركاء الله تعالى.` },
            { text: "أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلْأُنثَىٰ", tafsir: `` },
            { text: "تِلْكَ إِذًا قِسْمَةٌ ضِيزَىٰٓ", tafsir: `القسمة بينكم ف « لكم الذكر » وبين الله « وله الأنثى » ( إِذاً ) إذا كان كما زعمتم ( قِسْمَةٌ ضِيزى ) جائرة ، من ضاز يضيز ، إذا جار.` },
            { text: "إِنْ هِىَ إِلَّآ أَسْمَآءٌ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ", tafsir: `ما تلك الأصنام الثلاثة ( إِلَّا أَسْماءٌ ) أي تسميتها بالألوهية اسم مجرد لا حقيقة تحت هذا الاسم ف « هي » محل ، أطلق ، وأريد به « الحال » لأن « الاسم » حال ، و « الصنم » محل ( سَمَّيْتُمُوها ) مجرد تسمية ( أَنْتُمْ وَآباؤُكُمْ ) من قبل ، وإلا فهل الأصنام آلهة ؟ ( ما أَنْزَلَ اللهُ بِها مِنْ سُلْطانٍ ) من حجة وبرهان ، وإنما هوى أنفسهم مع تلك إِنْ يَتَّبِعُونَ إِلاَّ الظَّنَّ وَما تَهْوَى الْأَنْفُسُ وَلَقَدْ جاءَهُمْ مِنْ رَبِّهِمُ الْهُدى (23) أَمْ لِلْإِنْسانِ ما تَمَنَّى (24) فَلِلَّهِ الْآخِرَةُ وَالْأُولى (25) وَكَمْ مِنْ مَلَكٍ فِي السَّماواتِ لا تُغْنِي شَفاعَتُهُمْ شَيْئاً الأصنام ثم ظنوا أنها آلهة ، فلا دليل من العقل ولا من الشرع عليها ( إِنْ ) ما ( يَتَّبِعُونَ إِلَّا الظَّنَ ) بأنها آلهة ( وَما تَهْوَى الْأَنْفُسُ ) ما تشتهيه أنفسهم ( وَلَقَدْ جاءَهُمْ مِنْ رَبِّهِمُ الْهُدى ) الرسول والكتاب المطابقان للعقل والفطرة فتركوهما واتبعوا أهواءهم الباطلة في القول بأن الأصنام آلهة.` },
            { text: "أَمْ لِلْإِنسَٰنِ مَا تَمَنَّىٰ", tafsir: `استفهام إنكاري أي ليس للإنسان ما يتمناه ، فهؤلاء يتمنون صحة عقيدتهم ويتمنون أن تشفع الأصنام لهم ، لكن هذا التمني لا يتحقق.` },
            { text: "فَلِلَّهِ ٱلْـَٔاخِرَةُ وَٱلْأُولَىٰ", tafsir: `بيده كل شيء فهو الإله وهو الشفيع ( قُلْ لِلَّهِ الشَّفاعَةُ جَمِيعاً ) (1) . [27] إنهم يرجون الشفاعة من الأصنام بينما الملائكة لا تقدر على الشفاعة إلا بعد إذن الله ( وَكَمْ مِنْ مَلَكٍ فِي السَّماواتِ ) فهو مع كونه ملكا ، ومع كونه في السماوات قريبا من رحمة الله ( لا تُغْنِي ) لا تفيد ( شَفاعَتُهُمْ شَيْئاً ) أي أنهم على تقدير أن يشفعوا لا تفيد شفاعتهم و « كم » لا مفهوم له ، حتى يكون هناك « ملك » تغني شفاعته ، ولعل الإتيان به لإفادة أنه إذا كان كثير من الملائكة كذلك ، فكيف بالأصنام ؟ ولا حاجة في إسقاط الأصنام ( 1) الزمر : 45. إِلاَّ مِنْ بَعْدِ أَنْ يَأْذَنَ اللهُ لِمَنْ يَشاءُ وَيَرْضى (26) إِنَّ الَّذِينَ لا يُؤْمِنُونَ بِالْآخِرَةِ لَيُسَمُّونَ الْمَلائِكَةَ تَسْمِيَةَ الْأُنْثى (27) وَما لَهُمْ بِهِ مِنْ عِلْمٍ إِنْ يَتَّبِعُونَ إِلاَّ الظَّنَّ وَإِنَّ الظَّنَّ لا يُغْنِي مِنَ الْحَقِّ شَيْئاً (28) فَأَعْرِضْ عَنْ مَنْ تَوَلَّى عَنْ ذِكْرِنا وَلَمْ يُرِدْ إِلاَّ الْحَياةَ الدُّنْيا (29) عن الشفاعة القول بأن « كل الملائكة كذلك » ( إِلَّا مِنْ بَعْدِ أَنْ يَأْذَنَ اللهُ ) في الشفاعة ( لِمَنْ يَشاءُ ) من الملائكة أن يشفع ومن الناس أن يشفع له ( وَيَرْضى ) ويراه أهلا لذلك : شافعا ومشفوعا ، والرضا وإن كان قبل الإذن إلا أن ملاحظة رؤوس الآي أورث تأخيره ،` },
            { text: "وَكَم مِّن مَّلَكٍ فِى ٱلسَّمَٰوَٰتِ لَا تُغْنِى شَفَٰعَتُهُمْ شَيْـًٔا إِلَّا مِنۢ بَعْدِ أَن يَأْذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرْضَىٰٓ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ لَيُسَمُّونَ ٱلْمَلَٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ", tafsir: `الكفار ( الَّذِينَ لا يُؤْمِنُونَ بِالْآخِرَةِ ) وذلك يلازم عدم إيمانهم بما جاء عن الله ( لَيُسَمُّونَ الْمَلائِكَةَ تَسْمِيَةَ الْأُنْثى ) فإنهم حيث قالوا الملائكة بنات الله سموا كل ملك بنتا.` },
            { text: "وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا", tafsir: `الحال ( ما لَهُمْ بِهِ ) بما يقولون ( مِنْ عِلْمٍ ) أي لا علم لهم بأن الملائكة أنثى ( إِنْ ) ما ( يَتَّبِعُونَ إِلَّا الظَّنَ ) فإنهم يظنون أن الملائكة بنات ( وَإِنَّ الظَّنَّ لا يُغْنِي ) لا يفيد ( مِنَ الْحَقِّ شَيْئاً ) إذ لا برهان للظن ، وما لا برهان له ليس مطابقا للواقع ، فإن كل مطابق للواقع له برهان.` },
            { text: "فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا", tafsir: `يا رسول الله ( عَنْ مَنْ تَوَلَّى عَنْ ذِكْرِنا ) إذ لا يفيد معه التذكير ! لأنه معاند ( وَلَمْ يُرِدْ إِلَّا الْحَياةَ الدُّنْيا ) فكل سعيه وعمله للدنيا ، ذلِكَ مَبْلَغُهُمْ مِنَ الْعِلْمِ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيلِهِ وَهُوَ أَعْلَمُ بِمَنِ اهْتَدى (30) وَلِلَّهِ ما فِي السَّماواتِ وَما فِي الْأَرْضِ لِيَجْزِيَ الَّذِينَ أَساؤُا بِما عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى (31) الَّذِينَ يَجْتَنِبُونَ كَبائِرَ الْإِثْمِ وَالْفَواحِشَ ولا يعتقد بالآخرة حتى يعمل لها ، فهو منكر للتوحيد ، ومنكر للمعاد.` },
            { text: "ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ", tafsir: `انحصار فكرهم في الدنيا ، من دون نفوذ علمهم إلى المبدأ ولا إلى المعاد ( مَبْلَغُهُمْ مِنَ الْعِلْمِ ) قدر بلوغ علمهم فهو علم ضيّق محدود منحرف ، فلا تتعب نفسك يا رسول الله مع هؤلاء فإن الله يعلم حالهم وسوف يجازيهم ( إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيلِهِ ) أي أنفذ علما فيعلم خصوصياتهم وكل دقائقهم ( وَهُوَ أَعْلَمُ بِمَنِ اهْتَدى ) فيجازي كلا حسب عقيدته وعمله.` },
            { text: "وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى", tafsir: `أي الذي ( فِي السَّماواتِ وَما ) أي الذي ( فِي الْأَرْضِ ) أي كل شيء فيهما ملكا وخلقا ( لِيَجْزِيَ ) الله ( الَّذِينَ أَساؤُا بِما عَمِلُوا ) والعمل يشمل عمل القلب أيضا لأن الاعتقاد عقد القلب على شيء خاص ، و « اللام » للعاقبة ، لا للعلّة ، مثله ، مثل ( لِيَكُونَ لَهُمْ عَدُوًّا ) (1) ( وَيَجْزِيَ الَّذِينَ أَحْسَنُوا ) بالمثوبة الحسنى في الدنيا والآخرة. [33] ومن هم الذين أحسنوا ؟ هم ( الَّذِينَ يَجْتَنِبُونَ كَبائِرَ الْإِثْمِ ) الآثام الكبيرة والتي منها الكفر والشرك وعدم الإيمان بالرسول وبما جاء به الرسول وعدم الإيمان بالمعاد ( وَالْفَواحِشَ ) التي إثمها يتعدى إلى ( 1) القصص : 9. إِلاَّ اللَّمَمَ إِنَّ رَبَّكَ واسِعُ الْمَغْفِرَةِ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنْشَأَكُمْ مِنَ الْأَرْضِ وَإِذْ أَنْتُمْ أَجِنَّةٌ فِي بُطُونِ أُمَّهاتِكُمْ فَلا تُزَكُّوا أَنْفُسَكُمْ هُوَ أَعْلَمُ بِمَنِ اتَّقى (32) الآخرين ، من فحش إذا تعدى عمله الآثم إلى الآخرين ( إِلَّا اللَّمَمَ ) أي الذي يلمّ بالإنسان ويرد عليه مما لا علاج من وروده غالبا ، وهي الصغائر وهي الصغائر مثل كلمة نابية ، أو ضحكة غير جائزة أو نظرة محرمة أو ما شابه ذلك ، والاستثناء منقطع لدفع توهم أن كل عصيان كبيرة ، حيث إنها معصية لإله عظيم ( إِنَّ رَبَّكَ واسِعُ الْمَغْفِرَةِ ) فيغفر للّمم قطعا ، بعد أن كان يغفر لكثير من الكبائر لمن يشاء ( هُوَ أَعْلَمُ بِكُمْ ) حتى من أنفسكم فمن عمل صالحا يعرفه ومن عمل فاسدا يعرفه ( إِذْ أَنْشَأَكُمْ مِنَ الْأَرْضِ ) فإن علمه شامل لزمان تكوينكم من الأرض حيث إن الإنسان تراب ثم ينقلب ، نباتا ، ثم ينقلب حيوانا ثم النبات والحيوان ينقلب إلى طعام يأكله الأبوان فيصير دما ثم منيّا ( وَإِذْ أَنْتُمْ أَجِنَّةٌ ) جمع جنين ( فِي بُطُونِ أُمَّهاتِكُمْ ) وهذه أول مرحلة إنسانية ، فيعلم بكم من ذلك الحين إلى اليوم ( فَلا تُزَكُّوا أَنْفُسَكُمْ ) لا يغرنكم أعمالكم الصالحة ، كما يقع فيه بعض المؤمنين غير المتأدبين ، فيزكي نفسه إنه صام وصلى وأنفق وفعل الخير ، فإنه غرور يوجب سقوط النفس عن الرفعة عند الله وعند الناس ( هُوَ ) سبحانه ( أَعْلَمُ بِمَنِ اتَّقى ) فعلى المؤمن ، لا يكون مفرّطا بعمل الفواحش ، ولا مفرطا يزكي نفسه ، فإن التزكية للنفس قبيح ، ولله أقبح لأنه أعلم بالإنسان من حال كونه ترابا إلى حال تقيّا ، حتى من نفسه. [34] وإذا عرفنا أحوال المتقين الذين يجتنبون كبائر الإثم والفواحش إلا أَ فَرَأَيْتَ الَّذِي تَوَلَّى (33) وَأَعْطى قَلِيلاً وَأَكْدى (34) أَ عِنْدَهُ عِلْمُ الْغَيْبِ فَهُوَ يَرى (35) أَمْ لَمْ يُنَبَّأْ بِما فِي صُحُفِ مُوسى (36) وَإِبْراهِيمَ الَّذِي وَفَّى (37) اللمم فلنعرف أحوال غيرهم ( أَ فَرَأَيْتَ ) في قبال ذلك المتقي ( الَّذِي تَوَلَّى ) عن الحق وأعرض عنه وإن آمن به.` },
            { text: "ٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌ فِى بُطُونِ أُمَّهَٰتِكُمْ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ", tafsir: `` },
            { text: "أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ", tafsir: `` },
            { text: "وَأَعْطَىٰ قَلِيلًا وَأَكْدَىٰٓ", tafsir: `مالا ( قَلِيلاً ) كما هو شأن كثير من الناس حيث يظهرون الإيمان لكنهم لا يلتزمون بموازينه ، وبالأخص لا يدفعون المال المفروض عليهم إطلاقا أو يعطون شيئا قليلا ( وَأَكْدى ) أي قطع العطاء وأمسك يده عن الإنفاق ، لغلبة حالة البخل عليه ، ومن طبيعة أمثال هؤلاء الناس ، أنهم يلقون تبعة ذنوبهم على غيرهم ، فإذا قلت له لماذا تعصي ؟ قال ذنب المبلغين الذين لا يبلغون كاملا ، ثم أن الله يغفر لي ، وما أشبه من الكلمات المتعارفة عند البخلاء والعصاة ، وفي التفاسير أنّ الآيات نزلت في عثمان في قصة (1) ، ومن المعلوم أنه من باب المصداق.` },
            { text: "أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ", tafsir: `` },
            { text: "أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ", tafsir: `ألم يخبر ( بِما فِي صُحُفِ مُوسى ) .` },
            { text: "وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ", tafsir: `بما في صحف ( إِبْراهِيمَ الَّذِي وَفَّى ) كان وفيّا بكل ما تعهد من قبل الله سبحانه ، و « وفّى » بالتشديد مبالغة في الوفاء « وفيه تعريض أن هذا المؤمن الذي أعطى قليلا .. . إلى آخره » لم يوفي بما شرط على ( 1) مجمع البيان : ج 9 ص 298. أَلاَّ تَزِرُ وازِرَةٌ وِزْرَ أُخْرى (38) وَأَنْ لَيْسَ لِلْإِنْسانِ إِلاَّ ما سَعى (39) وَأَنَّ سَعْيَهُ سَوْفَ يُرى (40) ثُمَّ يُجْزاهُ الْجَزاءَ الْأَوْفى (41) وَأَنَّ إِلى رَبِّكَ الْمُنْتَهى (42) وَأَنَّهُ هُوَ أَضْحَكَ وَأَبْكى (43) نفسه من الإطاعة في كل الأوامر.` },
            { text: "أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ", tafsir: `لا تحمل ( وازِرَةٌ ) نفس حاملة ( وِزْرَ ) حمل نفس ( أُخْرى ) فكل إنسان ذنبه على نفسه ، لا كما زعم هذا البخيل من أن ذنبه على غيره.` },
            { text: "وَأَن لَّيْسَ لِلْإِنسَٰنِ إِلَّا مَا سَعَىٰ", tafsir: `؟ فلم يزعم أن إعطائه القليل كاف عن الإعطاء الذي أمر به فكما لا يؤخذ أحد بذنب الغير كذلك لا يثاب أحد بأكثر مما عمل.` },
            { text: "وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ", tafsir: `يراه بنفسه بدار الدنيا جزاء بالمدح أو بغير ذلك ، فإن الدنيا قبل الآخرة دار المكافآت « ولا يجتني الجاني من الشوك العنب » .` },
            { text: "ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ", tafsir: `أي يجزي العبد سعيه ( الْجَزاءَ الْأَوْفى ) الأوفر وذلك في الآخرة. [43] وليعلم الناس أن الله هو مبدأ الأشياء وكل الأشياء تنتهي إليه وكل الأمور بيده ، ولذا يجب عليهم شكره ، وطاعته ، كما يجب عليهم أن يخافوا من عقابه وعذابه ( وَأَنَّ إِلى رَبِّكَ الْمُنْتَهى ) انتهاء كل شيء ، ومعنى « إلى » إلى جزائه وثوابه وعقابه.` },
            { text: "وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ", tafsir: `` },
            { text: "وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ", tafsir: `سبحانه ( أَضْحَكَ وَأَبْكى ) فقد خلق في الإنسان قوتهما وَأَنَّهُ هُوَ أَماتَ وَأَحْيا (44) وَأَنَّهُ خَلَقَ الزَّوْجَيْنِ الذَّكَرَ وَالْأُنْثى (45) مِنْ نُطْفَةٍ إِذا تُمْنى (46) وَأَنَّ عَلَيْهِ النَّشْأَةَ الْأُخْرى (47) وَأَنَّهُ هُوَ أَغْنى وَأَقْنى (48) وَأَنَّهُ هُوَ رَبُّ الشِّعْرى (49) كما خلق وقدر ما يسبب البكاء والضحك ، والضحك والبكاء ليس خاصا بالإنسان بل كل شيء له ضحك وبكاء ، قال الشاعر : إن فصل الربيع فصل جميل تضحك الأرض من بكاء السماء ذهب حيثما ذهبنا ودرّ حيث درنا وفضة في الفضاء` },
            { text: "وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا", tafsir: `سبحانه ( أَماتَ وَأَحْيا ) حتى أنه إذا قتل الإنسان إنسانا فإن روحه بيد الله ، ولذا لا يموت الإنسان في جهنم.` },
            { text: "وَأَنَّهُۥ خَلَقَ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰ", tafsir: `من كل شيء ( الذَّكَرَ وَالْأُنْثى ) وعدم ذكر الخنثى إما لشذوذه ، أو لأنه في الحقيقة إما ذكر أو أنثى. [47] خلقهما ( مِنْ نُطْفَةٍ ) هي الماء القليل ( إِذا تُمْنى ) تدفق في الرحم.` },
            { text: "مِن نُّطْفَةٍ إِذَا تُمْنَىٰ", tafsir: `` },
            { text: "وَأَنَّ عَلَيْهِ ٱلنَّشْأَةَ ٱلْأُخْرَىٰ", tafsir: `سبحانه ( النَّشْأَةَ ) الإنشاء بعد الموت ( الْأُخْرى ) فكما بدأ يقدر على الإعادة.` },
            { text: "وَأَنَّهُۥ هُوَ أَغْنَىٰ وَأَقْنَىٰ", tafsir: `الأغنياء بخلق وسائل الغنى ( وَأَقْنى ) أعطى المال الذي يدّخر للقنية أي الإبقاء ، فالمال المتحرك الموجب للغنى ، والمال الثابت كلاهما من عنده تعالى.` },
            { text: "وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعْرَىٰ", tafsir: `تعالى ( رَبُّ الشِّعْرى ) نجم في السماء يطلع آخر الليل ، وَأَنَّهُ أَهْلَكَ عاداً الْأُولى (50) وَثَمُودَ فَما أَبْقى (51) وَقَوْمَ نُوحٍ مِنْ قَبْلُ إِنَّهُمْ كانُوا هُمْ أَظْلَمَ وَأَطْغى (52) وَالْمُؤْتَفِكَةَ أَهْوى (53) فَغَشَّاها ما غَشَّى (54) فَبِأَيِّ آلاءِ رَبِّكَ تَتَمارى (55) كان جماعة من العرب يعبدونه.` },
            { text: "وَأَنَّهُۥٓ أَهْلَكَ عَادًا ٱلْأُولَىٰ", tafsir: `أي قبيلة عاد ( الْأُولى ) قوم هود عليه‌السلام وهناك عاد ثانية عاد إرم ذات العماد.` },
            { text: "وَثَمُودَا۟ فَمَآ أَبْقَىٰ", tafsir: `أهلك ( ثَمُودَ ) قوم صالح ( فَما أَبْقى ) أحدا من الفريقين ، حيث عصوا وعتوا وكان جزاؤهم العذاب.` },
            { text: "وَقَوْمَ نُوحٍ مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ هُمْ أَظْلَمَ وَأَطْغَىٰ", tafsir: `أهلك ( قَوْمَ نُوحٍ مِنْ قَبْلُ ) قبل عاد وثمود ( إِنَّهُمْ كانُوا هُمْ أَظْلَمَ ) أكثر ظلما ( وَأَطْغى ) أكثر طغيانا فقد ورد أنهم كانوا يضربون نوحا عليه‌السلام حتى يبقى ليس به حراك ، فهم ظالمون لأنفسهم طاغون على غيرهم وقد دعاهم ألف سنة إلا خمسين عاما فلم ينفع فيهم.` },
            { text: "وَٱلْمُؤْتَفِكَةَ أَهْوَىٰ", tafsir: `وهي قرى قوم لوط عليه‌السلام التي ائتفكت بأهلها أي انقلبت ( أَهْوى ) بها وقلّبها بعد أن رفعها.` },
            { text: "فَغَشَّىٰهَا مَا غَشَّىٰ", tafsir: `أحاط بتلك القرى من العذاب ( ما غَشَّى ) الشيء الذي غشاها من أصناف العذاب الذي لا يوصف. [56] وبعد كل هذه العذابات التي تعلم بها ، مما أصاب العصاة ( فَبِأَيِّ آلاءِ ) نعم ( رَبِّكَ ) يا أيها الإنسان ( تَتَمارى ) تتشكك ، أليس وجود الأنبياء نعمة ؟ أليس إنزال الكتب نعمة ، أليس إرشاد العقل إلى الصحيح والباطل نعمة ؟ وهل شك في هذه النعم التي من أخذ بمقتضاها سعد ، ومن ترك مقتضاها شقي وعذب ، حتى إنك تشك هذا نَذِيرٌ مِنَ النُّذُرِ الْأُولى (56) أَزِفَتِ الْآزِفَةُ (57) لَيْسَ لَها مِنْ دُونِ اللهِ كاشِفَةٌ (58) أَفَمِنْ هذَا الْحَدِيثِ تَعْجَبُونَ (59) وتعصي وتترك الأوامر.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ", tafsir: `` },
            { text: "هَٰذَا نَذِيرٌ مِّنَ ٱلنُّذُرِ ٱلْأُولَىٰٓ", tafsir: `القرآن ( نَذِيرٌ ) ينذركم من عذاب الله لمن عصي ( مِنَ النُّذُرِ الْأُولى ) من جنس الإنذارات السابقة التي بعثنا بها إلى الأمم السابقين ، ومن المحتمل أن يكون المراد بهذا الرسول صلى‌الله‌عليه‌وآله‌وسلم فهو نذير من جنس المنذرين « الرسل » السابقين. [58] لقد ( أَزِفَتِ ) قربت ( الْآزِفَةُ ) القيامة التي هي قريبة إلى كل من جاء إلى دار الدنيا ، فإن الإنسان خلق جسمه الذي هو من التراب ، قبل مئات الألوف من السنوات ، وقد خلق الله الأرواح قبل الأجساد بألفي عام ، فإذا جاء إلى دار الدنيا فقد قرب موته ، وإذا مات الإنسان قامت قيامته ، أو المراد القيامة الحقيقية ، لأن أكثر عمر الدنيا قد انقضى ـ كما دل على ذلك الآثار والعلم الحديث ـ .` },
            { text: "أَزِفَتِ ٱلْـَٔازِفَةُ", tafsir: `` },
            { text: "لَيْسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ", tafsir: `للآزفة ( مِنْ دُونِ اللهِ ) أحد غير الله ( كاشِفَةٌ ) نفس قادرة على كشفها والإتيان بها ، فإن القيامة شيء مخفي ، فإذا أقامها الله سبحانه فقد كشفها ، والمراد الكناية عن أن القيامة بيد الله تعالى. [60] إذن فاللازم على هؤلاء من خوف عقاب الدنيا ـ كما في الآيات السابقة ـ ومن خوف عقاب الآخرة ـ كما في هاتين الآيتين ـ أن يؤمنوا ويخافوا ويعملوا صالحا ، ولكنهم سادرون في غيّهم ( أَ فَمِنْ هذَا الْحَدِيثِ ) حديث التوحيد والنبوة والمعاد مما جاء به النبي صلى‌الله‌عليه‌وآله‌وسلم ( تَعْجَبُونَ ) ؟ وقد كان اللازم أن لا تعجبوا ، لأنه قد قامت الحجة عليه. وَتَضْحَكُونَ وَلا تَبْكُونَ (60) وَأَنْتُمْ سامِدُونَ (61) فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا (62)` },
            { text: "أَفَمِنْ هَٰذَا ٱلْحَدِيثِ تَعْجَبُونَ", tafsir: `` },
            { text: "وَتَضْحَكُونَ وَلَا تَبْكُونَ", tafsir: `استهزاء ( وَلا تَبْكُونَ ) ندما وحزنا على ما سلف منكم من الكفر والآثام ، وحزنا على ما يأتي من عقاب الدنيا والآخرة.` },
            { text: "وَأَنتُمْ سَٰمِدُونَ", tafsir: `لاهون وهذه الاستفهامات استنكارية.` },
            { text: "فَٱسْجُدُوا۟ لِلَّهِ وَٱعْبُدُوا۟", tafsir: `` }
        ]
    },
    54: { // سورة القمر
        name: "القمر",
        basmalaTafsir: ``,
        verses: [
            { text: "ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ", tafsir: `القيامة ، وفيها احتمالان كما تقدم في آخر السورة السابقة في « أزفت الآزفة » أو المراد أنه ليس بعد رسول الله صلى‌الله‌عليه‌وآله‌وسلم إلا الساعة ، فقد انتهت نبوات السماء به صلى‌الله‌عليه‌وآله‌وسلم ( وَانْشَقَّ الْقَمَرُ ) الذي هو من علامات اقتراب الساعة ، وقد كان ذلك معجزة لرسول الله صلى‌الله‌عليه‌وآله‌وسلم في قصة طويلة ، وقد نقل كتاب « الإسلام يتحدى » ذكر بعض التواريخ الغابرة رؤية الناس لهذا الانشقاق ، كما ذكرت بعض الجرائد الكويتية ـ بعد نزول الغربيين على القمر ـ رؤيتهم مكان الانشقاق كأنه صار نصفين ثم التحم ـ مع أنهم مسيحيون لا يؤمنون بنبوة محمد صلى‌الله‌عليه‌وآله‌وسلم ـ .` },
            { text: "وَإِن يَرَوْا۟ ءَايَةً يُعْرِضُوا۟ وَيَقُولُوا۟ سِحْرٌ مُّسْتَمِرٌّ", tafsir: `هؤلاء الكفار المعاندون ( آيَةً ) معجزة تدل على صدق الرسول صلى‌الله‌عليه‌وآله‌وسلم ( يُعْرِضُوا ) عنها ولا يقبلونها ( وَيَقُولُوا ) إن ما يأتي به محمد صلى‌الله‌عليه‌وآله‌وسلم من الآيات ( سِحْرٌ مُسْتَمِرٌّ ) فهو يأتي بالسحر على سبيل الاستمرار.` },
            { text: "وَكَذَّبُوا۟ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ وَكُلُّ أَمْرٍ مُّسْتَقِرٌّ", tafsir: `بالحق لما جاءهم ( وَاتَّبَعُوا أَهْواءَهُمْ ) ما قرر عليهم الهوى والميل النفساني ، لا ما قرره عليهم عقلهم ( وَكُلُّ أَمْرٍ مُسْتَقِرٌّ ) وكل أمر لا بد وأن ينتهي إلى محل استقراره ، وهذا تهديد لهم ، أي أن تكذيبهم لا بد وأن ينتهي إلى عاقبة سيئة لهم.` },
            { text: "وَلَقَدْ جَآءَهُم مِّنَ ٱلْأَنۢبَآءِ مَا فِيهِ مُزْدَجَرٌ", tafsir: `أي الأخبار بالله وبالآخرة ، وبجزاء المحسن ما فِيهِ مُزْدَجَرٌ (4) حِكْمَةٌ بالِغَةٌ فَما تُغْنِ النُّذُرُ (5) فَتَوَلَّ عَنْهُمْ يَوْمَ يَدْعُ الدَّاعِ إِلى شَيْءٍ نُكُرٍ (6) خُشَّعاً أَبْصارُهُمْ يَخْرُجُونَ مِنَ الْأَجْداثِ كَأَنَّهُمْ جَرادٌ مُنْتَشِرٌ (7) مُهْطِعِينَ إِلَى الدَّاعِ حسنا والمسيء سيئا ( ما فِيهِ ) كفاية و ( مُزْدَجَرٌ ) ازدجار ، مصدر ميمي ، فلو أنهم كانوا من أهل العقل والحكمة لكفاهم ما ذكرنا لهم من الوعيد ازدجارا. [6] ذلك الذي قلناه لهم من الأنباء ( حِكْمَةٌ بالِغَةٌ ) بلغتهم ، وقد كانت حكمة بوضع الشيء في موضعه ولكن ( فَما تُغْنِ ) ما تفيد ( النُّذُرُ ) الإنذارات ، بالنسبة إلى من يتعامى عنها.` },
            { text: "حِكْمَةٌۢ بَٰلِغَةٌ فَمَا تُغْنِ ٱلنُّذُرُ", tafsir: `` },
            { text: "فَتَوَلَّ عَنْهُمْ يَوْمَ يَدْعُ ٱلدَّاعِ إِلَىٰ شَىْءٍ نُّكُرٍ", tafsir: `أعرض يا رسول الله ( عَنْهُمْ ) من بعد أن أبلغت وأنذرت ، ولم يقبلوا ، لأن الإنذار لا ينفع فيهم فما أهول ما ينتظرهم من العذاب في ( يَوْمَ يَدْعُ الدَّاعِ ) الداعي الذي يدعوهم عند البعث ، ليقوموا للحساب ( إِلى شَيْءٍ نُكُرٍ ) منكر فظيع ، وإنما كان منكرا ، لأن الإنسان لم يألفه ولم يشاهده.` },
            { text: "خُشَّعًا أَبْصَٰرُهُمْ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ كَأَنَّهُمْ جَرَادٌ مُّنتَشِرٌ", tafsir: `جمع خاشع بمعنى الذليل ( أَبْصارُهُمْ ) فإن خشوع النفس يظهر من خشوع العين ( يَخْرُجُونَ ) في أثر النداء ( مِنَ الْأَجْداثِ ) جمع جدث ، بمعنى القبور ( كَأَنَّهُمْ جَرادٌ مُنْتَشِرٌ ) في الكثرة والتموّج وعدم النظام وانتشارهم في كل مكان.` },
            { text: "مُّهْطِعِينَ إِلَى ٱلدَّاعِ يَقُولُ ٱلْكَٰفِرُونَ هَٰذَا يَوْمٌ عَسِرٌ", tafsir: `مسرعين ( إِلَى الدَّاعِ ) إلى الذي يدعوهم إلى الحساب ـ يَقُولُ الْكافِرُونَ هذا يَوْمٌ عَسِرٌ (8) كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ فَكَذَّبُوا عَبْدَنا وَقالُوا مَجْنُونٌ وَازْدُجِرَ (9) فَدَعا رَبَّهُ أَنِّي مَغْلُوبٌ فَانْتَصِرْ (10) فَفَتَحْنا أَبْوابَ السَّماءِ بِماءٍ مُنْهَمِرٍ (11) وَفَجَّرْنَا الْأَرْضَ عُيُوناً فَالْتَقَى الْماءُ عَلى أَمْرٍ قَدْ قُدِرَ (12) وَحَمَلْناهُ عَلى ويوم ذلك كلهم مطيعون ـ ( يَقُولُ الْكافِرُونَ هذا يَوْمٌ عَسِرٌ ) أي عسير صعب. [10] وهؤلاء الكفار بالإضافة إلى أنه ينتظرهم عذاب الآخرة ، كذلك مثلهم مثل الأقوام السابقة الذين كفروا بالأنبياء وبما جاءوا به فأخذهم عذاب الدنيا فقد ( كَذَّبَتْ قَبْلَهُمْ ) قبل قومك يا رسول الله ( قَوْمُ نُوحٍ ) فقد بغوا وطغوا وكذبوا ( عَبْدَنا ) نوحا عليه‌السلام ( وَقالُوا ) إنه ( مَجْنُونٌ ) كما يقول الكفار بالنسبة لك يا رسول الله ( وَازْدُجِرَ ) زجر نوح عليه‌السلام عن التبليغ بأنواع الأذية ، لكن نوحا عليه‌السلام استقام ولم ينصرف عن تبليغ الرسالة.` },
            { text: "كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ فَكَذَّبُوا۟ عَبْدَنَا وَقَالُوا۟ مَجْنُونٌ وَٱزْدُجِرَ", tafsir: `` },
            { text: "فَدَعَا رَبَّهُۥٓ أَنِّى مَغْلُوبٌ فَٱنتَصِرْ", tafsir: `نوح عليه‌السلام ( رَبَّهُ أَنِّي مَغْلُوبٌ ) قد غلب علي الكفار بقوتهم المادية ( فَانْتَصِرْ ) فانصرني يا رب عليهم. [12] وقد استجبنا دعاءه ( فَفَتَحْنا أَبْوابَ السَّماءِ ) مواضع نزول المطر ( بِماءٍ مُنْهَمِرٍ ) انهمر وتساقط بكثرة ، كأنه أفواه القرب.` },
            { text: "فَفَتَحْنَآ أَبْوَٰبَ ٱلسَّمَآءِ بِمَآءٍ مُّنْهَمِرٍ", tafsir: `` },
            { text: "وَفَجَّرْنَا ٱلْأَرْضَ عُيُونًا فَٱلْتَقَى ٱلْمَآءُ عَلَىٰٓ أَمْرٍ قَدْ قُدِرَ", tafsir: `حتى كأنها لها عيون ( فَالْتَقَى الْماءُ ) ماء السماء وماء الأرض ( عَلى أَمْرٍ ) هو إغراق قوم نوح عليه‌السلام ( قَدْ قُدِرَ ) قدّره الله سبحانه وحكم به.` },
            { text: "وَحَمَلْنَٰهُ عَلَىٰ ذَاتِ أَلْوَٰحٍ وَدُسُرٍ", tafsir: `أركبنا نوحا عليه‌السلام ومن معه من المؤمنين ( عَلى ) سفينة ذاتِ أَلْواحٍ وَدُسُرٍ (13) تَجْرِي بِأَعْيُنِنا جَزاءً لِمَنْ كانَ كُفِرَ (14) وَلَقَدْ تَرَكْناها آيَةً فَهَلْ مِنْ مُدَّكِرٍ (15) فَكَيْفَ كانَ عَذابِي وَنُذُرِ (16) وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ (17) كَذَّبَتْ عادٌ فَكَيْفَ كانَ عَذابِي وَنُذُرِ (18) ( ذاتِ أَلْواحٍ ) أخشاب عريضة ، جمع « لوح » ( وَدُسُرٍ ) المسامير ، فإنه جمع « دسار » بمعنى المسمار.` },
            { text: "تَجْرِى بِأَعْيُنِنَا جَزَآءً لِّمَن كَانَ كُفِرَ", tafsir: `السفينة بالمياه المحيطة بالأرض ( بِأَعْيُنِنا ) تحت نظرنا ورعايتنا ، والجمع باعتبار أن كل حركة تحتاج إلى عين ترعاها من الغرق والهلاك ، وقد فعلنا ذلك بنوح عليه‌السلام ( جَزاءً ) حسنا منا ( لِمَنْ كانَ كُفِرَ ) لنوح الذي كفر به قومه.` },
            { text: "وَلَقَد تَّرَكْنَٰهَآ ءَايَةً فَهَلْ مِن مُّدَّكِرٍ", tafsir: `أبقينا خبر نوح وقومه ( آيَةً ) علامة يعتبر بها العقلاء ( فَهَلْ مِنْ مُدَّكِرٍ ) هل هناك من يعتبر بالقصة ؟ المبلغ يعتبر به فلا يهمه تكذيب الناس ، والناس يعتبرون فلا يكذبون المبلغين لأن عاقبتهم تكون سيئة.` },
            { text: "فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ", tafsir: `للمكذبين ( وَنُذُرِ ) إنذاراتي لهم ، ألم تكن عاقبة المكذبين العذاب كما وعدتهم ؟ [18] وهل يريدون أوضح بيانا من هذا الذي ذكرناه وخوفناهم به ؟ ( وَلَقَدْ يَسَّرْنَا ) سهّلنا ( الْقُرْآنَ لِلذِّكْرِ ) ليتذكر به الناس ( فَهَلْ مِنْ مُدَّكِرٍ ) من يتذكر ويتعظ ؟ استفهام تحريضي ، و « مدّكر » من « ادّكر » أصله « تذكّر » . [19] وبعد قوم نوح عليه‌السلام ( كَذَّبَتْ عادٌ ) قبيلة عاد وهم قوم هود عليه‌السلام ، فعذبناهم بتكذيبهم ( فَكَيْفَ كانَ عَذابِي وَنُذُرِ ) ؟ أليس في تكرار إِنَّا أَرْسَلْنا عَلَيْهِمْ رِيحاً صَرْصَراً فِي يَوْمِ نَحْسٍ مُسْتَمِرٍّ (19) تَنْزِعُ النَّاسَ كَأَنَّهُمْ أَعْجازُ نَخْلٍ مُنْقَعِرٍ (20) فَكَيْفَ كانَ عَذابِي وَنُذُرِ (21) وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ (22) العذاب لكل قوم كذبوا ، وعظا لكفار قريش ؟ فليس لهم أن يقولوا أن عذاب قوم نوح كان من القضايا الاتفاقية.` },
            { text: "وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ", tafsir: `` },
            { text: "كَذَّبَتْ عَادٌ فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ", tafsir: `` },
            { text: "إِنَّآ أَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِى يَوْمِ نَحْسٍ مُّسْتَمِرٍّ", tafsir: `على عاد ( رِيحاً صَرْصَراً ) باردة شديدة البرد ( فِي يَوْمِ نَحْسٍ ) شؤم عليهم ( مُسْتَمِرٍّ ) استمر العذاب عليهم في ذلك اليوم حتى أهلكهم.` },
            { text: "تَنزِعُ ٱلنَّاسَ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ مُّنقَعِرٍ", tafsir: `تقلع تلك الريح ( النَّاسَ ) قوم عاد ، من أماكنهم في الغرف وغيرها وكانت تفتح الأبواب وتخرج الناس إلى الساحات وترفعهم عن الأرض ثم تضربهم بها ، وكانت تقلع رؤوسهم عن أجسادهم فبقيت أجسادهم ( كَأَنَّهُمْ أَعْجازُ ) أصول ( نَخْلٍ مُنْقَعِرٍ ) منقلع عن مغارسه ، ولعلهم كانوا يلوون على أنفسهم من شدة الألم ولأن يجمعوا أنفسهم في قبال الريح ، ولذا شبهوا بأعجاز النخل.` },
            { text: "فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ", tafsir: `؟ لعل وجه التكرار لأجل أن مثل هذا العذاب لا يمكن أن يحمل على أنه طبيعي ، وإن أمكن ذلك في الغرق.` },
            { text: "وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ", tafsir: `فلم نجعله كالكتب الفلسفية التي لا يفهمها الإنسان إلا بصعوبة بالغة ( فَهَلْ مِنْ مُدَّكِرٍ ) ؟ من يتذكر فلا يعصي حتى لا يعذب كما عذب الأمم السابقة. كَذَّبَتْ ثَمُودُ بِالنُّذُرِ (23) فَقالُوا أَ بَشَراً مِنَّا واحِداً نَتَّبِعُهُ إِنَّا إِذاً لَفِي ضَلالٍ وَسُعُرٍ (24) أَأُلْقِيَ الذِّكْرُ عَلَيْهِ مِنْ بَيْنِنا بَلْ هُوَ كَذَّابٌ أَشِرٌ (25) سَيَعْلَمُونَ غَداً مَنِ الْكَذَّابُ الْأَشِرُ (26) إِنَّا مُرْسِلُوا النَّاقَةِ` },
            { text: "كَذَّبَتْ ثَمُودُ بِٱلنُّذُرِ", tafsir: `قبيلة ( ثَمُودُ ) قوم صالح عليه‌السلام ( بِالنُّذُرِ ) جمع نذير أي الأنبياء إذ تكذيب نبي واحد هو تكذيب لكل الأنبياء.` },
            { text: "فَقَالُوٓا۟ أَبَشَرًا مِّنَّا وَٰحِدًا نَّتَّبِعُهُۥٓ إِنَّآ إِذًا لَّفِى ضَلَٰلٍ وَسُعُرٍ", tafsir: `من جنسنا أو من قبيلتنا ، لأن صالح كان من قبيلتهم ( واحِداً ) لا تبع له ( نَتَّبِعُهُ ) ونقبل كلامه ؟ هذا لا يكون ( إِنَّا إِذاً ) إذا اتبعنا بشرا واحدا ( لَفِي ضَلالٍ ) عن طريقة آبائنا ( وَسُعُرٍ ) جمع سعير ، أي نحرق بناره ، كما يقال فلان أحرق نفسه أي سبّب ضياع نفسه وماله ومستقبله ، إنهم ما كانوا يقتنعون بالبرهان ، بل كانوا يريدون أن يكون الهادي لهم من جنس أعلى كالملائكة لا « منا » أو لهم جماعة وسطوة وشوكة مثل أن يكون ملكا أو رئيس عشيرة.` },
            { text: "أَءُلْقِىَ ٱلذِّكْرُ عَلَيْهِ مِنۢ بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌ", tafsir: `الكتاب والوحي ( عَلَيْهِ مِنْ بَيْنِنا ) ؟ فلما ذا لم يلق الوحي إلي من هو أكثر منه مالا أو شخصية ؟ ( بَلْ هُوَ ) صالح عليه‌السلام ( كَذَّابٌ ) كثير الكذب في نسبة الوحي إلى نفسه ( أَشِرٌ ) حمله بطره على الترفع علينا بادعائه النبوة ، فإن المترفعين لما يعتادون الإشارة إلى الناس بالاستهزاء والسوء ، اشتق من مادة الإشارة ، الأشر بهذا المعنى.` },
            { text: "سَيَعْلَمُونَ غَدًا مَّنِ ٱلْكَذَّابُ ٱلْأَشِرُ", tafsir: `حين ينزل عليهم العذاب ( مَنِ ) هو ( الْكَذَّابُ الْأَشِرُ ) هل هم الذين أكثروا من الكذب أم صالح النبي عليه‌السلام ؟.` },
            { text: "إِنَّا مُرْسِلُوا۟ ٱلنَّاقَةِ فِتْنَةً لَّهُمْ فَٱرْتَقِبْهُمْ وَٱصْطَبِرْ", tafsir: `أي الله سبحانه ( مُرْسِلُوا النَّاقَةِ ) مخرجوها من الجبل وباعثوها فِتْنَةً لَهُمْ فَارْتَقِبْهُمْ وَاصْطَبِرْ (27) وَنَبِّئْهُمْ أَنَّ الْماءَ قِسْمَةٌ بَيْنَهُمْ كُلُّ شِرْبٍ مُحْتَضَرٌ (28) فَنادَوْا صاحِبَهُمْ فَتَعاطى فَعَقَرَ (29) فَكَيْفَ كانَ عَذابِي وَنُذُرِ (30) إِنَّا أَرْسَلْنا عَلَيْهِمْ صَيْحَةً واحِدَةً فَكانُوا كَهَشِيمِ الْمُحْتَظِرِ (31) إليهم معجزة لصالح عليه‌السلام ( فِتْنَةً ) اختبارا وامتحانا ( لَهُمْ ) هل يؤمنون بالإعجاز أم لا ؟ ( فَارْتَقِبْهُمْ ) أي انتظرهم وراقبهم هل يؤمنون أم لا ؟ ( وَاصْطَبِرْ ) عليهم بالاستمرار في التبليغ وعدم الدعاء عليهم مع إيذائهم لك.` },
            { text: "وَنَبِّئْهُمْ أَنَّ ٱلْمَآءَ قِسْمَةٌۢ بَيْنَهُمْ كُلُّ شِرْبٍ مُّحْتَضَرٌ", tafsir: `أخبرهم ( أَنَّ الْماءَ ) الذي كان يجري نهرا عندهم ( قِسْمَةٌ بَيْنَهُمْ ) مقسوم للناقة يوم ولهم يوم ، فإذا شربت الناقة في يومها كل ماء النهر أعطتهم عوضه حليبا ( كُلُّ شِرْبٍ ) شرب الحصة من الماء ( مُحْتَضَرٌ ) يحضره صاحبه ولا حق لأحدهما في الماء في يوم الآخر.` },
            { text: "فَنَادَوْا۟ صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ", tafsir: `ثمود ( صاحِبَهُمْ ) وهو قدار الذي كان من شرارهم ( فَتَعاطى ) أخذ الناقة ، ولعل باب التفاعل من جهة أن قدار وجماعة منهم أخذوا زمام الناقة حتى ألجؤوها إلى مكان يمكن عقرها ( فَعَقَرَ ) قدار الناقة أي جرحها وقتلها.` },
            { text: "فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ", tafsir: `؟ هل تركت عذابهم لما خالفوا وكذبوا أم أخذتهم بالعذاب ؟.` },
            { text: "إِنَّآ أَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَٰحِدَةً فَكَانُوا۟ كَهَشِيمِ ٱلْمُحْتَظِرِ", tafsir: `صاح بهم جبرائيل عليه‌السلام فانخلعت بذلك قلوبهم ( فَكانُوا كَهَشِيمِ الْمُحْتَظِرِ ) كالحشيش اليابس الذي يجمعه صاحب الماشية في الشتاء في حظيرته ، ولعل وجه التشبيه ، أنه وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ (32) كَذَّبَتْ قَوْمُ لُوطٍ بِالنُّذُرِ (33) إِنَّا أَرْسَلْنا عَلَيْهِمْ حاصِباً إِلاَّ آلَ لُوطٍ نَجَّيْناهُمْ بِسَحَرٍ (34) نِعْمَةً مِنْ عِنْدِنا كَذلِكَ نَجْزِي مَنْ شَكَرَ (35) تقطعت أيديهم وأرجلهم وتكوّمت الأبدان والأيدي والأرجل في مكان ، كما يتكوّم الهشيم المتكسر المجتمع.` },
            { text: "وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ", tafsir: `لا يقال في القرآن متشابهات ، لأنه يقال عامة القرآن ميسرة وبعض الآيات المتشابهات لا يضر بالعموم من حيث العموم.` },
            { text: "كَذَّبَتْ قَوْمُ لُوطٍۭ بِٱلنُّذُرِ", tafsir: `فلم يقبلوا إنذار لوط عليه‌السلام وتكذيب لوط تكذيب لسائر الأنبياء.` },
            { text: "إِنَّآ أَرْسَلْنَا عَلَيْهِمْ حَاصِبًا إِلَّآ ءَالَ لُوطٍ نَّجَّيْنَٰهُم بِسَحَرٍ", tafsir: `جزاء لتكذيبهم ( أَرْسَلْنا عَلَيْهِمْ حاصِباً ) ريحا ترميهم بالحجارة يقال حصبه أي رماه بالحجارة ( إِلَّا آلَ لُوطٍ ) لوط وأهل بيته المؤمنين « باستثناء زوجته فإنها أصابها ما أصاب القوم لأنها كانت كافرة مثلهم » ( نَجَّيْناهُمْ بِسَحَرٍ ) في آخر الليل. [36] وإنما نجيناهم ( نِعْمَةً ) لهم ( مِنْ عِنْدِنا ) إذ كان من الممكن إماتتهم في ذلك الحال ، بدون عذاب ، كما يموت كل خير في زمان ما ( كَذلِكَ ) هكذا ، كما جزينا آل لوط عليه‌السلام ( نَجْزِي مَنْ شَكَرَ ) نعمتنا عليه ، بالإيمان والطاعة ، والمراد الشكر القلبي والشكر العملي. [37] وقد قدم سبحانه عذابهم على ذكر بلاغ لوط لهم ، لبيان أن العذاب وَلَقَدْ أَنْذَرَهُمْ بَطْشَتَنا فَتَمارَوْا بِالنُّذُرِ (36) وَلَقَدْ راوَدُوهُ عَنْ ضَيْفِهِ فَطَمَسْنا أَعْيُنَهُمْ فَذُوقُوا عَذابِي وَنُذُرِ (37) وَلَقَدْ صَبَّحَهُمْ بُكْرَةً عَذابٌ مُسْتَقِرٌّ (38) فَذُوقُوا عَذابِي وَنُذُرِ (39) يأخذ المعتدين بسرعة حتى كأن بقاءهم في الحياة لمحة عين ( وَلَقَدْ أَنْذَرَهُمْ ) لوط عليه‌السلام ( بَطْشَتَنا ) أخذنا الشديد بالعذاب لمن خالف أوامرنا ( فَتَمارَوْا ) فتشككوا من المماراة أي المجادلة ( بِالنُّذُرِ ) وأخذوا يجادلون بالباطل حول صدق لوط.` },
            { text: "نِّعْمَةً مِّنْ عِندِنَا كَذَٰلِكَ نَجْزِى مَن شَكَرَ", tafsir: `` },
            { text: "وَلَقَدْ أَنذَرَهُم بَطْشَتَنَا فَتَمَارَوْا۟ بِٱلنُّذُرِ", tafsir: `` },
            { text: "وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُوا۟ عَذَابِى وَنُذُرِ", tafsir: `لم يقتنعوا بتكذيبه والاستمرار في فحشائهم ، بل أضافوا على ذلك أنهم ( لَقَدْ راوَدُوهُ عَنْ ضَيْفِهِ ) المراودة ، الرواح والمجيء ، فقد جاء آل لوط ضيوف ، فأراد قومه أن يلوطوا بهم ، وكان أولئك الضيوف هم الملائكة ( فَطَمَسْنا أَعْيُنَهُمْ ) فمسحناها وسويناها بسائر الوجه حتى عميت عيونهم وشوهت خلقتهم فقلنا لهم ( فَذُوقُوا عَذابِي وَنُذُرِ ) أي ذوقوا عاقبة إنذاري لكم ، أو المراد كأن لسان الحال يقول لهم « ذوقوا .. . » .` },
            { text: "وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌ مُّسْتَقِرٌّ", tafsir: `دخل العذاب عليهم في الصباح الباكر ، والبكرة أول الصبح ، ودخول العذاب في ذلك الوقت أنكر ، لأنهم يرجون خير النهار فإذا بهم يجدون انهدام الآمال بالعذاب ( مُسْتَقِرٌّ ) فلم يكن عذابا عابرا ، بل عذاب استقر بهم حتى أهلكهم.` },
            { text: "فَذُوقُوا۟ عَذَابِى وَنُذُرِ", tafsir: `وفائدة التكرار تكرار التذكير ومن الواضح أنه قد يؤثر التكرار ما لا يؤثر غيره ، وذلك لاستيعاب الذهن له ، ولذا إذا أراد الإنسان أن يحفظ شيئا كرره مرات. وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ مُدَّكِرٍ (40) وَلَقَدْ جاءَ آلَ فِرْعَوْنَ النُّذُرُ (41) كَذَّبُوا بِآياتِنا كُلِّها فَأَخَذْناهُمْ أَخْذَ عَزِيزٍ مُقْتَدِرٍ (42) أَ كُفَّارُكُمْ خَيْرٌ مِنْ أُولئِكُمْ أَمْ لَكُمْ بَراءَةٌ فِي الزُّبُرِ (43)` },
            { text: "وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ", tafsir: `لا يقال غير العرب لا يستفيدون من القرآن ، لأنه يقال ، قصد الإسلام توحيد لغة الناس ، لأجل تفاهم عام ولأجل إرساء دعائم حكومة واحدة ـ بما فيها من الفوائد الجمة ـ ومثل ذلك يوجب يسر القرآن للكل.` },
            { text: "وَلَقَدْ جَآءَ ءَالَ فِرْعَوْنَ ٱلنُّذُرُ", tafsir: `آل فلان يستعمل له ولآله ، أي فرعون وآله ( النُّذُرُ ) المنذرون مثل موسى وهارون ومؤمن آل فرعون ، ولعل أنبياء آخرين أيضا كانوا ، لما ورد في الأحاديث أن موسى عليه‌السلام حج مع سبعين نبيا.` },
            { text: "كَذَّبُوا۟ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذْنَٰهُمْ أَخْذَ عَزِيزٍ مُّقْتَدِرٍ", tafsir: `الكثيرة ( كُلِّها ) كاليد والعصا والقمل والضفادع والدم وغيرها ، ولعل المجيء بدون « الواو » لإفادة فورية التكذيب بلا تروّ ( فَأَخَذْناهُمْ ) بالغرق ( أَخْذَ عَزِيزٍ ) له العزة والغلبة ( مُقْتَدِرٍ ) له القدرة ، لأن القدرة قد تكون مع الذلة عند الناس ، وقد تكون مع العزة.` },
            { text: "أَكُفَّارُكُمْ خَيْرٌ مِّنْ أُو۟لَٰٓئِكُمْ أَمْ لَكُم بَرَآءَةٌ فِى ٱلزُّبُرِ", tafsir: `يا معشر قريش ( خَيْرٌ مِنْ أُولئِكُمْ ) من أولئك الكفار للأمم السابقة حتى نترككم مع تكذيبكم ، وقد سمعتم كيف أخذنا أولئك الكفار ؟ ( أَمْ لَكُمْ بَراءَةٌ فِي الزُّبُرِ ) في الكتب ، بأن كنا أعطيناكم عهدا في كتب الأنبياء أن لا نهلككم ؟ وإذ لا ذاك ، ولا هذا ، فاللازم أن أَمْ يَقُولُونَ نَحْنُ جَمِيعٌ مُنْتَصِرٌ (44) سَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ (45) بَلِ السَّاعَةُ مَوْعِدُهُمْ وَالسَّاعَةُ أَدْهى وَأَمَرُّ (46) إِنَّ الْمُجْرِمِينَ فِي ضَلالٍ وَسُعُرٍ (47) يَوْمَ تخافوا من بطشنا وأن نفعل بكم ما فعلنا بتلك الأمم الكافرة.` },
            { text: "أَمْ يَقُولُونَ نَحْنُ جَمِيعٌ مُّنتَصِرٌ", tafsir: `هؤلاء الكفار ( نَحْنُ جَمِيعٌ ) مجتمع ( مُنْتَصِرٌ ) ننتصر ونتغلب على من أراد بنا هلاكا ؟ وهل يمكن التغلب على إرادة الله ؟.` },
            { text: "سَيُهْزَمُ ٱلْجَمْعُ وَيُوَلُّونَ ٱلدُّبُرَ", tafsir: `سيهزمون إذا جاءهم عذاب الله ولا يفيدهم جمعهم ( وَيُوَلُّونَ الدُّبُرَ ) فلا يقفون وجها لوجه أمام العذاب ، بل يعطون العذاب قفاهم ويفرون ، فلا يفيدهم جمعهم. [47] هذا إذا أرسلنا عليهم العذاب في الدنيا ( بَلِ السَّاعَةُ ) القيامة ( مَوْعِدُهُمْ ) موعد عقوبتهم الحقيقية وعذابهم الأصلي ( وَالسَّاعَةُ أَدْهى ) أشد عذابا لهم من عذاب الدنيا ( وَأَمَرُّ ) أكثر مرارة في مذاقهم ، والداهية الأمر المنكر الذي لا يهتدي الإنسان لدوائه.` },
            { text: "بَلِ ٱلسَّاعَةُ مَوْعِدُهُمْ وَٱلسَّاعَةُ أَدْهَىٰ وَأَمَرُّ", tafsir: `` },
            { text: "إِنَّ ٱلْمُجْرِمِينَ فِى ضَلَٰلٍ وَسُعُرٍ", tafsir: `بالإضافة إلى عذابهم في الدنيا والآخرة ، هم ( فِي ضَلالٍ ) عن الحق ، وهذا ما يولد لهم نوعا من المشاكل المادية ، لأن غير طريق الحق فيه مشاكل وأتعاب ( وَسُعُرٍ ) جمع سعير ، لأنهم يستعرون نفسيا بما يرتطمون فيه من المشاكل فهم في قلق نفسي واضطراب وعدم سكينة ، فإن الاطمئنان النفسي للمؤمنين فقط ، أو المراد ضلال الدنيا وسعير الآخرة.` },
            { text: "يَوْمَ يُسْحَبُونَ فِى ٱلنَّارِ عَلَىٰ وُجُوهِهِمْ ذُوقُوا۟ مَسَّ سَقَرَ", tafsir: `بيان لموعدهم في الساعة ، أو ما بينه بقوله « سعر » يُسْحَبُونَ فِي النَّارِ عَلى وُجُوهِهِمْ ذُوقُوا مَسَّ سَقَرَ (48) إِنَّا كُلَّ شَيْءٍ خَلَقْناهُ بِقَدَرٍ (49) وَما أَمْرُنا إِلاَّ واحِدَةٌ كَلَمْحٍ بِالْبَصَرِ (50) و َلَقَدْ أَهْلَكْنا أَشْياعَكُمْ ( يُسْحَبُونَ ) يجرون ( فِي النَّارِ عَلى وُجُوهِهِمْ ) فإنهم لما لم تخضع وجوههم للحق ، جوزوا بإذلال وجوههم في النار ، ويقال لهم زيادة في إهانتهم من جهة الشماتة ( ذُوقُوا مَسَّ سَقَرَ ) مسّه ، أي أصابه ، وسقر علم على جهنم. [50] وحيث إن الكفار كانوا يقولون : ائتنا بعذاب الله إن كنت صادقا ، أجابهم القرآن ( إِنَّا كُلَّ شَيْءٍ خَلَقْناهُ ) أي جعلناه ( بِقَدَرٍ ) بتقدير خاص ، فيوم القيامة ، وعذاب هؤلاء ، يأتي في الوقت المقدر لهما ، ولا نقدم العذاب حسب طلبهم فكما أن كل بذرة تعطي ثمرا ، فللثمرة بين زرعها وبين إثمارها زمان مقدر ، كذلك كل عمل إلى أن يعطي ثمره وجزاءه له وقت مقدر خاص. [51] لكن إذا حان الوقت المقدر ، فلا تراجع فيه ولا بطء فيه ( وَما أَمْرُنا ) بعذابهم أو بغير ذلك ( إِلَّا واحِدَةٌ ) فلا حاجة للتكرار في الأمر ، كما لا تراجع منه إذا أمرنا وهو ( كَلَمْحٍ بِالْبَصَرِ ) حركة البصر ، في السرعة فلا يحتاج إلى مقدمات فيجب أن يعرف هؤلاء الكفار أنه إذا حان عذابهم لا تراجع فيه ، كما أنه لا يأخذهم تدريجيا ليفكروا في الخلاص بل يأخذهم بغتة.` },
            { text: "إِنَّا كُلَّ شَىْءٍ خَلَقْنَٰهُ بِقَدَرٍ", tafsir: `` },
            { text: "وَمَآ أَمْرُنَآ إِلَّا وَٰحِدَةٌ كَلَمْحٍۭ بِٱلْبَصَرِ", tafsir: `` },
            { text: "وَلَقَدْ أَهْلَكْنَآ أَشْيَاعَكُمْ فَهَلْ مِن مُّدَّكِرٍ", tafsir: `أشباهكم من الأمم ، وقد عرفتم كيف لم نتراجع حين أردنا عذابهم وكيف لم نتدرج في عذابهم بل أخذناهم فَهَلْ مِنْ مُدَّكِرٍ (51) وَكُلُّ شَيْءٍ فَعَلُوهُ فِي الزُّبُرِ (52) وَكُلُّ صَغِيرٍ وَكَبِيرٍ مُسْتَطَرٌ (53) إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَهَرٍ (54) فِي مَقْعَدِ صِدْقٍ عِنْدَ مَلِيكٍ مُقْتَدِرٍ (55) دفعة واحدة ( فَهَلْ مِنْ مُدَّكِرٍ ) مدّكر يتذكر ، حتى يرجع عن غيه ؟. [53] ولم ننس حتى أصغر شيء فعلوه فعاقبناهم بكل ما ارتكبوا من جرائم ( وَكُلُّ شَيْءٍ فَعَلُوهُ ) مكتوب ( فِي الزُّبُرِ ) كتبه الحفظة.` },
            { text: "وَكُلُّ شَىْءٍ فَعَلُوهُ فِى ٱلزُّبُرِ", tafsir: `` },
            { text: "وَكُلُّ صَغِيرٍ وَكَبِيرٍ مُّسْتَطَرٌ", tafsir: `من أعمالهم ، كما هو كذلك في كل أعمال البشر ( مُسْتَطَرٌ ) مسطور مكتوب.` },
            { text: "إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍ وَنَهَرٍ", tafsir: `جمع نهر بسكون الهاء ، ولعل المراد انهم يسبحون في أنهار الجنة ، والظرف مجاز.` },
            { text: "فِى مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍ مُّقْتَدِرٍۭ", tafsir: `` }
        ]
    },
    55: { // سورة الرحمن
        name: "الرحمن",
        basmalaTafsir: ``,
        verses: [
            { text: "ٱلرَّحْمَٰنُ", tafsir: `لأنه رحمن « فإن تعليق الأمر على الصفة يفيد العلية » .` },
            { text: "عَلَّمَ ٱلْقُرْءَانَ", tafsir: `إذ لو لا رحمه لم يعلم القرآن وترك البشر في دياجير الظلام.` },
            { text: "خَلَقَ ٱلْإِنسَٰنَ", tafsir: `أخّر الخلق ، عن التعليم مع أنه مقدم على التعليم زمانا ، للدلالة على جلالة العلم حتى أنه لو لا العلم لكان خلق الإنسان قليل الفائدة.` },
            { text: "عَلَّمَهُ ٱلْبَيَانَ", tafsir: `بأن يتكلم ويظهر ما في ضميره. [6] وإذ ذكر القرآن الإنسان بالنعم التي تدل على علم الله وقدرته ودقة حكمه ، جاء الدور للتنبيه على أنه لا مكان للعبثية والاعتباط في الخلق ( الشَّمْسُ وَالْقَمَرُ بِحُسْبانٍ ) قد خلقا ويجريان بحساب معلوم مقدر بلا زيادة ولا نقيصة.` },
            { text: "ٱلشَّمْسُ وَٱلْقَمَرُ بِحُسْبَانٍ", tafsir: `` },
            { text: "وَٱلنَّجْمُ وَٱلشَّجَرُ يَسْجُدَانِ", tafsir: `الموجود في السماء ، والذي ينجم أي يظهر في الأفق ( وَالشَّجَرُ ) الذي ينجم أي يظهر من الأرض ( يَسْجُدانِ ) خاضعان لله سبحانه ، ويسجد ليس بمعنى المستقبل ، بل بمعنى الحال أي دائما ، أو المراد سجودهما ، إذ لكل شيء معرفة بالله ونوع خضوع له ، وفي جملة من التفاسير ، إن المراد بالنجم النبات الذي لا ساق له ، في مقابل الشجر الذي له ساق.` },
            { text: "وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلْمِيزَانَ", tafsir: `الله سبحانه ، سواء أريد به المدارات أو الجزئيات ، وَوَضَعَ الْمِيزانَ (7) أَلاَّ تَطْغَوْا فِي الْمِيزانِ (8) وَأَقِيمُوا الْوَزْنَ بِالْقِسْطِ وَلا تُخْسِرُوا الْمِيزانَ (9) وَالْأَرْضَ وَضَعَها لِلْأَنامِ (10) فِيها فاكِهَةٌ وَالنَّخْلُ ذاتُ الْأَكْمامِ (11) وَالْحَبُّ ذُو الْعَصْفِ أو الأنجم ( وَوَضَعَ ) أي جعل وإنما أتى بهذا اللفظ ، ليجعل المقابلة بين الرفع والوضع ( الْمِيزانَ ) ليوفي كل ذي حق حقه ، ففي القضايا التكوينية عدل وحساب دقيق ، وكذلك جعل سبحانه للتعامل بين الناس عدلا وحسابا. [9] وإنما وضع الميزان ل ـ ( أَلَّا تَطْغَوْا ) وتجوروا ( فِي الْمِيزانِ ) في وزن الأشياء إذ لو لم يكن الميزان الذي به توزن الأشياء لحصل الجور في وزن الأشياء. [10] لكن قسما من الناس أيضا يجورون مع وجود الميزان ، بالاحتيال والتطفيف ولذا قال الله سبحانه ( وَأَقِيمُوا الْوَزْنَ بِالْقِسْطِ ) بالعدل ( وَلا تُخْسِرُوا الْمِيزانَ ) أي لا تنقصوه ، والمراد ما في الميزان بعلاقة الحال والمحل.` },
            { text: "أَلَّا تَطْغَوْا۟ فِى ٱلْمِيزَانِ", tafsir: `` },
            { text: "وَأَقِيمُوا۟ ٱلْوَزْنَ بِٱلْقِسْطِ وَلَا تُخْسِرُوا۟ ٱلْمِيزَانَ", tafsir: `` },
            { text: "وَٱلْأَرْضَ وَضَعَهَا لِلْأَنَامِ", tafsir: `إذا تقدم ذكر السماء فلنذكر ما يقابل نعمة السماء من نعمة الأرض فإن ( الْأَرْضَ وَضَعَها ) الله ( لِلْأَنامِ ) لفائدتهم أحياء وأمواتا.` },
            { text: "فِيهَا فَٰكِهَةٌ وَٱلنَّخْلُ ذَاتُ ٱلْأَكْمَامِ", tafsir: `إما الثمار أو كل ما يتفكه به ( وَالنَّخْلُ ذاتُ الْأَكْمامِ ) الكم وعاء التمر ، و « ذات » باعتبار جنس النخل.` },
            { text: "وَٱلْحَبُّ ذُو ٱلْعَصْفِ وَٱلرَّيْحَانُ", tafsir: `كالحنطة والشعير ( ذُو الْعَصْفِ ) ورق الزرع ، سمي به وَالرَّيْحانُ (12) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (13) خَلَقَ الْإِنْسانَ مِنْ صَلْصالٍ كَالْفَخَّارِ (14) وَخَلَقَ الْجَانَّ مِنْ مارِجٍ مِنْ نارٍ (15) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (16) رَبُّ الْمَشْرِقَيْنِ وَرَبُّ الْمَغْرِبَيْنِ (17) لأنه يعصف به أي يتحرك ، ومنه « العاصفة » بمعنى الريح الشديدة ( وَالرَّيْحانُ ) ما يستشم به من الأوراد ونحوها.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `جمع « إلى » بمعنى النعمة ( رَبِّكُما ) أيها الجن والإنس ، بقرينة « للأنام » و « أيها الثقلان » ( تُكَذِّبانِ ) فإن تكذيبهم برب النعمة وإنكارهم له ، كفران للنعمة ، وتكذيب لربط النعمة برب النعمة ، وتكرار التذكير بهذه الآية ( فَبِأَيِّ آلاءِ .. . ) في مقابل كثرة تكذيبهم برب النعمة.` },
            { text: "خَلَقَ ٱلْإِنسَٰنَ مِن صَلْصَٰلٍ كَٱلْفَخَّارِ", tafsir: `الله ( الْإِنْسانَ مِنْ صَلْصالٍ ) الطين اليابس الذي له صلصلة ، أي صوت ( كَالْفَخَّارِ ) الخزف فإن الله جعل التراب طينا ولما بقي مدة صار كالحمإ المسنون ، ثم يبس وصار صلصالا ، كما في آيات متعددة.` },
            { text: "وَخَلَقَ ٱلْجَآنَّ مِن مَّارِجٍ مِّن نَّارٍ", tafsir: `أبا الجن ، أو كل جني ، فكما أن أصل كل فرد منا التراب ، كذلك أصل كل جني النار ( مِنْ مارِجٍ ) صاف من الدخان ( مِنْ نارٍ ) أي نار مارجة ، ويسمى مارجا من مرج بمعنى اضطرب.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ هل تكذبون بنعمة الخلق ؟ ومن خلقكم إذن ؟. [18] الله هو ( رَبُّ الْمَشْرِقَيْنِ ) مشرق الصيف ومشرق الشتاء ( وَرَبُّ الْمَغْرِبَيْنِ ) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (18) مَرَجَ الْبَحْرَيْنِ يَلْتَقِيانِ (19) بَيْنَهُما بَرْزَخٌ لا يَبْغِيانِ (20) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (21) يَخْرُجُ مِنْهُمَا اللُّؤْلُؤُ وَالْمَرْجانُ (22) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (23) مغربهما.` },
            { text: "رَبُّ ٱلْمَشْرِقَيْنِ وَرَبُّ ٱلْمَغْرِبَيْنِ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ وهل هناك رب آخر جعل المشرق والمغرب ؟ ومن هو إذن ؟` },
            { text: "مَرَجَ ٱلْبَحْرَيْنِ يَلْتَقِيَانِ", tafsir: `خلط بين بحر عذب وبحر مالح ( يَلْتَقِيانِ ) فإن تحت الأرض قطعة من الماء المالح في البحار ، والعذب في العيون والمخازن الخلقية ، وهما متجاوران ، وهذا في بطن ذاك وبالعكس.` },
            { text: "بَيْنَهُمَا بَرْزَخٌ لَّا يَبْغِيَانِ", tafsir: `حاجز ( لا يَبْغِيانِ ) فلا العذب يدخل في المالح ، ولا العكس ، وذلك لقانون خلقه الله في المائين ، مما لا يقبل أحدهما الاختلاط بالآخر ، وإنما كل ماء يجذب إلى نفسه أجزاء ما من جنسه ، وقد ذكروا تفصيل ذلك في علم الفيزياء.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ فهل خلق المائين غير الله ؟ وهل جعل هذا القانون فيهما غير الله ؟` },
            { text: "يَخْرُجُ مِنْهُمَا ٱللُّؤْلُؤُ وَٱلْمَرْجَانُ", tafsir: `الدر الذي في الصدف ( وَالْمَرْجانُ ) شجرة تنبت تحت الماء.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ فهل خلق اللؤلؤ والمرجان من غيره تعالى ؟ ومن هو إذا ؟ وَلَهُ الْجَوارِ الْمُنْشَآتُ فِي الْبَحْرِ كَالْأَعْلامِ (24) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (25) كُلُّ مَنْ عَلَيْها فانٍ (26) وَيَبْقى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالْإِكْرامِ (27) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (28)` },
            { text: "وَلَهُ ٱلْجَوَارِ ٱلْمُنشَـَٔاتُ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ", tafsir: `سبحانه ( الْجَوارِ ) جمع جارية أي السفينة ، وكونها له لأنه خلق مواردها ، ووهب الإنسان عقلا لصنعها وجعل في الماء قانونا « كشفه أرخميدس » لأجل أن لا تغرق في الماء ( الْمُنْشَآتُ ) التي أنشأها وأوجدها الإنسان بفكر وهبه الله له ( فِي الْبَحْرِ كَالْأَعْلامِ ) جمع علم وهو الجبل الطويل ، فكيف أنها لا تغرق في الماء ؟.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ هل خلق المواد ، وإعطاء الإنسان قدرة الإنشاء ، أو جعل قانون أرخميدس في الماء ، لغير الله ؟ ، ومن يجرأ أن يقول ذلك ؟ [27] هكذا أنشأناكم ، وهيأنا مصالحكم ، ثم بعد ذلك ( كُلُّ مَنْ عَلَيْها ) أي على الأرض ( فانٍ ) يفنى ويهلك.` },
            { text: "كُلُّ مَنْ عَلَيْهَا فَانٍ", tafsir: `` },
            { text: "وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو ٱلْجَلَٰلِ وَٱلْإِكْرَامِ", tafsir: `ذات ربك ، والإنسان يقال له وجه ، فيقال « نحتاج إلى وجوه جديدة » أو « فلان وجه كريم » وذلك ، لأنه محل التوجه ، فيطلق على الكل من باب إطلاق الجزء على الكل ، كما ذكروه في أقسام المجاز ( ذُو الْجَلالِ ) فهو أجل من أن يفنى ( وَالْإِكْرامِ ) الذي أكرم بالخلق ثم يكرم بالإعادة. والأول : صفة جلال. والثاني : صفة جمال.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ فهل تكذبون بأن الله يفني زيدا وعمروا وبكرا ؟ وكل واحد من فناءاته نعمة ، نعمة على المؤمن لأنه ينجيه إلى يَسْئَلُهُ مَنْ فِي السَّماواتِ وَالْأَرْضِ كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ (29) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (30) دار كرامته ، وعلى غير المؤمن لأنه لا يزداد عصيانا ببقائه في دار الدنيا. [30] فهو الخالق ، وهو مهئ كل نعمة ، وهو المغني ، ثم هو المسؤول لكل حاجة ، في كل الكون ( يَسْئَلُهُ ) يطلب الحوائج منه ( مَنْ فِي السَّماواتِ ) من الملائكة وغيرهم ( وَالْأَرْضِ ) من الإنسان والجن وغيرهما ، وليس الله كالإنسان الذي يجعل القانون ثم لا يغيره ولا يبدله ، فلا شأن له في التصرف بعد وضعه القانون بل ( كُلَّ يَوْمٍ هُوَ ) سبحانه ( فِي شَأْنٍ ) فإذا قدر الفقر ثم سأله إنسان أن يغنيه أغناه ، وهكذا ، فهو يتصرف في الكون في كل آن ، لا يقال ما هي الحاجة إلى ذلك وقد كان بقدرته سبحانه أن يكون كصاحب معمل يشغل معمله لحظة ، ثم يتركه طيلة حركته ، فيخلق الله الكون لحظة ، ثم لا يعمل شيئا ؟ لأنه يقال المحال لا يقع تحت قدرة الله تعالى فإن الأشياء عدم بدون استمرار عناية الله بها مثل أن النور عدم بدون إفاضة الشمس دائما له ، ومثال المعمل غير صحيح ، لأن صاحب المعمل لا يأتي إلا بالمعدّ أي بحركة أعضائه وجوارحه في اللحظة الأولى أما دوران المعمل فهو حسب قانون جعله الله في الكون فالله قائم على دوران المعمل لا إنه يدوره بنفسه كما أن من يضغط على جهاز الكهرباء أتى بالمعدّ وانتهى فالإنارة المستمرة إنما هي حسب قانون الله في جريان تيار الكهرباء ، وهذا بحث طويل مربوط بالفلسفة.` },
            { text: "يَسْـَٔلُهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلَّ يَوْمٍ هُوَ فِى شَأْنٍ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ أليس الله يستمر في إعطاء الكون الحياة سَنَفْرُغُ لَكُمْ أَيُّهَ الثَّقَلانِ (31) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (32) يا مَعْشَرَ الْجِنِّ وَالْإِنْسِ إِنِ اسْتَطَعْتُمْ أَنْ تَنْفُذُوا مِنْ أَقْطارِ السَّماواتِ وَالْأَرْضِ فَانْفُذُوا لا تَنْفُذُونَ إِلاَّ بِسُلْطانٍ (33) والبقاء الجديد ؟ وأليس كل ذلك آلاء ونعما.` },
            { text: "سَنَفْرُغُ لَكُمْ أَيُّهَ ٱلثَّقَلَانِ", tafsir: `سنتجرد عن شؤون الدنيا لأجل حسابكم يوم القيامة ـ إذ لا دنيا حينئذ ـ ( أَيُّهَ الثَّقَلانِ ) الجن والإنس ، والظاهر أنه تهديد ، وكناية على أنه لا عمل إلا حسابكم ، فيكون الحساب دقيقا جدا ، فهو مثل قول الرجل لمن يريد تهديده ، سأفرغ لك ، أي لا يكون لي شغل إلا الإيقاع بك.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ لا تكذبوا بآلاء الله حتى لا تقعوا في العذاب يوم القيامة وأهوالها. [34] إن ذلك التفرغ لشأنكم إنما يكون في يوم لا مفر لأحد من سلطان الله ، فيقال للثقلين ( يا مَعْشَرَ الْجِنِّ وَالْإِنْسِ ) يا أيتها الجماعة ( إِنِ اسْتَطَعْتُمْ أَنْ تَنْفُذُوا ) أن تهربوا من ثقب الكون ( مِنْ أَقْطارِ ) جمع قطر بمعنى الناحية ( السَّماواتِ وَالْأَرْضِ ) لأن أقطارها في ذلك اليوم مسدودة ( فَانْفُذُوا ) واهربوا لكن هيهات أن تتمكنوا من ذلك ( لا تَنْفُذُونَ ) لا تقدرون من النفوذ والهرب ( إِلَّا بِسُلْطانٍ ) بحجة واضحة تأتون بها على أنكم عملتم في الدنيا حسنا ، فيعطى لكم جواز التخلص من الحساب إلى سعة الجنة. أقول : ربما فسر هذه الآية بعض العلماء بعدم إمكان الذهاب إلى أجواء السماء وأعماق الأرض إلا بسلطان العلم. فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (34) يُرْسَلُ عَلَيْكُما شُواظٌ مِنْ نارٍ وَنُحاسٌ فَلا تَنْتَصِرانِ (35) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (36) فَإِذَا انْشَقَّتِ السَّماءُ فَكانَتْ وَرْدَةً كَالدِّهانِ (37) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (38)` },
            { text: "يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ إِنِ ٱسْتَطَعْتُمْ أَن تَنفُذُوا۟ مِنْ أَقْطَارِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ فَٱنفُذُوا۟ لَا تَنفُذُونَ إِلَّا بِسُلْطَٰنٍ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ فكما أن الدنيا نعمة ، كذلك الحساب نعمة ، فإن مثله مثل الامتحان الذي يعطي كل ذي حق حقه ، فهل تكذبان بنعم الحساب التي توجب وصول كل ذي حق إلى حقه ؟ [36] في ذلك اليوم ( يُرْسَلُ عَلَيْكُما ) أيها الجن والإنس ( شُواظٌ ) اللهب الخالص ، أو ذرأت النار المتطايرة ( مِنْ نارٍ وَنُحاسٌ ) مذاب حتى يتأذى بهما الكفرة والعصاة ( فَلا تَنْتَصِرانِ ) لا أحد ينصركم من بأس الله ، فآمنوا واعملوا حتى لا يصيبكم مثل هذا العذاب.` },
            { text: "يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِّن نَّارٍ وَنُحَاسٌ فَلَا تَنتَصِرَانِ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `لا تكذبوا بالآلاء حتى لا يشملكم مثل هذا العذاب.` },
            { text: "فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتْ وَرْدَةً كَٱلدِّهَانِ", tafsir: `بأن كان في نظر الناظر كأن فيها خلل وفرج ، كما أن يوم الحساب ينظر الناس إلى السماء كأن فيها فرج من أثر وجود الغيم في بعضها وعدم وجوده في بعضها ( فَكانَتْ ) السماء ( وَرْدَةً ) يظهر في فرجها أثار العذاب الأحمر ، لأن النار حمراء ( كَالدِّهانِ ) كالدهن أي عذاب سيال كالدهن أحمر كالنار ، وجواب « إذا » لا يسأل ، كما يأتي.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ لا تكذبا حتى لا تبتليا بأهوال هذا اليوم. فَيَوْمَئِذٍ لا يُسْئَلُ عَنْ ذَنْبِهِ إِنْسٌ وَلا جَانٌّ (39) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (40) يُعْرَفُ الْمُجْرِمُونَ بِسِيماهُمْ فَيُؤْخَذُ بِالنَّواصِي وَالْأَقْدامِ (41) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (42)` },
            { text: "فَيَوْمَئِذٍ لَّا يُسْـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٌ وَلَا جَآنٌّ", tafsir: `تكرار لقوله سبحانه « فإذا » للتأكيد ( لا يُسْئَلُ عَنْ ذَنْبِهِ ) عن ذنب أحد ، إلا نفسه ، وجيء بضمير مفرد ، لإفادة أن كل إنسان هو المسؤول عن نفسه فلا يتوهم أنه يمكنه الفرار وإلقاء الأجوبة على عاتق الغير ، كما أن الكبراء في الدنيا يفعلون كذلك ، يلقون أجوبة الأسئلة المحرجة على عاتق غيرهم ( إِنْسٌ وَلا جَانٌ ) فكل إنس يجيب عن نفسه وكل جني يجيب عن نفسه.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ هل تكذبان ؟ وتخلّفان هذه المشكلة التي لا مفر منها وراء ظهوركم. [42] إنه بالإضافة إلى أنهم يسألون في موطن من مواطن القيامة عن أعمالهم ، إنهم يعرفون من ألوانهم ( يُعْرَفُ الْمُجْرِمُونَ بِسِيماهُمْ ) ووجوههم السود وأجسامهم الزرق ، فإن أجسامهم تكون كجسم من لفحه برد شديد ، وكآبتهم الظاهرة ( يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ ) (1) « زرقاء » ( وَوُجُوهٌ يَوْمَئِذٍ باسِرَةٌ ) (2) وإنما لم يذكر الصالحون ، لأن المقام لتهديد الكفار والعصاة ( فَيُؤْخَذُ ) كل مجرم ( بِالنَّواصِي وَالْأَقْدامِ ) ظاهر الآية أنهم يجمع الملائكة بين ناصيتهم وأقدامهم لإلقائهم في جهنم.` },
            { text: "يُعْرَفُ ٱلْمُجْرِمُونَ بِسِيمَٰهُمْ فَيُؤْخَذُ بِٱلنَّوَٰصِى وَٱلْأَقْدَامِ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ لا تكذبوا حتى لا تقعوا في أمثال هذا العذاب الجسمي والإهانة النفسية. ( 1) آل عمران : 107. ( 2) القيامة : 25. هذِهِ جَهَنَّمُ الَّتِي يُكَذِّبُ بِهَا الْمُجْرِمُونَ (43) يَطُوفُونَ بَيْنَها وَبَيْنَ حَمِيمٍ آنٍ (44) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (45) وَلِمَنْ خافَ مَقامَ رَبِّهِ جَنَّتانِ (46) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (47) [44] ويقال لهم حينذاك ( هذِهِ جَهَنَّمُ الَّتِي ) كان ( يُكَذِّبُ بِهَا الْمُجْرِمُونَ ) في دار الدنيا فكانوا يقولون لا جنة ولا نار ، أرأيتم كيف وصلتم إليها ، ولم ينفعكم تكذيبكم بها في الخلاص منها. [45] والمجرمون في حركة دائمة فيها بين شدة العذاب والعطش وبين شرب الماء الذي هو في غاية الحرارة ( يَطُوفُونَ ) المجرمون ، والطواف هو الذهاب والمجيء ( بَيْنَها ) بين نيرانها ( وَبَيْنَ ) ماء ( حَمِيمٍ ) حار ( آنٍ ) من شدة الحرارة قد انتهى حره إلى آخر درجة.` },
            { text: "هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى يُكَذِّبُ بِهَا ٱلْمُجْرِمُونَ", tafsir: `` },
            { text: "يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ ءَانٍ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ فهل لكم طاقة بهذا العذاب حتى تكفروا ، وتبتلوا به ؟. [47] هذا حال المجرمين والمكذبين ( وَلِمَنْ خافَ مَقامَ رَبِّهِ ) موقف ربه ، أي يوم الحساب وإضافة « مقام » إلى « الرب » لبيان اختصاص الحكم هناك لله سبحانه ، لا إن المراد « قيام الله » كما ربما توهم ، أي خاف الله في الدنيا فآمن وعمل صالحا ( جَنَّتانِ ) جنة لجزاء عمله ، وأخرى زيادة وتفضلا ، كما قال تعالى ( لِلَّذِينَ أَحْسَنُوا الْحُسْنى وَزِيادَةٌ ) (1) وقوله ( كِفْلَيْنِ مِنْ رَحْمَتِهِ وَيَجْعَلْ ) (2) .` },
            { text: "وَلِمَنْ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ لا تكذبوا بالآلاء حتى تنالوا هذا ( 1) يونس : 27. ( 2) الحديد : 29. ذَواتا أَفْنانٍ (48) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (49) فِيهِما عَيْنانِ تَجْرِيانِ (50) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (51) فِيهِما مِنْ كُلِّ فاكِهَةٍ زَوْجانِ (52) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (53) مُتَّكِئِينَ عَلى فُرُشٍ بَطائِنُها الثواب العظيم.` },
            { text: "ذَوَاتَآ أَفْنَانٍ", tafsir: `كل جنة ذات ألوان من النعيم والثمار والحور والقصور.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ لا تكذبوا حتى تنالوا هذا النعيم ذا الأفنان.` },
            { text: "فِيهِمَا عَيْنَانِ تَجْرِيَانِ", tafsir: `في كل جنة عين ، لها صفاء العين ، وجمالها ، ومنظر النهر الجاري.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ فبينما كان ينبغي أن يكون وراء كل مخوف وكل نعمة تصديق ، هؤلاء يكذبون ، وسيجزون جزاء تكذيبهم.` },
            { text: "فِيهِمَا مِن كُلِّ فَٰكِهَةٍ زَوْجَانِ", tafsir: `صنفان شتوي وصيفي أو غريب ومألوف ، أو كبير وصغير ، أو رطب ويابس ، إلى غير ذلك ، كل ذلك للتفنن ومزيد النعمة.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `بنعمه الظاهرة أو بنعمه الباطنة ؟ وهل نعمه قابلة للتكذيب ؟ [55] وهؤلاء أصحاب هذا النعيم تراهم في حال كونهم ( مُتَّكِئِينَ ) بحالة راحة واسترخاء ( عَلى فُرُشٍ ) جمع فراش ( بَطائِنُها ) البطانة مقابل مِنْ إِسْتَبْرَقٍ وَجَنَى الْجَنَّتَيْنِ دانٍ (54) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (55) فِيهِنَّ قاصِراتُ الطَّرْفِ لَمْ يَطْمِثْهُنَّ إِنْسٌ قَبْلَهُمْ وَلا جَانٌّ (56) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (57) كَأَنَّهُنَّ الْياقُوتُ وَالْمَرْجانُ (58) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (59) الظهارة ( مِنْ إِسْتَبْرَقٍ ) من ديباج ثخين ، يسبب الراحة ، فليس فراش ظاهر فقط ، حتى لا يستريح الإنسان عليه ( وَجَنَى الْجَنَّتَيْنِ ) أي الذي يجنى منهما وهو الثمر ( دانٍ ) متهدل على رؤوسهم يتمكن القاعد والنائم أن يناله بسهولة.` },
            { text: "مُتَّكِـِٔينَ عَلَىٰ فُرُشٍۭ بَطَآئِنُهَا مِنْ إِسْتَبْرَقٍ وَجَنَى ٱلْجَنَّتَيْنِ دَانٍ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ هل تكذبان بآلائه في الآخرة.` },
            { text: "فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرْفِ لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ", tafsir: `في تلك الفرش نساء ( قاصِراتُ الطَّرْفِ ) مقصورة أبصارهن على أزواجهن لا يردن غيرهم ( لَمْ يَطْمِثْهُنَ ) لم يمسهن ، لا بالجماع ولا بغير الجماع ( إِنْسٌ قَبْلَهُمْ ) قبل أهل الجنة ( وَلا جَانٌ ) فزوجة الإنس لم يمسها إنس وزوجة الجن لم يمسها جن.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ بآلائه التي تؤكل وتشرب أم بآلائه من جنس الزواج والاستمتاعات.` },
            { text: "كَأَنَّهُنَّ ٱلْيَاقُوتُ وَٱلْمَرْجَانُ", tafsir: `كأن تلك النساء ( الْياقُوتُ ) في حمرة الشفاه والوجنات ( وَالْمَرْجانُ ) في بياض الجسم والبشرة.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `فمن خلق مثل هذا الجمال الذي رأيتموه في الدنيا ، في الجملة ، وسيراه المؤمنون في الآخرة في كماله الرائع ؟. [61] ثم أن كل هذا الجزاء لمن أحسن في الدنيا بالإيمان والعمل الصالح هَلْ جَزاءُ الْإِحْسانِ إِلاَّ الْإِحْسانُ (60) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (61) وَمِنْ دُونِهِما جَنَّتانِ (62) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (63) مُدْهامَّتانِ (64) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (65) فِيهِما عَيْنانِ نَضَّاخَتانِ (66) و ( هَلْ جَزاءُ الْإِحْسانِ ) أي إحسان المؤمنين ( إِلَّا الْإِحْسانُ ) إليهم في الآخرة بالثواب والنعيم ؟ فإن البذرة تثمر الثمرة التي هي من جنسها.` },
            { text: "هَلْ جَزَآءُ ٱلْإِحْسَٰنِ إِلَّا ٱلْإِحْسَٰنُ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `؟ فهل هناك تكذيب بأن الإحسان يولّد الإحسان ؟. [63] النعم التي ذكرناها إنما هي للسابقين المقربين ( وَمِنْ دُونِهِما ) أدون وأنزل من الجنتين المذكورتين ( جَنَّتانِ ) والظاهر أنهما لمن دون المقربين في الأعمال ، أي باقي المؤمنين.` },
            { text: "وَمِن دُونِهِمَا جَنَّتَانِ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `فهل يتساوى الأكثر طاعة والأقل طاعة ؟ الأكثر طاعة في جنتين رفيعتين ، والأقل طاعة في جنتين أقل درجة ، فهل يكذب الإنسان بمثل هذا ؟` },
            { text: "مُدْهَآمَّتَانِ", tafsir: `من « دهم » بمعنى السواد أي أن الجنتين خضراوتان تضربان إلى السواد من شدة الخضرة ، فلا يبس لهما.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `هل تكذب بجمال ونضارة ما يمنحه الله للمطيعين الذين أكرمهم بإسكانهم دار كرامته ؟` },
            { text: "فِيهِمَا عَيْنَانِ نَضَّاخَتَانِ", tafsir: `فوارتان ، لا كمثل الجنتين السابقتين حيث العيون الجارية التي هي أجمل من مجرد النضاخة. فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (67) فِيهِما فاكِهَةٌ وَنَخْلٌ وَرُمَّانٌ (68) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (69) فِيهِنَّ خَيْراتٌ حِسانٌ (70) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (71) حُورٌ مَقْصُوراتٌ فِي الْخِيامِ (72) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (73)` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `أليس في قدرة الله أن يجعل العين تنضخ ؟` },
            { text: "فِيهِمَا فَٰكِهَةٌ وَنَخْلٌ وَرُمَّانٌ", tafsir: `من بعض أقسام الفواكه ( وَنَخْلٌ ) للتمر ( وَرُمَّانٌ ) وهذا أقل مما في الجنتين السابقتين حيث فيهما من كل فاكهة زوجين.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `ألا يقدر سبحانه أن يعطي المؤمن أمثال هذا النعيم.` },
            { text: "فِيهِنَّ خَيْرَٰتٌ حِسَانٌ", tafsir: `نساءهن خير من كل ناحية مثل « زيد عدل » « حسان » الوجوه وهن أقل من الحور القاصرات الطرف ، فالسابقات كأنهن اللؤلؤ والمرجان.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `فإن الله قادر على أن يجعل المرأة خيرا محضا وحسنة الوجه.` },
            { text: "حُورٌ مَّقْصُورَٰتٌ فِى ٱلْخِيَامِ", tafsir: `جمع حوراء ، كما تقدم وهن البيضاوات جسما ( مَقْصُوراتٌ ) محفوظات مخدرات ( فِي الْخِيامِ ) فأهل هاتين الجنتين ليس لهم قصور مثل أصحاب الجنتين السابقتين بل لهم خيام كخيام أهل البادية.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `أ ليست هذه النعمة مما يجب أن يشكر عليها ، عوض أن يكفر بها المكذبون ؟ لَمْ يَطْمِثْهُنَّ إِنْسٌ قَبْلَهُمْ وَلا جَانٌّ (74) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (75) مُتَّكِئِينَ عَلى رَفْرَفٍ خُضْرٍ وَعَبْقَرِيٍّ حِسانٍ (76) فَبِأَيِّ آلاءِ رَبِّكُما تُكَذِّبانِ (77) تَبارَكَ اسْمُ رَبِّكَ ذِي الْجَلالِ وَالْإِكْرامِ (78)` },
            { text: "لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ", tafsir: `لم يجامعهن ( إِنْسٌ قَبْلَهُمْ وَلا جَانٌ ) فهن باكرات.` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `أليس الله بقادر على مثل ذلك. [77] في حال كون أصحاب هاتين الجنتين ( مُتَّكِئِينَ عَلى رَفْرَفٍ ) جمع رفرفة وهي الوسادة ( خُضْرٍ ) خضراوات ( وَعَبْقَرِيٍ ) كل ثوب موشى يقال له عبقري ، ولعل على تلك الوسائل أثواب جميلة موشاة ( حِسانٍ ) تلك الرفرف والعبقري كلها حسناوات وهذه أقل مرتبة من فرش بطائنها من إستبرق.` },
            { text: "مُتَّكِـِٔينَ عَلَىٰ رَفْرَفٍ خُضْرٍ وَعَبْقَرِىٍّ حِسَانٍ", tafsir: `` },
            { text: "فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ", tafsir: `أليس مثل هذا جزاء الصالحين وإن كانوا بدرجة ثانية من الصلاح ؟` },
            { text: "تَبَٰرَكَ ٱسْمُ رَبِّكَ ذِى ٱلْجَلَٰلِ وَٱلْإِكْرَامِ", tafsir: `` }
        ]
    },
    56: { // سورة الواقعة
        name: "الواقعة",
        basmalaTafsir: ``,
        verses: [
            { text: "إِذَا وَقَعَتِ ٱلْوَاقِعَةُ", tafsir: `إذا حدثت القيامة وجاءت وسميت بالواقعة لتحقق وقوعها.` },
            { text: "لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ", tafsir: `نفس ( كاذِبَةٌ ) فكلّ يصدق في ذلك اليوم صحته ، وإن كان جماعة ينكرونه في الدنيا ، وهذا كمال يقال إذا وقعت في السجن تصدق كلامي بأن ما تعمله الآن ليس من صلاحك. [4] وهذه الواقعة ( خافِضَةٌ ) تخفض وتنزل بالكفار والعصاة اللذين كانوا في الدنيا ، بنظر الناس في رفعة وسمو ( رافِعَةٌ ) ترفع المؤمنين المطيعين اللذين كانوا في دار الدنيا ، بنظر الناس في ذل وهوان. [5] ويكون ذلك فيما ( إِذا رُجَّتِ الْأَرْضُ رَجًّا ) تحركت تحركا شديدا بالزلازل التي هي من علائم الساعة.` },
            { text: "خَافِضَةٌ رَّافِعَةٌ", tafsir: `` },
            { text: "إِذَا رُجَّتِ ٱلْأَرْضُ رَجًّا", tafsir: `` },
            { text: "وَبُسَّتِ ٱلْجِبَالُ بَسًّا", tafsir: `فتتت وتحركت ( بَسًّا ) مفعول مطلق لبيان شدة التفتت والحركة.` },
            { text: "فَكَانَتْ هَبَآءً مُّنۢبَثًّا", tafsir: `الهباء الذي يرى من الذرات في شعاع الشمس إذا دخل الشعاع في كوّة في غرفة مظلمة ( مُنْبَثًّا ) منتشرا.` },
            { text: "وَكُنتُمْ أَزْوَٰجًا ثَلَٰثَةً", tafsir: `أيها البشر ( أَزْواجاً ) أصنافا ( ثَلاثَةً ) المقربون وأصحاب اليمين ، وأصحاب الشمال. [9] فصنف أصحاب ( الْمَيْمَنَةِ ) أصحاب اليمن ( ما أَصْحابُ الْمَيْمَنَةِ ) وَأَصْحابُ الْمَشْئَمَةِ ما أَصْحابُ الْمَشْئَمَةِ (9) وَالسَّابِقُونَ السَّابِقُونَ (10) أُولئِكَ الْمُقَرَّبُونَ (11) ما أعظم حالهم إذ هم في خير سعادة وبركة.` },
            { text: "فَأَصْحَٰبُ ٱلْمَيْمَنَةِ مَآ أَصْحَٰبُ ٱلْمَيْمَنَةِ", tafsir: `` },
            { text: "وَأَصْحَٰبُ ٱلْمَشْـَٔمَةِ مَآ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ", tafsir: `صنف ( أَصْحابُ الْمَشْئَمَةِ ) أصحاب الشؤم وهم أهل النار ( ما أَصْحابُ الْمَشْئَمَةِ ) ما أعظم حالهم في العذاب ، مثل ( فَغَشِيَهُمْ مِنَ الْيَمِّ ما غَشِيَهُمْ ) (1) .` },
            { text: "وَٱلسَّٰبِقُونَ ٱلسَّٰبِقُونَ", tafsir: `صنف ( السَّابِقُونَ ) ولا حاجة إلى ذكر التهويل في حالهم ، كالصنفين السابقين فإنهم معروفون بأنهم ( السَّابِقُونَ ) يسبقون إلى الجنة بغير حساب.` },
            { text: "أُو۟لَٰٓئِكَ ٱلْمُقَرَّبُونَ", tafsir: `إلى رضوان الله سبحانه ، مما لم يلحقهم أحد من المؤمنين ، وهم الأنبياء والأوصياء والأولياء. لا يقال إن صفاء جوهر الأنبياء والأوصياء سبب إطاعتهم ، فأية فضيلة لهم ولو كان غيرهم خلق صافي الجوهر لكان كذلك ؟ لأنه يقال بالإضافة إلى أن خلق عدم صافي الجوهر يوجب نقصا في الخلق ، وبخلا عن الفيض ، وكلاهما تمتنع على الله ، أنهم إنما صفي جوهرهم لأنهم أجابوا بالطاعة في عالم الذر ، بما لم يجب غيرهم بمثلهم فلو فرض تساويهم مع غيرهم ، لكنهم أجابوا بالطاعة ، فصفي جوهرهم ، فكان ذلك جزاء العمل لا اعتباطا ، ولذا ورد في دعاء الندبة « بعد أن شرطت عليهم الزهد في درجات هذه الدنيا الدنية وزخرفها وزبرجها فشرطوا ذلك وعلمت منهم الوفاء ، فقبلتهم ( 1) طه : 79. فِي جَنَّاتِ النَّعِيمِ (12) ثُلَّةٌ مِنَ الْأَوَّلِينَ (13) وَقَلِيلٌ مِنَ الْآخِرِينَ (14) عَلى سُرُرٍ مَوْضُونَةٍ (15) مُتَّكِئِينَ عَلَيْها مُتَقابِلِينَ (16) يَطُوفُ عَلَيْهِمْ وِلْدانٌ مُخَلَّدُونَ (17) و قربتهم » (1) والبحث طويل مكانه كتب الفلسفة الإسلامية. [13] والمقربون ( فِي جَنَّاتِ النَّعِيمِ ) التي ملأت نعمة وفيرة بحيث لا مكان للشر فيها.` },
            { text: "فِى جَنَّٰتِ ٱلنَّعِيمِ", tafsir: `` },
            { text: "ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ", tafsir: `أي جماعة كثيرة ( مِنَ الْأَوَّلِينَ ) الأمم السابقة من لدن آدم عليه‌السلام إلى محمد صلى‌الله‌عليه‌وآله‌وسلم ، وذلك لأن الأنبياء والأوصياء كانوا في هذه الفترة.` },
            { text: "وَقَلِيلٌ مِّنَ ٱلْـَٔاخِرِينَ", tafsir: `كمحمد صلى‌الله‌عليه‌وآله‌وسلم وأهل بيته ومن إليهم وهم أقل عددا من السابقين ، كما هو واضح. [16] وهم ( عَلى سُرُرٍ ) جمع سرير ( مَوْضُونَةٍ ) أي منسوجة بالذهب واللؤلؤ.` },
            { text: "عَلَىٰ سُرُرٍ مَّوْضُونَةٍ", tafsir: `` },
            { text: "مُّتَّكِـِٔينَ عَلَيْهَا مُتَقَٰبِلِينَ", tafsir: `في حالة راحة واسترخاء ( مُتَقابِلِينَ ) بعضهم مقابل بعض للتحدث ومزيد السرور.` },
            { text: "يَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ", tafsir: `الطواف الذهاب والمجيء ، ولذا يقال طاف بالبيت ، ولا يلزم الدور ولذا يقال طاف بالصفا والمروة ( وِلْدانٌ ) أولاد كالخدم ، فالحور خادمات ، والولدان خدم ( مُخَلَّدُونَ ) باقون دائما على هيئتهم لا يهرمون ولا يموتون. ( 1) مفاتيح الجنان : ث 607. بِأَكْوابٍ وَأَبارِيقَ وَكَأْسٍ مِنْ مَعِينٍ (18) لا يُصَدَّعُونَ عَنْها وَلا يُنْزِفُونَ (19) وَفاكِهَةٍ مِمَّا يَتَخَيَّرُونَ (20) وَلَحْمِ طَيْرٍ مِمَّا يَشْتَهُونَ (21) وَحُورٌ عِينٌ (22) كَأَمْثالِ اللُّؤْلُؤِ الْمَكْنُونِ (23) جَزاءً بِما كانُوا يَعْمَلُونَ (24) لا يَسْمَعُونَ فِيها لَغْواً وَلا تَأْثِيماً (25)` },
            { text: "بِأَكْوَابٍ وَأَبَارِيقَ وَكَأْسٍ مِّن مَّعِينٍ", tafsir: `جمع كوب إناء لا عروة له ولا خرطوم ( وَأَبارِيقَ ) جمع إبريق ما له عروة وإبريق ( وَكَأْسٍ مِنْ مَعِينٍ ) الماء المعين وهو الزلال العذب الطعم ، ولعل المراد به الخمر بقرينة الآية الآتية.` },
            { text: "لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزِفُونَ", tafsir: `لا يأخذهم الصداع ، وهو وجع الرأس كما أن من يشرب الخمر في الدنيا يأخذه الصداع ( وَلا يُنْزِفُونَ ) لا يسكرون ، لأن من سكر فقد « نزف » أي سال عقله وخرج من رأسه.` },
            { text: "وَفَٰكِهَةٍ مِّمَّا يَتَخَيَّرُونَ", tafsir: `يطوف عليهم الولدان ب ( فاكِهَةٍ مِمَّا يَتَخَيَّرُونَ ) يختارون.` },
            { text: "وَلَحْمِ طَيْرٍ مِّمَّا يَشْتَهُونَ", tafsir: `ب ( لَحْمِ طَيْرٍ مِمَّا يَشْتَهُونَ ) يريدون.` },
            { text: "وَحُورٌ عِينٌ", tafsir: `عطف على « ولدان » أي يطوف عليهم حور عين ، وكأن ذلك كناية عن تهيؤ الفراش لهم في كل وقت. [24] وهن ( كَأَمْثالِ اللُّؤْلُؤِ الْمَكْنُونِ ) في الصفاء والنضارة فإن اللؤلؤ إذا لم يكنّ ولم يحفظ قلّ صفاؤه. [25] يعطي أهل الجنة كل ذلك ( جَزاءً بِما كانُوا يَعْمَلُونَ ) أعمالهم التي عملوها في الدنيا.` },
            { text: "كَأَمْثَٰلِ ٱللُّؤْلُؤِ ٱلْمَكْنُونِ", tafsir: `` },
            { text: "جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا تَأْثِيمًا", tafsir: `في الجنة ( لَغْواً ) أي كلاما لغوا ( وَلا تَأْثِيماً ) نسبة إلى الإثم ، فإن الأنبياء عليهم‌السلام والأولياء كانوا في الدنيا يسمعون إِلاَّ قِيلاً سَلاماً سَلاماً (26) وَأَصْحابُ الْيَمِينِ ما أَصْحابُ الْيَمِينِ (27) فِي سِدْرٍ مَخْضُودٍ (28) وَطَلْحٍ مَنْضُودٍ (29) وَظِلٍّ مَمْدُودٍ (30) وَماءٍ مَسْكُوبٍ (31) وَفاكِهَةٍ كَثِيرَةٍ (32) اللغو من أقوامهم وينسبونهم إلى الإثم فيقال لهم ، إنهم آثمون لتركهم أديان قومهم واتخاذهم دينا جديدا ، لكن في الجنة لا شيء من هذين فقد ذهبت الأتعاب وصاروا في راحة ورفاه.` },
            { text: "إِلَّا قِيلًا سَلَٰمًا سَلَٰمًا", tafsir: `استثناء منقطع ( قِيلاً ) قولا ( سَلاماً سَلاماً ) هذا يدخل عليهم ويسلم ، وذاك يدخل ويسلم ، وهكذا.` },
            { text: "وَأَصْحَٰبُ ٱلْيَمِينِ مَآ أَصْحَٰبُ ٱلْيَمِينِ", tafsir: `الصنف الثاني ( أَصْحابُ الْيَمِينِ ) الذين هم دون المقربين مرتبة ، وهم المؤمنون الصالحون ( ما أَصْحابُ الْيَمِينِ ) لا يتكلم حولهم من السعادة والرفاه الذين هم فيهما. [29] هم يعيشون في جنان نضرة ( فِي سِدْرٍ ) النبق ( مَخْضُودٍ ) قد خضد شوكة فلا شوك فيه.` },
            { text: "فِى سِدْرٍ مَّخْضُودٍ", tafsir: `` },
            { text: "وَطَلْحٍ مَّنضُودٍ", tafsir: `شجر الموز ( مَنْضُودٍ ) قد نضد ورتب ثمره بعضه فوق بعض.` },
            { text: "وَظِلٍّ مَّمْدُودٍ", tafsir: `لا شمس فيها تؤذيهم ( مَمْدُودٍ ) لا يزول كما يزول ظل الدنيا وتنسخه الشمس.` },
            { text: "وَمَآءٍ مَّسْكُوبٍ", tafsir: `دائم السكب ، لا ينقطع حتى يحتاجون إلى عناء تحصيله.` },
            { text: "وَفَٰكِهَةٍ كَثِيرَةٍ", tafsir: `وافرة مستمرة. لا مَقْطُوعَةٍ وَلا مَمْنُوعَةٍ (33) وَفُرُشٍ مَرْفُوعَةٍ (34) إِنَّا أَنْشَأْناهُنَّ إِنْشاءً (35) فَجَعَلْناهُنَّ أَبْكاراً (36) عُرُباً أَتْراباً (37) لِأَصْحابِ الْيَمِينِ (38) ثُلَّةٌ مِنَ الْأَوَّلِينَ (39) وَثُلَّةٌ مِنَ الْآخِرِينَ (40)` },
            { text: "لَّا مَقْطُوعَةٍ وَلَا مَمْنُوعَةٍ", tafsir: `كما في فواكه الدنيا حيث تكون في فصل دون فصل ( وَلا مَمْنُوعَةٍ ) لا يمنع عن أخذها أحد ، فهي مباحة لكل أهل الجنة.` },
            { text: "وَفُرُشٍ مَّرْفُوعَةٍ", tafsir: `نساء مرفوعات في الأخلاق والجمال كما يقال فلان إنسان رفيع ، وعبر عن النساء الحوريات بالفراش لافتراش الأزواج لهن.` },
            { text: "إِنَّآ أَنشَأْنَٰهُنَّ إِنشَآءً", tafsir: `ابتدأنا خلقهن ( إِنْشاءً ) بدون ولادة ، كما في نساء الدنيا.` },
            { text: "فَجَعَلْنَٰهُنَّ أَبْكَارًا", tafsir: `دائمات البكارة ليتلذذ الأزواج بهن أكثر ، وكذلك هن يتلذذن أكثر ، لأنه لا وجع لهن ، ولا صعوبة لأزواجهن في افتضاضهن.` },
            { text: "عُرُبًا أَتْرَابًا", tafsir: `جمع عروب بمعنى المحبة للزوج ( أَتْراباً ) جمع ترب بمعنى المتساويات مع أزواجهن في السن ، لا الصغيرة التي يرى الزوج منها عنتا ولا الكبيرة التي يكرهها زوجها لكبر سنها. [39] كل ذلك النعيم ( لِأَصْحابِ الْيَمِينِ ) الذين يؤخذ بهم ذات اليمين إلى الجنة وهم المؤمنون من الأمم.` },
            { text: "لِّأَصْحَٰبِ ٱلْيَمِينِ", tafsir: `` },
            { text: "ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ", tafsir: `جماعة كثيرة من الأمم السابقة.` },
            { text: "وَثُلَّةٌ مِّنَ ٱلْـَٔاخِرِينَ", tafsir: `من أمة رسول الله صلى‌الله‌عليه‌وآله‌وسلم . وَأَصْحابُ الشِّمالِ ما أَصْحابُ الشِّمالِ (41) فِي سَمُومٍ وَحَمِيمٍ (42) وَظِلٍّ مِنْ يَحْمُومٍ (43) لا بارِدٍ وَلا كَرِيمٍ (44) إِنَّهُمْ كانُوا قَبْلَ ذلِكَ مُتْرَفِينَ (45) وَكانُوا يُصِرُّونَ عَلَى الْحِنْثِ الْعَظِيمِ (46) وَكانُوا يَقُولُونَ أَ إِذا` },
            { text: "وَأَصْحَٰبُ ٱلشِّمَالِ مَآ أَصْحَٰبُ ٱلشِّمَالِ", tafsir: `وهم الصنف الثالث من البشر والذين يؤخذ بهم ذات الشمال إلى النار ( ما أَصْحابُ الشِّمالِ ) فهم في أهوال كثيرة ، حتى لا يمكن أن يتصور أحوالهم.` },
            { text: "فِى سَمُومٍ وَحَمِيمٍ", tafsir: `نيران تنفذ إلى مسام الجلد ( وَحَمِيمٍ ) ماء متناه في الحرارة.` },
            { text: "وَظِلٍّ مِّن يَحْمُومٍ", tafsir: `دخان أسود فهم في النار ذات دخان لا يرون مكانا.` },
            { text: "لَّا بَارِدٍ وَلَا كَرِيمٍ", tafsir: `كسائر الظلال ( وَلا كَرِيمٍ ) ولا نافع كما في دخان الدنيا إذ قد يمنع الدخان حر الشمس ونحوها. [46] ولماذا يذوقون هذا العذاب المؤلم ؟ ل ( إِنَّهُمْ كانُوا قَبْلَ ذلِكَ ) في دار الدنيا ( مُتْرَفِينَ ) يعيشون في الترف وهو الانهماك في الملذات والشهوات.` },
            { text: "إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ", tafsir: `` },
            { text: "وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ", tafsir: `لعهد الله أي نقضه ( الْعَظِيمِ ) وهو الشرك ، لأن الله أخذ الميثاق من كل البشر بأن يؤمنوا به ، ثم هؤلاء حنثوا عهد الله. [48] وبالإضافة إلى إنكارهم المبدأ ( وَكانُوا يَقُولُونَ أَ إِذا ) الهمزة للاستفهام مِتْنا وَكُنَّا تُراباً وَعِظاماً أَوَآباؤُنَا الْأَوَّلُونَ (48) قُلْ إِنَّ الْأَوَّلِينَ وَالْآخِرِينَ (49) لَمَجْمُوعُونَ إِلى مِيقاتِ يَوْمٍ مَعْلُومٍ (50) ثُمَّ إِنَّكُمْ أَيُّهَا الضَّالُّونَ الْمُكَذِّبُونَ (51) لَآكِلُونَ مِنْ شَجَرٍ مِنْ زَقُّومٍ (52) فَمالِؤُنَ مِنْهَا الْبُطُونَ (53) فَشارِبُونَ عَلَيْهِ مِنَ الْحَمِيمِ (54) الإنكاري ( مِتْنا وَكُنَّا تُراباً ) لحومنا ( وَعِظاماً ) ظهرت عظامنا ( أَ إِنَّا لَمَبْعُوثُونَ ) ليوم القيامة ؟ فأنكروا المعاد أيضا.` },
            { text: "وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ", tafsir: `` },
            { text: "أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ", tafsir: `وهل ( آباؤُنَا الْأَوَّلُونَ ) الذين صاروا ترابا يبعثون ؟ « فالهمزة » للاستفهام و « الواو » للعطف على ضمير « مبعوثون » .` },
            { text: "قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْـَٔاخِرِينَ", tafsir: `يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم لهم نعم يبعث الجميع ( إِنَّ الْأَوَّلِينَ وَالْآخِرِينَ ) كلهم أجمع.` },
            { text: "لَمَجْمُوعُونَ إِلَىٰ مِيقَٰتِ يَوْمٍ مَّعْلُومٍ", tafsir: `تحت التراب ( إِلى مِيقاتِ ) وقت ( يَوْمٍ مَعْلُومٍ ) هو يوم القيامة ، حيث يبعث كلهم مرة واحدة.` },
            { text: "ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ", tafsir: `بعد البعث ( إِنَّكُمْ أَيُّهَا الضَّالُّونَ ) عن طريق الثواب ( الْمُكَذِّبُونَ ) بالله وبرسوله وبالمعاد.` },
            { text: "لَـَٔاكِلُونَ مِن شَجَرٍ مِّن زَقُّومٍ", tafsir: `وهو شيء في غاية المرارة.` },
            { text: "فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ", tafsir: `تملؤون ( مِنْهَا ) من تلك الثمرة المرة ( الْبُطُونَ ) فإنهم لشدة جوعهم يأكلون منها إلى حد الامتلاء. [55] ثم يعطشون أشد العطش ( فَشارِبُونَ عَلَيْهِ ) على الزقوم ( مِنَ ) الماء ( الْحَمِيمِ ) الذي هو غاية في الحرارة. فَشارِبُونَ شُرْبَ الْهِيمِ (55) هذا نُزُلُهُمْ يَوْمَ الدِّينِ (56) نَحْنُ خَلَقْناكُمْ فَلَوْ لا تُصَدِّقُونَ (57) أَ فَرَأَيْتُمْ ما تُمْنُونَ (58) أَ أَنْتُمْ تَخْلُقُونَهُ أَمْ نَحْنُ الْخالِقُونَ (59) نَحْنُ قَدَّرْنا بَيْنَكُمُ الْمَوْتَ وَما نَحْنُ بِمَسْبُوقِينَ (60)` },
            { text: "فَشَٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ", tafsir: `` },
            { text: "فَشَٰرِبُونَ شُرْبَ ٱلْهِيمِ", tafsir: `تكرار الفاء لبيان أنهم يشربون ويشربون ( شُرْبَ الْهِيمِ ) مثل شرب الإبل العطشان الذي هو في غاية العطش فإن الإبل الذي به « الهيام » وهو داء الاستسقاء ، يشرب من الماء الشيء الكثير جدا ، وهيم جمع أهيم وهيماء.` },
            { text: "هَٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ", tafsir: `لنزل ما يعد للضيف ( يَوْمَ الدِّينِ ) في يوم القيامة. [58] وهذا جزاء تكذيبكم ( نَحْنُ خَلَقْناكُمْ فَلَوْ لا تُصَدِّقُونَ ) فلما ذا لم تصدقوا بمن خلقكم ، ولا برسله ، ولا بما أخبر من بعثه ؟. [59] وكيف تكذبون بالله وأنتم ترون أن كل ما حولكم هو من خلق الله ؟ ( أَ فَرَأَيْتُمْ ما تُمْنُونَ ) ما تقذفونه في الأرحام من النطف.` },
            { text: "نَحْنُ خَلَقْنَٰكُمْ فَلَوْلَا تُصَدِّقُونَ", tafsir: `` },
            { text: "أَفَرَءَيْتُم مَّا تُمْنُونَ", tafsir: `` },
            { text: "ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَٰلِقُونَ", tafsir: `تجعلونه بشرا سويا ( أَمْ نَحْنُ الْخالِقُونَ ) وإذا اعترفتم بأنكم لا تخلقونه فلم تكذبون بخالقه ؟. [61] ثم الموت الذي يأتيكم بغير إرادة منكم فهل أنتم سبب الموت أو الله ؟ وإذا كان الله هو المقدر للموت فلما ذا تكفرون به ( نَحْنُ قَدَّرْنا بَيْنَكُمُ الْمَوْتَ ) فكل إنسان يموت حسب تقدير الله وإرادته ( وَما نَحْنُ بِمَسْبُوقِينَ ) بمغلوبين تشبيه بأن يسبق إنسان إنسانا فلا يقدر المسبوق اللحاق بالسابق. عَلى أَنْ نُبَدِّلَ أَمْثالَكُمْ وَنُنْشِئَكُمْ فِي ما لا تَعْلَمُونَ (61) وَلَقَدْ عَلِمْتُمُ النَّشْأَةَ الْأُولى فَلَوْ لا تَذَكَّرُونَ (62) أَ فَرَأَيْتُمْ ما تَحْرُثُونَ (63) أَ أَنْتُمْ تَزْرَعُونَهُ أَمْ نَحْنُ الزَّارِعُونَ (64) لَوْ نَشاءُ لَجَعَلْناهُ حُطاماً فَظَلْتُمْ تَفَكَّهُونَ (65)` },
            { text: "نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ", tafsir: `` },
            { text: "عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ", tafsir: `بأن نذهب بكم ونأتي غيركم ـ من مثلكم ـ مكانكم ( وَنُنْشِئَكُمْ ) نخلقكم خلقا جديدا ( فِي ما ) أي في صورة ( لا تَعْلَمُونَ ) لا تعلمونها كأن نجعلكم قردة أو خنازير أو غير ذلك.` },
            { text: "وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ", tafsir: `كيف أنشأناكم ( فَلَوْ لا تَذَكَّرُونَ ) فلما ذا لا تتذكرون أن من يقدر على الإنشاء أولا يقدر على الإنشاء ثانيا ؟ فكيف تنكرون البعث ؟. [64] ثم ليس خلقكم أنتم من الله فقط بل كل شيء هو من خلق الله ( أَ فَرَأَيْتُمْ ما تَحْرُثُونَ ) تبذرون حبّة لأجل الزراعة والثمر.` },
            { text: "أَفَرَءَيْتُم مَّا تَحْرُثُونَ", tafsir: `` },
            { text: "ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ", tafsir: `تنبتونه ( أَمْ نَحْنُ الزَّارِعُونَ ) ؟ ولا أحد يقدر أن يقول إنه هو الزارع للنبات كما أنه لا أحد يقدر أن يقول إن الزارع له هو الطبيعة ، فهل الطبيعة الجاهلة العاجزة تقدر على مثل هذا الشيء ، وإذا صدق الإنسان أن الله هو الزارع الذي يجعل من الأرض الميتة نباتا حيا ، سهل عنده أن يصدق أن الله قادر على إعادة الإنسان بعد موته.` },
            { text: "لَوْ نَشَآءُ لَجَعَلْنَٰهُ حُطَٰمًا فَظَلْتُمْ تَفَكَّهُونَ", tafsir: `هشيما متحطما عوض أن ننمي النبات حتى نجعله شجرة ذات ثمرة فإذا فعلناه هشيما لظلتم ( تَفَكَّهُونَ ) إِنَّا لَمُغْرَمُونَ (66) بَلْ نَحْنُ مَحْرُومُونَ (67) أَ فَرَأَيْتُمُ الْماءَ الَّذِي تَشْرَبُونَ (68) أَ أَنْتُمْ أَنْزَلْتُمُوهُ مِنَ الْمُزْنِ أَمْ نَحْنُ الْمُنْزِلُونَ (69) لَوْ نَشاءُ جَعَلْناهُ أُجاجاً فَلَوْ لا تَشْكُرُونَ (70) أَفَرَأَيْتُمُ النَّارَ الَّتِي تُورُونَ (71) أَ أَنْتُمْ أَنْشَأْتُمْ شَجَرَتَها أَمْ نَحْنُ الْمُنْشِؤُنَ (72) تتكلمون في مجالسكم ، من جهة التعجب والندم على ما أنفقتم في الأرض لأجل الزرع ، والمراد أنكم لا تقدرون أمام قدرة الله بجعله النبات هشيما إلا التكلم فقط.` },
            { text: "إِنَّا لَمُغْرَمُونَ", tafsir: `ملزمون بغرامة ما أنفقنا.` },
            { text: "بَلْ نَحْنُ مَحْرُومُونَ", tafsir: `تقولون بالإضافة إلى غرامة ما أنفقنا ( نَحْنُ ) قوم ( مَحْرُومُونَ ) حرمنا من رزقنا.` },
            { text: "أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ", tafsir: `هو ماء عذب صالح للشرب.` },
            { text: "ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ", tafsir: `من السحاب ( أَمْ نَحْنُ الْمُنْزِلُونَ ) بقدرتنا ؟ وهل هناك أحد يقول أنا أنزلت الماء ؟.` },
            { text: "لَوْ نَشَآءُ جَعَلْنَٰهُ أُجَاجًا فَلَوْلَا تَشْكُرُونَ", tafsir: `مالحا يمجّه الطبع ( فَلَوْ لا تَشْكُرُونَ ) أمثال هذه النعم التي هي ضرورية لحياتكم ، ولو إنا ما أعطيناها لكم ، لم يكن لكم علاج في تحصيلها ، إلا التفكّر والتحسّر.` },
            { text: "أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ", tafsir: `تخرجونها من الخشب ونحوه.` },
            { text: "ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ", tafsir: `خلقتم شجرتها ( أَمْ نَحْنُ الْمُنْشِؤُنَ ) ؟ وهل هناك أحد يقول إنه أنشأ شجرتها. نَحْنُ جَعَلْناها تَذْكِرَةً وَمَتاعاً لِلْمُقْوِينَ (73) فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ (74) فَلا أُقْسِمُ بِمَواقِعِ النُّجُومِ (75) وَإِنَّهُ لَقَسَمٌ لَوْ تَعْلَمُونَ عَظِيمٌ (76)` },
            { text: "نَحْنُ جَعَلْنَٰهَا تَذْكِرَةً وَمَتَٰعًا لِّلْمُقْوِينَ", tafsir: `النار ( تَذْكِرَةً ) تذكركم بنعمة الله ، وبنار الآخرة ، حتى تشكروه سبحانه على هذه النعمة ، وتخافوا من عذاب يوم القيامة ( وَمَتاعاً ) منفعة يتمتع بها الإنسان في طبخه وتدفئته وقضاء سائر حوائجه المحتاجة إلى النار ( لِلْمُقْوِينَ ) يقال أقويت منذ أيام أي لم آكل طعاما فالمقوين هم الذين يحتاجون إلى الطعام ، ولعله من حمل الضد على الضد ، حيث إن خالي البطن لا يقوى فحمل على من « يقوى » بأكله الطعام. [75] وإذ عرفت كثرة نعم الله عليك ( فَسَبِّحْ بِاسْمِ رَبِّكَ ) نزهه عما لا يليق به ، والباء في « باسم » مثل اللام في « سبح لله » للتقوية ( الْعَظِيمِ ) صفة الرب. [76] وحيث فرغ عن إثبات الألوهية جاء دور إثبات الرسالة ، وذلك بسبب بيان أن القرآن من عند الله سبحانه ( فَلا أُقْسِمُ ) هذا صيغة تشير إلى الحلف ، ليكون للكلام قوة الحلف ، مع عدم الحلف احتراما للمحلف به ، ف « لا » نافية ( بِمَواقِعِ النُّجُومِ ) إذ القوة الهائلة التي تحفظ النجوم الكبار ، والتي بعضها ستون مليون مرّة أكبر من الشمس ، الشمس التي هي أكبر من الأرض بأكثر من مليون مرة ، إن تلك القوة من العظمة مما ينبغي أن يحلف بها.` },
            { text: "فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ", tafsir: `` },
            { text: "فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ", tafsir: `` },
            { text: "وَإِنَّهُۥ لَقَسَمٌ لَّوْ تَعْلَمُونَ عَظِيمٌ", tafsir: `لعلمتم أنه ( عَظِيمٌ ) بل خارج عظمته من إِنَّهُ لَقُرْآنٌ كَرِيمٌ (77) فِي كِتابٍ مَكْنُونٍ (78) لا يَمَسُّهُ إِلاَّ الْمُطَهَّرُونَ (79) تَنْزِيلٌ مِنْ رَبِّ الْعالَمِينَ (80) أَ فَبِهذَا الْحَدِيثِ أَنْتُمْ مُدْهِنُونَ (81) طوق فهم البشر وإدراكهم.` },
            { text: "إِنَّهُۥ لَقُرْءَانٌ كَرِيمٌ", tafsir: `الشيء المنزل على رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( لَقُرْآنٌ كَرِيمٌ ) له كرامة الوحي وهو يكفي لإصلاح المعاش والمعاد.` },
            { text: "فِى كِتَٰبٍ مَّكْنُونٍ", tafsir: `مكتوب في لوح محفوظ عند الله أنزله الله على رسوله لهداية البشر إلى يوم القيامة.` },
            { text: "لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ", tafsir: `لا يمس ذلك الكتاب المكنون ( إِلَّا الْمُطَهَّرُونَ ) من الملائكة فإذا كان شأنه هناك في العالم الأعلى مثل هذا الشأن ، فاللازم تقديره حق قدره في هذا العالم ، وهذا حسب ظاهر الآية ، وما ورد في تفسيرها بطون أو تأويل أو ما أشبه (1) ، ولا منافاة بين الجميع ، كما ذكرناه في كتاب « حول القرآن الحكيم » (2) . [81] وهو ( تَنْزِيلٌ ) أي منزل ، فهو من قبيل « زيد عدل » ( مِنْ رَبِّ الْعالَمِينَ ) أنزله لصالح الكون إلى الأبد.` },
            { text: "تَنزِيلٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "أَفَبِهَٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ", tafsir: `الشيء الحادث الذي هو القرآن ( أَنْتُمْ مُدْهِنُونَ ) متهاونون ؟ كمن يدهن في الأمر أي يلين جانبه تهاونا ، وأصله استعمال الدهن للين الجسم. ( 1) راجع بحار الأنوار : ج 77 ص 255. ( 2) موسوعة الفقه : ج 98. وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ (82) فَلَوْ لا إِذا بَلَغَتِ الْحُلْقُومَ (83) وَأَنْتُمْ حِينَئِذٍ تَنْظُرُونَ (84) وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْكُمْ وَلكِنْ لا تُبْصِرُونَ (85) فَلَوْ لا إِنْ كُنْتُمْ غَيْرَ مَدِينِينَ (86)` },
            { text: "وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ", tafsir: `أي سبب رزقكم ، أطلق عليها الرزق بعلاقة السبب والمسبب ( أَنَّكُمْ تُكَذِّبُونَ ) تكذيبكم لهذا القرآن الموصوف بالصفات السابقة ، لأنهم كانوا يرون أن استمرار رزقهم إنما هو بالتجافي عن القرآن والتكذيب له ، كما يقال « جعل فلان رزقه الزنى » أي جعله ممر رزقه. [84] نعم سترون جزاء تكذيبكم عند ما يأتيكم الموت ولا علاج لكم في دفعه ( فَلَوْ لا ) فهلا ( إِذا بَلَغَتِ ) النفس ( الْحُلْقُومَ ) لأن النفس تخرج من الرجل إلى الحلقوم ، ثم إلى الرأس ، وذكر الحلقوم من جهة شعور الإنسان بالموت مع بقاء مشاعره في الرأس مدركا لهول الموت.` },
            { text: "فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ", tafsir: `` },
            { text: "وَأَنتُمْ حِينَئِذٍ تَنظُرُونَ", tafsir: `أيها الحاضرون حول المحتضر ( حِينَئِذٍ ) حين وصلت روحه إلى الحلقوم ( تَنْظُرُونَ ) وهو وأنتم في غاية إلى عدم موته ، ورجوعه إلى الحياة.` },
            { text: "وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ", tafsir: `لأن علمنا وقدرتنا نافذتان إلى أعماقه ، وأنتم لستم كذلك ( وَلكِنْ لا تُبْصِرُونَ ) أنتم قربنا.` },
            { text: "فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ", tafsir: `تكرار ، لأجل ارتباط الجواب ب « لو لا ( إِذا بَلَغَتِ .. . ) ( إِنْ كُنْتُمْ غَيْرَ مَدِينِينَ ) غير مربوبين من دان السلطان الرعية إذا ساسهم. تَرْجِعُونَها إِنْ كُنْتُمْ ص ادِقِينَ (87) فَأَمَّا إِنْ كانَ مِنَ الْمُقَرَّبِينَ (88) فَرَوْحٌ وَرَيْحانٌ وَجَنَّةُ نَعِيمٍ (89) وَأَمَّا إِنْ كانَ مِنْ أَصْحابِ الْيَمِينِ (90) فَسَلامٌ لَكَ مِنْ أَصْحابِ الْيَمِينِ (91) وَأَمَّا إِنْ كانَ مِنَ الْمُكَذِّبِينَ الضَّالِّينَ (92)` },
            { text: "تَرْجِعُونَهَآ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `ترجعون النفس إلى كل الجسد ، كما كان سابقا ( إِنْ كُنْتُمْ صادِقِينَ ) في إنكاركم لله وقدرته ، فإذا لم يكن إله ـ كما زعمتم ـ ولم يكن أمر الكون بيده ، فلما ذا لا تقدرون أنتم على إنجاز أحب شيء إلى قلوبكم من إرجاع الروح إلى ميتكم العزيز ، أليس كل ذلك دليلا على وجود إله قدير بيده كل شيء. [89] ثم يبين الله سبحانه مصير هذا المحتضر ( فَأَمَّا إِنْ كانَ مِنَ الْمُقَرَّبِينَ ) وهو القسم الأول من « الأزواج الثلاثة » المذكورين في أول السورة.` },
            { text: "فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ", tafsir: `` },
            { text: "فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَعِيمٍ", tafsir: `فله راحة ( وَرَيْحانٌ ) الريحان المشموم كناية عن حضور مشتهياته الطيبة ( وَجَنَّةُ نَعِيمٍ ) جنة ذات نعمة.` },
            { text: "وَأَمَّآ إِن كَانَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ", tafsir: `وهو القسم الثاني من أهل الجنة لكنهم دون المقربين.` },
            { text: "فَسَلَٰمٌ لَّكَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ", tafsir: `يا صاحب اليمين ، سلامة لك في آخرتك وأنت تكون ( مِنْ ) جملة ( أَصْحابِ الْيَمِينِ ) كما يقال « السلام عليك من شهيد في سبيل الله » فإن « من » بيان ل « كاف » الخطاب.` },
            { text: "وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ", tafsir: `المحتضر ( مِنَ الْمُكَذِّبِينَ ) بالله ورسوله والمعاد ( الضَّالِّينَ ) عن طريق الهداية ، « هم أصحاب الشمال » فهو ضال في فَنُزُلٌ مِنْ حَمِيمٍ (93) وَتَصْلِيَةُ جَحِيمٍ (94) إِنَّ هذا لَهُوَ حَقُّ الْيَقِينِ (95) فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ (96) نفسه مكذب للحق.` },
            { text: "فَنُزُلٌ مِّنْ حَمِيمٍ", tafsir: `هو ما يعد للضيف ( مِنْ حَمِيمٍ ) من ماء حار شديد الحرارة.` },
            { text: "وَتَصْلِيَةُ جَحِيمٍ", tafsir: `يقال صلاة إذا أوصله ( جَحِيمٍ ) هي من أسماء جهنم.` },
            { text: "إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ", tafsir: `الذي ذكرناه من جزاء الأقسام الثلاثة ( لَهُوَ حَقُّ الْيَقِينِ ) الحق المطابق للواقع ، الذي هو يقيني أي من شأنه ذلك وإن أنكره كثير ، مثل « لا ريب فيه » أي ليس هو محل الريب وإن ارتاب فيه الكثير ، وهذا أحد الأقسام الثلاثة التي ينقسم اليقين إليها. فالأول : علم اليقين ، كما إذا علمت بأن النار حارة. والثاني : حق اليقين ، كما إذا رأيت النار. والثالث : عين اليقين ، كما إذا أدخلت يدك في النار وذقت حرارتها. [97] وإذا علمت بما تقدم ( فَسَبِّحْ ) يا رسول الله ( بِاسْمِ رَبِّكَ ) نزهه عما لا يليق به ( الْعَظِيمِ ) صفة الرب ، وقد تقدم بعض الكلام فيه في آية شبيهة بها ، فباعتبار أن التسبيح للذات يأتي بلا حرف جر ، وباعتبار أن التسبيح ملصق بالاسم يتعدى بالباء ، وباعتبار أن التسبيح لله يتعدى باللام. (57)` },
            { text: "فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ", tafsir: `` }
        ]
    },
    57: { // سورة الحديد
        name: "الحديد",
        basmalaTafsir: ``,
        verses: [
            { text: "سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `نزهه عما لا يليق به ، وقد تقدم في آخر الواقعة ، وجه تعدي التسبيح باللام ( ما فِي السَّماواتِ وَالْأَرْضِ ) قد سبق وجه جمع السماوات وإفراد الأرض ، وتسبيح كل شيء إما بلسانه ، وإن كنا لا نفهم ألسنة غير الإنسان من المخلوقات ، وإما بدلالته على علم الله وقدرته وصفاته وغير ذلك ، إذ حتى الشعرة الواحدة دليل على الذات وعلى كل الصفات العقلية الثابتة عقلا له سبحانه ( وَهُوَ ) تعالى ( الْعَزِيزُ ) له العزّة والرفعة وعزّة ما سواه إنما تكون به تعالى ( الْحَكِيمُ ) يضع الأشياء موضعها ، ولحكمته خلق الكون ، ولعزته سبح له كل ما في الكون.` },
            { text: "لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُحْىِۦ وَيُمِيتُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `بل هو وحده المالك الحقيقي ، أما سواه فملكه استعارة ومجاز ( يُحْيِي ) التراب إلى النبات والحيوان والإنسان ، كما يحيي الإنسان والحيوان بعد موتهما ( وَيُمِيتُ ) الثلاثة بعد حياتها في دار الدنيا ، كما يميت الحيوانات على الأكثر في الآخرة ، حتى أن الكافر إذا رأى ذلك قال : ( يا لَيْتَنِي كُنْتُ تُراباً ) (1) ( وَهُوَ ) سبحانه ( عَلى كُلِّ شَيْءٍ قَدِيرٌ ) بشرط أن يكون لذلك الشيء أهلية تعليق القدرة ، كما بحث حول ذلك في كتب الفلسفة الإسلامية.` },
            { text: "هُوَ ٱلْأَوَّلُ وَٱلْـَٔاخِرُ وَٱلظَّٰهِرُ وَٱلْبَاطِنُ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ", tafsir: `قبل كل شيء ( وَالْآخِرُ ) بعد كل شيء ، ولا منافاة لعدم انتهاء الجنة والنار إذ يصدق البعدية بالنسبة إلى الحال الحاضرة ، فإن الكل يهلك إلى وجهه ( وَالظَّاهِرُ ) بآثاره لدى كل ذي عقل ( وَالْباطِنُ ) ( 1) النبأ : 41. وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ (3) هُوَ الَّذِي خَلَقَ السَّماواتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوى عَلَى الْعَرْشِ يَعْلَمُ ما يَلِجُ فِي الْأَرْضِ وَما يَخْرُجُ مِنْها وَما يَنْزِلُ مِنَ السَّماءِ وَما يَعْرُجُ فِيها وَهُوَ مَعَكُمْ أَيْنَ ما كُنْتُمْ وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ (4) الخفي بحقيقته لا يعلم حقيقته إلا هو تعالى ( وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ ) يعلم كل شيء ، كما أنه يقدر على كل شيء ـ كما تقدم في الآية السابقة ـ .` },
            { text: "هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `اليوم قطعة من الزمان ولعل المراد ستة مليارات من السنوات فقد ثبت في بعض تحقيقات العلم الحديث خلقهما في مثل هذه المدة ( ثُمَّ اسْتَوى عَلَى الْعَرْشِ ) استولى على عرش الإرادة إذ قبل ذلك كان من باب السالبة بانتفاء الموضوع ، فالاستواء على العرش كناية عن التصرف في الكون ، فهو مثل قول الشاعر : رأيت الوليد بن اليزيد مباركا شديدا بأعباء الخلافة كاهله هذا « الاستيلاء » من ناحية القدرة أما من ناحية العلم فإنه سبحانه ( يَعْلَمُ ما يَلِجُ ) يدخل ( فِي الْأَرْضِ ) كالبذر والميت ( وَما يَخْرُجُ مِنْها ) كالنبات والحيوان الذي يخلق تحت الأرض ثم يخرج منها ( وَما يَنْزِلُ مِنَ السَّماءِ ) كالمطر ( وَما يَعْرُجُ فِيها ) يصعد إليها كالدخان والأبخرة ( وَهُوَ مَعَكُمْ ) علما وقدرة إذ علمه نافذ فينا وقدرته محيطة بنا ( أَيْنَ ما كُنْتُمْ ) في بر أو بحر في نور أم ظلام في عراء أو بناء ( وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ ) يراكم ، والبصر غير العلم كما هو واضح فإن علمنا لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ (5) يُولِجُ اللَّيْلَ فِي النَّهارِ وَيُولِجُ النَّهارَ فِي اللَّيْلِ وَهُوَ عَلِيمٌ بِذاتِ الصُّدُورِ (6) آمِنُوا بِاللهِ وَرَسُولِهِ وَأَنْفِقُوا مِمَّا جَعَلَكُمْ مُسْتَخْلَفِينَ بالشيء ولا نراه ، غير أن نعلم به ونراه ، أما كيفية رؤية الله فهي مجهولة مثل كيفية علمه وسائر الأمور المرتبطة بذاته تعالى.` },
            { text: "لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ", tafsir: `أعاد ذكره لأن الآية السابقة كانت كالاستدلال لذلك ، بخلاف ما ذكره سبحانه أولا ، حيث إنه لم يتقدم له استدلال ـ في هذه السورة ـ ( وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ ) فإذا أراد الإنسان شيئا فإن قدره سبحانه صار وإلا لم يصر كما أن الموظفين إذا أرادوا شيئا أرجع إلى الرئيس إن قبله صار وإلا لم يصر ، وهذا كناية عن أن الإرادة النهائية له تعالى.` },
            { text: "يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ", tafsir: `يدخل الله ( اللَّيْلَ فِي النَّهارِ ) أي يأخذ الليل مكان النهار ، إذا طال الليل ، أو المراد أن عمودا من الظلام يدخل في ضوء النهار ثم ينتشر الظلام إلى أن يأخذ الأفق ، فإن من يلاحظ الكرة الأرضية والشمس يعلم أن ظل الأرض كالعامود الذي يخترق نور الشمس ( وَيُولِجُ النَّهارَ فِي اللَّيْلِ ) فيه الاحتمالان السابقان ، ولذا يرى نور النهار أول الفجر كالخيط في طرف المشرق ، ثم يتوسع حتى يشمل النور الأفق ( وَهُوَ ) سبحانه ( عَلِيمٌ بِذاتِ الصُّدُورِ ) « الذات » الحقيقة ، وكأنه كناية عما في الصدور ، لا بد وأن يكون محيطا به عالما بما فيه.` },
            { text: "ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌ كَبِيرٌ", tafsir: `أيها الكفار ، أو عمّقوا إيمانكم أيها المؤمنون ( وَأَنْفِقُوا مِمَّا جَعَلَكُمْ مُسْتَخْلَفِينَ ) استخلفكم وجعلكم خلفاء لمن فِيهِ فَالَّذِينَ آمَنُوا مِنْكُمْ وَأَنْفَقُوا لَهُمْ أَجْرٌ كَبِيرٌ (7) وَما لَكُمْ لا تُؤْمِنُونَ بِاللهِ وَالرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثاقَكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ (8) هُوَ الَّذِي يُنَزِّلُ عَلى عَبْدِهِ آياتٍ بَيِّناتٍ لِيُخْرِجَكُمْ مِنَ الظُّلُماتِ إِلَى النُّورِ قبلكم ( فِيهِ ) في ذلك المال ، إذ كان المال لغيرنا ثم صار لنا وهكذا جيلا بعد جيل كل جيل خليفة سابقه ، كناية عن أن المال ليس لكم ، وإنما كان لغيركم ثم يكون من بعدكم لغيركم أيضا فإن الذين ( آمَنُوا مِنْكُمْ وَأَنْفَقُوا ) من أموالهم ( لَهُمْ أَجْرٌ كَبِيرٌ ) في الدنيا بالرفاه والسعادة وفي الآخرة بجنة عرضها السماوات والأرض.` },
            { text: "وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ", tafsir: `أيّ شيء لكم إذن ( لا تُؤْمِنُونَ بِاللهِ ) ؟ فهل لكم فائدة من عدم إيمانكم ( وَ ) الحال إن ( الرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا بِرَبِّكُمْ ) ويقيم لكم الحجج والآيات ( وَقَدْ أَخَذَ ) الله ( مِيثاقَكُمْ ) عهدكم الغليظ في عالم الذر ، وأودع فيكم الفطرة التي تدل على صحة ما جاء به الرسول إذ يجد كل إنسان في نفسه قبول الحق وليس هذا إلا أن شيئا مودع فيه يلجؤه إلى الاعتراف باطنا سواء اعترف ظاهرا أم لا ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) لشيء ما ، فإن تنبيه الرسول ودلالة العقول من أقوى موجبات الإيمان ، وهذا مثل ما يقال « إن كنت تفهم فافهم أن الشيء الفلاني ينفعك » .` },
            { text: "هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَٰتٍۭ بَيِّنَٰتٍ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌ رَّحِيمٌ", tafsir: `الله ( الَّذِي يُنَزِّلُ عَلى عَبْدِهِ ) محمدا صلى‌الله‌عليه‌وآله‌وسلم ( آياتٍ بَيِّناتٍ ) واضحات ( لِيُخْرِجَكُمْ ) أيها البشر ( مِنَ الظُّلُماتِ ) ظلمات الكفر والجهل ( إِلَى النُّورِ ) نور الإيمان والعلم ، فإن الكفر والجهل يسببان عدم رؤية الإنسان للحقائق ، كما أن الظلام يسبب عدم رؤية الإنسان وَإِنَّ اللهَ بِكُمْ لَرَؤُفٌ رَحِيمٌ (9) وَما لَكُمْ أَلاَّ تُنْفِقُوا فِي سَبِيلِ اللهِ وَلِلَّهِ مِيراثُ السَّماواتِ وَالْأَرْضِ لا يَسْتَوِي مِنْكُمْ مَنْ أَنْفَقَ مِنْ قَبْلِ الْفَتْحِ وَقاتَلَ أُولئِكَ أَعْظَمُ دَرَجَةً مِنَ الَّذِينَ أَنْفَقُوا مِنْ بَعْدُ وَقاتَلُوا وَكُلاًّ وَعَدَ اللهُ الْحُسْنى وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ (10) للأشياء ( وَإِنَّ اللهَ ) الواو للحال ، أو العطف ( بِكُمْ ) أيها البشر ( لَرَؤُفٌ ) الرأفة يقال للعطف قبل ظهوره أو دقة الرحمة ( رَحِيمٌ ) عطف يظهر أثره أو مطلق الرحمة.` },
            { text: "وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَٰتَلَ أُو۟لَٰٓئِكَ أَعْظَمُ دَرَجَةً مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَٰتَلُوا۟ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ", tafsir: `أيّ شيء لكم من عدم إنفاقكم ( فِي سَبِيلِ اللهِ ) في طريقه المؤدية إلى رضوانه ( وَلِلَّهِ مِيراثُ السَّماواتِ وَالْأَرْضِ ) وإذا لم تنفقوا يبقى المال وتموتون ، ولم تستفيدوا منه في تحصيل الدرجات العالية ، فإن كل من في السماوات ومن في الأرض يموتون وتبقى أموالهم وما كان في أيديهم لله وحده ( لا يَسْتَوِي مِنْكُمْ مَنْ أَنْفَقَ مِنْ قَبْلِ الْفَتْحِ ) فتح مكة ( وَقاتَلَ ) قبل الفتح ، حيث الإسلام غريب وبحاجة شديدة إلى المقاتلين وإلى المال ، ومن أنفق وقاتل بعد فتح مكة حيث أعز الله الإسلام ، وذهب الخوف من المسلمين ، وكثرت الغنائم ، وحذف هذا الشق لوضوحه ( أُولئِكَ ) المنفقون المقاتلون قبل الفتح ( أَعْظَمُ دَرَجَةً مِنَ الَّذِينَ أَنْفَقُوا مِنْ بَعْدُ ) الفتح ( وَقاتَلُوا ) بعد الفتح ( وَكُلًّا ) من المنفق والمقاتل قبلا ، وبعدا ( وَعَدَ اللهُ الْحُسْنى ) أي المثوبة الحسنى وهذا الكلام لئلّا يزعم تساويهما لا لبيان تبرير المتقاعس قبلا ، إذ المتقاعس له وزر ( وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ ) مَنْ ذَا الَّذِي يُقْرِضُ اللهَ قَرْضاً حَسَناً فَيُضاعِفَهُ لَهُ وَلَهُ أَجْرٌ كَرِيمٌ (11) يَوْمَ تَرَى الْمُؤْمِنِينَ وَالْمُؤْمِناتِ يَسْعى نُورُهُمْ بَيْنَ أَيْدِيهِمْ وَبِأَيْمانِهِمْ بُشْراكُمُ الْيَوْمَ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ فيجازيكم حسب أعمالكم. [12] ثم إن الذي يعطي ماله في سبيل الله فهو قرض يسترجع أكثر منه في دنياه وآخرته ، أما الآخرة فالمثوبة ، وأما الدنيا فلأن الإنفاق يوجب تقدم الاجتماع ، والاجتماع المتقدم يرتفع أفراده أكثر ، وبذلك يكون مالهم أكثر ، ولذا قال سبحانه ( وَيُرْبِي الصَّدَقاتِ ) (1) ( مَنْ ذَا ) الشخص ( الَّذِي يُقْرِضُ اللهَ قَرْضاً حَسَناً ) مقابل القرض السيئ الذي لا إخلاص له أو كان لأجل تحصيل الربا بالزيادة ( فَيُضاعِفَهُ ) الله ( لَهُ ) لأن الله يجعل كل حسنة أضعافا ثم يردها على صاحبها ( وَلَهُ أَجْرٌ كَرِيمٌ ) فإن الأجر لأصل القرض « بالإضافة إلى ما يضاف إليه من الزيادة » كريم في نفسه يرجع إلى صاحبه مع الإكرام له. [13] وتلك المضاعفة والأجر إنما هو في ( يَوْمَ ) القيامة حيث ( تَرَى الْمُؤْمِنِينَ وَالْمُؤْمِناتِ يَسْعى نُورُهُمْ ) مثلا نورهم عمود له امتداد ميل ، فإذا تحركوا تحرك النور ، فكأنه يسعى ( بَيْنَ أَيْدِيهِمْ وَبِأَيْمانِهِمْ ) فإن لهم نورا من هذين الجانبين ، ولعل ما كان من بين أيديهم للمقربين ، وما كان بأيمانهم لأصحاب اليمين ، ليكون علامة لمنزلتهم ، أو لأن صحائفهم تعطى من طرف اليمين من الأمام ، ويقال لهم ( بُشْراكُمُ ) بشارة لكم ( الْيَوْمَ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) من ( 1) البقرة : 277. خالِدِينَ فِيها ذلِكَ هُوَ الْفَوْزُ الْعَظِيمُ (12) يَوْمَ يَقُولُ الْمُنافِقُونَ وَالْمُنافِقاتُ لِلَّذِينَ آمَنُوا انْظُرُونا نَقْتَبِسْ مِنْ نُورِكُمْ قِيلَ ارْجِعُوا وَراءَكُمْ فَالْتَمِسُوا نُوراً فَضُرِبَ بَيْنَهُمْ بِسُورٍ لَهُ بابٌ باطِنُهُ فِيهِ الرَّحْمَةُ وَظاهِرُهُ مِنْ قِبَلِهِ الْعَذابُ (13) تحت أشجارها ، في حال كونهم ( خالِدِينَ فِيها ) أبدا ( ذلِكَ هُوَ الْفَوْزُ ) النجاح ( الْعَظِيمُ ) الذي ليس مثله فوز. [14] وذلك في ( يَوْمَ يَقُولُ الْمُنافِقُونَ وَالْمُنافِقاتُ لِلَّذِينَ آمَنُوا ) وهم يعيشون في ظلام شديد ( انْظُرُونا ) انظروا إلينا حيث يتوجه عمود نوركم إلى جانبنا ل ( نَقْتَبِسْ مِنْ نُورِكُمْ ) حتى نرى طريقنا ونتعرف إلى أوضاع بدننا ، لأن الإنسان في الظلام لا يرى طريقه ، ولا يتعرف على أوضاع جسده ، وإنما ذكرت الآية المنافقين ، ولم تذكر الكفار ، لأن الكفار في مكان آخر ، وإنما يحشر جميع من كان ظاهره الإيمان في مكان واحد ، ثم يميّزون ( قِيلَ ) لهم في جوابهم ( ارْجِعُوا وَراءَكُمْ ) إلى الدنيا ( فَالْتَمِسُوا ) فحصّلوا هناك ( نُوراً ) كناية عن أن النور إنما يحصل في الدنيا لا في الآخرة. ( فَضُرِبَ بَيْنَهُمْ ) بين المؤمنين والمنافقين ( بِسُورٍ ) بحائط يكون فاصلا بينهما ( لَهُ بابٌ ) لمرور الملائكة أو لأجل أن يميز المؤمن من المنافق ، حيث كانا قبلا مختلطين فمن كان في طرف المؤمنين من المنافقين أخرج من الباب إلى المنافقين ، وبالعكس ( باطِنُهُ ) حيث المؤمنون ( فِيهِ الرَّحْمَةُ ) وسمي باطنا لأنه المكان الأحسن المحفوظ كباطن حائط الدار ( وَظاهِرُهُ ) طرف المنافقين ( مِنْ قِبَلِهِ ) من جهته ( الْعَذابُ ) . يُنادُونَهُمْ أَ لَمْ نَكُنْ مَعَكُمْ قالُوا بَلى وَلكِنَّكُمْ فَتَنْتُمْ أَنْفُسَكُمْ وَتَرَبَّصْتُمْ وَارْتَبْتُمْ وَغَرَّتْكُمُ الْأَمانِيُّ حَتَّى جاءَ أَمْرُ اللهِ وَغَرَّكُمْ بِاللهِ الْغَرُورُ (14) فَالْيَوْمَ لا يُؤْخَذُ مِنْكُمْ فِدْيَةٌ وَلا مِنَ الَّذِينَ كَفَرُوا مَأْواكُمُ النَّارُ هِيَ مَوْلاكُمْ وَبِئْسَ الْمَصِيرُ (15) [15] وحين ذاك ( يُنادُونَهُمْ ) ينادي المنافقون المؤمنين ( أَ لَمْ نَكُنْ مَعَكُمْ ) في دار الدنيا نعمل الأعمال الصالحة معا فكيف صرتم أنتم في رحمة ونحن في العذاب ؟ ( قالُوا ) المؤمنون ( بَلى ) كنتم معنا في الظاهر ( وَلكِنَّكُمْ فَتَنْتُمْ أَنْفُسَكُمْ ) أي حرفتم أنفسكم عن الحق بسبب نفاقكم وعصيانكم ( وَتَرَبَّصْتُمْ ) في إطاعة أوامر الله ، فلم تسارعوا إليها كما سارع المؤمنون فإن من عادة المنافق أن لا يدخل في جهاد ولا خير ، وإنما يقول : دعنا نرى ماذا تكون العاقبة ( وَارْتَبْتُمْ ) شككتم في الدين ( وَغَرَّتْكُمُ ) خدعتكم ( الْأَمانِيُ ) جمع أمنية ، مثل « أغاني جمع أغنية » فإن المنافق لا يجاهد رجاء أن لا يصادف بأذى ، ولا ينفق رجاء أن يزيد تجارته ، ولا يحضر الخير رجاء أن يقدم عمله الدنيوي وهكذا ( حَتَّى جاءَ أَمْرُ اللهِ ) تقدم دينه ولم يكن لكم نصيب في ذلك ( وَغَرَّكُمْ بِاللهِ ) خدعكم بالاستهانة بأمر الله ( الْغَرُورُ ) الشيطان الذي هو كثير الخدعة.` },
            { text: "مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌ كَرِيمٌ", tafsir: `` },
            { text: "يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `` },
            { text: "يَوْمَ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًا فَضُرِبَ بَيْنَهُم بِسُورٍ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ", tafsir: `` },
            { text: "يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ قَالُوا۟ بَلَىٰ وَلَٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ", tafsir: `` },
            { text: "فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ مَأْوَىٰكُمُ ٱلنَّارُ هِىَ مَوْلَىٰكُمْ وَبِئْسَ ٱلْمَصِيرُ", tafsir: `في يوم الحساب ( لا يُؤْخَذُ مِنْكُمْ فِدْيَةٌ ) فداء في مقابل أن تخلصوا من نار جهنم ( وَلا مِنَ الَّذِينَ كَفَرُوا ) إذ في الآخرة لا ينفع إلا الإيمان والعمل الصالح ( مَأْواكُمُ النَّارُ ) محلكم الذي تأوون إليه نار جهنم ( هِيَ مَوْلاكُمْ ) أولى بكم ( وَبِئْسَ الْمَصِيرُ ) إنه مصير سيء. أَ لَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللهِ وَما نَزَلَ مِنَ الْحَقِّ وَلا يَكُونُوا كَالَّذِينَ أُوتُوا الْكِتابَ مِنْ قَبْلُ فَطالَ عَلَيْهِمُ الْأَمَدُ فَقَسَتْ قُلُوبُهُمْ وَكَثِيرٌ مِنْهُمْ فاسِقُونَ (16) اعْلَمُوا أَنَّ اللهَ يُحْيِ الْأَرْضَ بَعْدَ مَوْتِها [17] وإذا عرف الفرق بين المؤمن حقيقة والمؤمن صورة « المنافق واقعا » ف ( أَ لَمْ يَأْنِ ) ألم يصل الآن أي الوقت ( لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللهِ ) فتكون قلوبهم مصدقة لما لفظوا بألسنتهم من الشهادتين ( وَ ) ل ( ما نَزَلَ مِنَ الْحَقِ ) فيقبلوا قلبا كلما جاء به الرسول صلى‌الله‌عليه‌وآله‌وسلم ، ثم إذا آمنتم أيها المنافقون قلبا ، وأنتم أيها المؤمنون ظاهرا وباطنا ، اعلموا إن من شرط الإيمان المنجي البقاء على الإيمان وعدم الانحراف ( وَلا يَكُونُوا ) أولئك المؤمنون ( كَالَّذِينَ أُوتُوا الْكِتابَ مِنْ قَبْلُ ) كتاب موسى عليه‌السلام وغيره من الأنبياء ( فَطالَ عَلَيْهِمُ الْأَمَدُ ) الزمن ( فَقَسَتْ قُلُوبُهُمْ ) لم تكن لها شفافية ولين قلوب المعاصرين للأنبياء ، في عصر الرسالة ، حيث كانوا يخضعون لأوامر الله سبحانه ، لما لهم من لين وطهارة وشفافية ( وَكَثِيرٌ مِنْهُمْ فاسِقُونَ ) خرجوا عن الطاعة ، فالباقي منهم قسى قلبه ، وغير الباقي خرج عن الطريق. [18] لكن الله لا يترك دينه بين ذاك وهذا بل إنه كما يحيي الأرض بعد اليباب يحيي الدين بعد الاندراس ( اعْلَمُوا أَنَّ اللهَ يُحْيِ الْأَرْضَ بَعْدَ مَوْتِها ) بسبب المطر ، وكيفية تحديد الله للأمم ، أن الأمة السابقة تأخذها النخوة والغرور فلا تعمل صحيحا بل تأخذ في عمل الباطل ، وأمة جديدة صفت أذهانها عن الرواسب والأنانيات تأخذ في العمل قَدْ بَيَّنَّا لَكُمُ الْآياتِ لَعَلَّكُمْ تَعْقِلُونَ (17) إِنَّ الْمُصَّدِّقِينَ وَالْمُصَّدِّقاتِ وَأَقْرَضُوا اللهَ قَرْضاً حَسَناً يُضاعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ (18) وَالَّذِينَ آمَنُوا بِاللهِ وَرُسُلِهِ أُولئِكَ هُمُ الصِّدِّيقُونَ وَالشُّهَداءُ عِنْدَ رَبِّهِمْ ولذا تأخذ مكان الأمة السابقة ، وقد جعل الإسلام الشورى في الحكم وكون رئيس الدولة المجتهد العادل المخالف لهواه المطيع لأمر مولاه ضامنا لبقاء الإسلام غصنا طريا ( قَدْ بَيَّنَّا لَكُمُ الْآياتِ ) الدلالات الواضحات على صحة ما نقول ( لَعَلَّكُمْ تَعْقِلُونَ ) تفهمون ما نقول وتعملون بموجبه. [19] وحيث كان الكلام قبلا في إعطاء المال في سبيل الله رجع الكلام إليه فقال سبحانه ( إِنَّ الْمُصَّدِّقِينَ وَالْمُصَّدِّقاتِ ) أصله « تصدق » أي أعطى الصدقة ( وَ ) الذين ( أَقْرَضُوا اللهَ قَرْضاً حَسَناً ) وإنما سميت الصدقة صدقة ، لأنها تصديق لله في ما يقول فالمعنى إن الذي صدق الله في إعطاء المال ، وقد جعله قرضا حسنا ( يُضاعَفُ لَهُمْ ) عند رد ما أعطوا ( وَلَهُمْ أَجْرٌ كَرِيمٌ ) وقد تقدم تفسير الآية ، فلا حاجة إلى التكرار. [20] نعم إنه لا ينفع مجرد إعطاء الصدقة إذا لم يكن كامل الإيمان ولذا قال سبحانه ( وَالَّذِينَ آمَنُوا بِاللهِ وَرُسُلِهِ ) فشرط القبول الإيمان بالله والرسول وإعطاء الصدقة قرضا حسنا بإخلاص وبدون ربا ( أُولئِكَ هُمُ الصِّدِّيقُونَ ) لكثرة تصديقهم لأنهم صدقوا بالله وبكل أنبيائه وبما وعد من إعطائهم المال ، إلى غير ذلك ( وَالشُّهَداءُ عِنْدَ رَبِّهِمْ ) لأن الله يجعلهم شهداء على غيرهم ، في الآخرة ، إذ الإنسان العادل المعتدل لَهُمْ أَجْرُهُمْ وَنُورُهُمْ وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآياتِنا أُولئِكَ أَصْحابُ الْجَحِيمِ (19) اعْلَمُوا أَنَّمَا الْحَياةُ الدُّنْيا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفاخُرٌ بَيْنَكُمْ وَتَكاثُرٌ فِي الْأَمْوالِ وَالْأَوْلادِ كَمَثَلِ غَيْثٍ أَعْجَبَ الْكُفَّارَ نَباتُهُ ثُمَّ يَهِيجُ فَتَراهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطاماً في سلوكه يكون شاهدا على غيره ( لَهُمْ ) لهؤلاء المؤمنين المصدقين ( أَجْرُهُمْ ) أجر الصديقين ( وَنُورُهُمْ ) ونور الصديقين ( وَ ) بالعكس منهم ( الَّذِينَ كَفَرُوا وَكَذَّبُوا بِآياتِنا ) فلم يؤمنوا ولم يعملوا صالحا ( أُولئِكَ أَصْحابُ الْجَحِيمِ ) لا أجر حسن لهم ، ولا نور لهم ، بل يعيشون في حر النار وظلام الدخان.` },
            { text: "أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ", tafsir: `` },
            { text: "ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ", tafsir: `` },
            { text: "إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ", tafsir: `` },
            { text: "وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ", tafsir: `` },
            { text: "ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطَٰمًا وَفِى ٱلْـَٔاخِرَةِ عَذَابٌ شَدِيدٌ وَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرِضْوَٰنٌ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ", tafsir: `فهي صورة للآخرة الحقيقية ، مثل ملاعب الأطفال التي هي صورة للأشياء الحقيقية في الدنيا ( وَلَهْوٌ ) تلهي الإنسان عن الواقع الذي هو الآخرة ( وَزِينَةٌ ) مظهر لا واقع له كما يتزين الإنسان ببعض المظاهر التي لا تغير من الواقع شيئا ( وَتَفاخُرٌ بَيْنَكُمْ ) يفتخر الإنسان على إنسان ثان وبالعكس وهي حالة بدائية يتصف بها الأطفال ( وَتَكاثُرٌ فِي الْأَمْوالِ وَالْأَوْلادِ ) حيث كل ما يريد أن يكون أكثر من الأخر مالا وولدا بينما لا يفيد أيهما له فائدة حقيقية ، ثم كل ذلك إلى الزوال والفناء ( كَمَثَلِ غَيْثٍ ) مطر ( أَعْجَبَ الْكُفَّارَ ) الزراع ( نَباتُهُ ) قد أعجبوا بها وفرحوا بما لا دوام له ولا بقاء ( ثُمَّ يَهِيجُ ) هيجانا إلى الفساد ( فَتَراهُ مُصْفَرًّا ) قد ذهب رونقه وجماله ( ثُمَّ يَكُونُ حُطاماً ) يابسا متكسرا فالدنيا في نضارتها الخلابة ثم سرعة زوالها مثل وَفِي الْآخِرَةِ عَذابٌ شَدِيدٌ وَمَغْفِرَةٌ مِنَ اللهِ وَرِضْوانٌ وَمَا الْحَياةُ الدُّنْيا إِلاَّ مَتاعُ الْغُرُورِ (20) سابِقُوا إِلى مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُها كَعَرْضِ السَّماءِ وَالْأَرْضِ أُعِدَّتْ لِلَّذِينَ آمَنُوا بِاللهِ وَرُسُلِهِ ذلِكَ فَضْلُ اللهِ يُؤْتِيهِ مَنْ يَشاءُ وَاللهُ النبات السريع الزوال هذا حال زينة الدنيا ، في الدنيا ( وَفِي الْآخِرَةِ عَذابٌ شَدِيدٌ وَ ) في قبال أهل الدنيا المغترين بها ، الذين مثل دنياهم ما تقدم أهل الآخرة الذين لهم ( مَغْفِرَةٌ مِنَ اللهِ وَرِضْوانٌ ) غفران لذنوبهم ورضي الله لهم الذي هو أعظم شيء لأنه نعمة روحية ، والنعمة الروحية أفضل من النعمة الجسدية ( وَمَا الْحَياةُ الدُّنْيا إِلَّا مَتاعُ الْغُرُورِ ) لمن أقبل إليها ولم يطلب بها الآخرة الباقية ، فإنها تغر الإنسان عن منافعه الواقعية. [22] وإذا عرف الإنسان حال الدنيا وحال الآخرة فليسرع إلى تحصيل الآخرة ( سابِقُوا ) من المسابقة تحريض لطلب الآخرة بكل سرعة ممكنة ، كما يفعل المسابق في الدنيا ( إِلى مَغْفِرَةٍ مِنْ رَبِّكُمْ ) أسباب الغفران ( وَجَنَّةٍ عَرْضُها ) سعتها ( كَعَرْضِ السَّماءِ وَالْأَرْضِ ) كسعتهما والفضاء وسيع جدا حتى أن كل السماء والأرض في جنبه كحبة أرز في صحراء غير متناهية ( أُعِدَّتْ ) هيأت تلك الجنة ( لِلَّذِينَ آمَنُوا بِاللهِ وَرُسُلِهِ ) فليتشوق إليها كل عاقل ( ذلِكَ ) إعطاء الجنة للمؤمنين ( فَضْلُ اللهِ ) لأنه ليس بواجب عليه سبحانه إعطاء الجنة للمطيع ( يُؤْتِيهِ مَنْ يَشاءُ ) ومشيئته تابعة للصلاح الذي لا يكون إلا للمؤمن العامل بالصالحات ( وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ (21) ما أَصابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ وَلا فِي أَنْفُسِكُمْ إِلاَّ فِي كِتابٍ مِنْ قَبْلِ أَنْ نَبْرَأَها إِنَّ ذلِكَ عَلَى اللهِ يَسِيرٌ (22) لِكَيْلا تَأْسَوْا عَلى ما فاتَكُمْ وَلا تَفْرَحُوا بِما آتاكُمْ ذُو الْفَضْلِ الْعَظِيمِ ) الذي لا يعرف مدى فضله وسعة رحمته إلا هو. [23] وحيث ذكر سبحانه وجوب القتال والإنفاق وشوق المطيعين بالجنان وأنذر المخالفين بالعقاب جاء دور بيان أن ما يصيب الإنسان عامة « والتي منها ما يصيبه حال الحرب من الموت والجرح وما أشبه » مثبوت عند الله ولا يضيع أجره ( ما أَصابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ ) كالجرب وأكل الجراد المزارع ( وَلا ) حرف عطف ( فِي أَنْفُسِكُمْ ) كالمرض والجرح ( إِلَّا ) مكتوبة ( فِي كِتابٍ ) ثابتة في علمنا ، ولعل المراد بالكتاب اللوح المحفوظ ( مِنْ قَبْلِ أَنْ نَبْرَأَها ) برأه بمعنى خلقه ( إِنَّ ذلِكَ ) كناية في كتاب من قبل تكونه ( عَلَى اللهِ يَسِيرٌ ) لأنه سبحانه عالم بما كان وبما يكون وبما هو كائن إلى الأبد ، والإشكال بأنه إذا كان سبحانه عالما لا يمكن تخلفه ، واضح الجواب : لأن العلم ليس بعلة ، كما أنك إذا علمت بطلوع الشمس غدا لا تكون علة لطلوعها. [24] وقد ذكرنا ذلك لكم بأنه ثابت في الكتاب ( لِكَيْلا تَأْسَوْا ) لا تحزنوا ( عَلى ما فاتَكُمْ ) من نعم الدنيا ، وقد ذكر سبحانه تبعا لذلك « وإن لم يكن الكلام منصبا عليه » قوله ( وَ ) لكي ( لا تَفْرَحُوا بِما آتاكُمْ ) أعطاكم من نعيم ، فإن من علم أن كل شيء يصيبه من خير وشر مقدر وَاللهُ لا يُحِبُّ كُلَّ مُخْتالٍ (23) الَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ وَمَنْ يَتَوَلَّ فَإِنَّ اللهَ هُوَ الْغَنِيُّ الْحَمِيدُ (24) كائن ، لا يحزن حزنا متزايدا ولا يفرح فرحا متزايدا ، لأن شدة الحزن والفرح ، لمحزن ولمفرح فجائي ، والعلم يرفع الفجائية ألا ترى أن من يعلم أن غدا يموت ولده لا يحزن مثل حزن من لا يعلم بذلك بل يفاجأ به ، إلى غير ذلك ثم المراد « عدم الحزن المخرج للإنسان إلى الجزع » و « عدم الفرح المخرج للإنسان إلى البطر » ( وَاللهُ لا يُحِبُّ كُلَّ مُخْتالٍ ) من اختال بمعنى تكبّر ( فَخُورٍ ) كثير الفخر ، فإن من فرح فرحا متزايدا بالنعمة ، ولم يخف عواقبها أخذ في الكبر والافتخار على الناس. [25] ومن هو المختال الفخور ؟ هم ( الَّذِينَ يَبْخَلُونَ ) عن الإنفاق فإن الذين يفرحون الفرح المطغي ممن لا يؤمن بأن المال جاءه بكتابة من الله ، وإنه زائل وله حساب دقيق « للتلازم بين العلم بالكتابة وبين التواضع والإنفاق ، كالتلازم بين عدم هذا العلم وبين التكبر والبخل » . ( وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ ) إذ البخلاء يريدون بخل الناس حتى لا تقع اللائمة عليهم ( وَمَنْ يَتَوَلَ ) عن أوامر الله سبحانه فلا ينفق فليعلم أن الله أمر بالإنفاق لمصلحته هو لا لأن الله بحاجة إلى المال وإن ( اللهَ هُوَ الْغَنِيُ ) إذ غنى ما سوى الله مجازي ( الْحَمِيدُ ) فلا يحتاج إلى الإنفاق ليكثر المؤمنين حتى يحمدوه ، فإنه المحمود بالذات سواء حمده أحد أولا. لَقَدْ أَرْسَلْنا رُسُلَنا بِالْبَيِّناتِ وَأَنْزَلْنا مَعَهُمُ الْكِتابَ وَالْمِيزانَ لِيَقُومَ النَّاسُ بِالْقِسْطِ وَأَنْزَلْنَا الْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنافِعُ لِلنَّاسِ وَلِيَعْلَمَ اللهُ مَنْ يَنْصُرُهُ وَرُسُلَهُ بِالْغَيْبِ [26] ومن كونه غنيا حميدا يتبين أن إرساله الرسل والأحكام ليس لأجل حاجته وإنما لأجل الناس أنفسهم ( لَقَدْ أَرْسَلْنا رُسُلَنا بِالْبَيِّناتِ ) بالأدلة البينة الواضحة ( وَأَنْزَلْنا مَعَهُمُ الْكِتابَ ) جنس الكتب السماوية ( وَ ) أنزلنا ( الْمِيزانَ ) ومعنى إنزاله تقريره ، وحيث إنه من مكان رفيع معنى ، صح « أنزلنا » كما يقال هذه الأمور من فوق إذا كانت من الرئيس ، والمراد كل ميزان للحق والباطل ، سواء كانت موازين للأخلاق أو المعاملات أو المعاشرات أو الموازين الحديدية ونحوها ، لأن كل الموازين العلمية والعملية إنما قررها الله سبحانه ، ( لِيَقُومَ النَّاسُ بِالْقِسْطِ ) أي بالعدل ، فلا يظلم أحد أحدا ، فالكتاب لبيان الحكم ، والميزان لتطبيق ذلك الحكم على المجتمع ، ومن يخالف ؟ فله الحديد ( وَأَنْزَلْنَا الْحَدِيدَ ) إنزاله باعتبار تقديره في السماء ( فِيهِ بَأْسٌ شَدِيدٌ ) بالقتل والقصاص ونحوهما ( وَ ) فيه ( مَنافِعُ لِلنَّاسِ ) لأن كثيرا من الحاجات تكون بسبب الحديد ( وَلِيَعْلَمَ اللهُ ) عطف على فيه بأس ، أي أنزلنا الحديد للبأس والمنفعة والامتحان ( مَنْ يَنْصُرُهُ وَ ) ينصر ( رُسُلَهُ ) إذ استعمال الأسلحة الحديدية في مجاهدة الكفار نصرة لله ولرسله ( بِالْغَيْبِ ) في حال كون الله ، أو الرسول غائبا عنهم إذ الناس لا يرون الله ، وكثيرا لا يرون الرسول ، ومع ذلك يجاهدون ، ومعنى « ليعلم الله » أي ليتحقق علمه في الخارج ، لكن ليس طلب الله للنصرة عن إِنَّ اللهَ قَوِيٌّ عَزِيزٌ (25) وَلَقَدْ أَرْسَلْنا نُوحاً وَإِبْراهِيمَ وَجَعَلْنا فِي ذُرِّيَّتِهِمَا النُّبُوَّةَ وَالْكِتابَ فَمِنْهُمْ مُهْتَدٍ وَكَثِيرٌ مِنْهُمْ فاسِقُونَ (26) ثُمَّ قَفَّيْنا عَلى آثارِهِمْ بِرُسُلِنا وَقَفَّيْنا بِعِيسَى ابْنِ مَرْيَمَ وَآتَيْناهُ الْإِنْجِيلَ وَجَعَلْنا فِي قُلُوبِ الَّذِينَ اتَّبَعُوهُ احتياج ف ( إِنَّ اللهَ قَوِيٌ ) على إهلاك من يريد ( عَزِيزٌ ) لا يحتاج إلى أحد ، وإنما أمر بالجهاد لينتفع الناس بالجهاد في دنياهم وآخرتهم. [27] ثم ذكر سبحانه بعض أفراد الرسل ( وَلَقَدْ أَرْسَلْنا نُوحاً وَإِبْراهِيمَ وَجَعَلْنا فِي ذُرِّيَّتِهِمَا النُّبُوَّةَ ) فقد كان بعض ذريتهما أنبياء ( وَالْكِتابَ ) أعطينا بعضهم كتبا جديدة ( فَمِنْهُمْ ) من ذريتهما ( مُهْتَدٍ ) اهتدى بالأنبياء ( وَكَثِيرٌ مِنْهُمْ ) أي من أولئك الذرية ( فاسِقُونَ ) خارجون عن طاعة الله سبحانه.` },
            { text: "سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ", tafsir: `` },
            { text: "مَآ أَصَابَ مِن مُّصِيبَةٍ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَٰبٍ مِّن قَبْلِ أَن نَّبْرَأَهَآ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ", tafsir: `` },
            { text: "لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ", tafsir: `` },
            { text: "ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ", tafsir: `` },
            { text: "لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ", tafsir: `` },
            { text: "وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ فَمِنْهُم مُّهْتَدٍ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ", tafsir: `` },
            { text: "ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةً وَرَحْمَةً وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ", tafsir: `بعد نوح وإبراهيم عليهما‌السلام ( قَفَّيْنا ) أتبعنا ( عَلى آثارِهِمْ ) آثار ذينك النبيين وذريتهما ( بِرُسُلِنا ) أرسلنا رسولا بعد رسول ( وَقَفَّيْنا ) أتبعنا ( بِعِيسَى ابْنِ مَرْيَمَ ) رسلا أيضا ولعل عدم ذكر موسى عليه‌السلام أن الكلام في الأول والوسط والآخر فنوح أول « نبي » وإبراهيم وسط كذلك ، وعيسى آخر قبل نبي الإسلام صلى‌الله‌عليه‌وآله‌وسلم ( وَآتَيْناهُ ) أعطيناه ( الْإِنْجِيلَ ) فلما ذا ينكر النصارى الرسول وقرآنه أليس أرسل لهم رسولا وأعطوا كتابا ؟ ( وَجَعَلْنا فِي قُلُوبِ الَّذِينَ اتَّبَعُوهُ ) اتباعا حقيقيا رَأْفَةً وَرَحْمَةً وَرَهْبانِيَّةً ابْتَدَعُوها ما كَتَبْناها عَلَيْهِمْ إِلاَّ ابْتِغاءَ رِضْوانِ اللهِ فَما رَعَوْها حَقَّ رِعايَتِها فَآتَيْنَا الَّذِينَ آمَنُوا مِنْهُمْ أَجْرَهُمْ وَكَثِيرٌ مِ نْهُمْ فاسِقُونَ (27) لا من حرّف دينه وغيّر كتابه ( رَأْفَةً ) صفة داخل القلب ( وَرَحْمَةً ) صفة داخل القلب إذا ظهرت في الخارج ( وَرَهْبانِيَّةً ) مشتقة من رهبة بمعنى ما يظهر من العبادة على الجوارح من آثار رهبة القلب ، ورهبان جمع راهب ( ابْتَدَعُوها ) بدعة حسنة أي طبقوا أمر الله بالرهبة على كيفية خاصة فإن للإنسان أن يطبق الكلي على بعض أفراده ، مثل أن يطبق قوله صلى‌الله‌عليه‌وآله‌وسلم « الوقوف على حسب ما وقفها أهلها » على بناء المدرسة الدينية ، فهي مجعولة باعتبار جعل الله الكلي ، ومبتدعة باعتبار الفرد ، ولذا لا منافاة بين قوله تعالى « جعلنا » وبين قوله « ابتدعوها » ( ما كَتَبْناها ) الرهبانية ( عَلَيْهِمْ ) بالصيغة الخاصة ( إِلَّا ابْتِغاءَ رِضْوانِ اللهِ ) فإنهم لما ابتدعوها كتبناها عليهم بالصيغة الخاصة لأجل طلب رضى الله ، فهي مجعولة بالكلية ، مبتدعة بالصيغة الخاصة ، مكتوبة بعد ذلك لأجل رضى الله ( فَما رَعَوْها حَقَّ رِعايَتِها ) لأن الرؤوف الرحيم الراهب يجب عليه التصديق بما جاء من عند الله ، لكنهم بكفرهم بمحمد صلى‌الله‌عليه‌وآله‌وسلم ، وباختلافهم قبل ذلك ، وجعلهم الإله ثالث ثلاثة ، وبتحريفهم الإنجيل ، وبغشوتهم على الناس ، تركوا رعاية تلك الأوصاف ( فَآتَيْنَا ) أعطينا ( الَّذِينَ آمَنُوا مِنْهُمْ ) أي بقوا على إيمانهم ، لأن للإنسان في كل يوم إيمانا جديدا ( أَجْرَهُمْ ) الذي يستحقون بسبب بقائهم على إيمانهم ( وَكَثِيرٌ مِنْهُمْ فاسِقُونَ ) خارجون عن طاعة الله. يا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ وَآمِنُوا بِرَسُولِهِ يُؤْتِكُمْ كِفْلَيْنِ مِنْ رَحْمَتِهِ وَيَجْعَلْ لَكُمْ نُوراً تَمْشُونَ بِهِ وَيَغْفِرْ لَكُمْ وَاللهُ غَفُورٌ رَحِيمٌ (28) لِئَلاَّ يَعْلَمَ أَهْلُ الْكِتابِ أَلاَّ يَقْدِرُونَ عَلى شَيْءٍ مِنْ فَضْلِ` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ", tafsir: `بألسنتهم ( اتَّقُوا اللهَ ) في أعمالكم ( وَآمِنُوا بِرَسُولِهِ ) بمحمد صلى‌الله‌عليه‌وآله‌وسلم إيمانا صادقا لا يشوبه النفاق ، إذا آمنتم بالرسول إيمانا صادقا ( يُؤْتِكُمْ ) يعطكم الله ( كِفْلَيْنِ ) أي نصيبين ( مِنْ رَحْمَتِهِ ) نصيبا لأجل إيمانكم بالله ، ونصيبا لأجل إيمانكم برسوله والمراد أيها المؤمنون بعيسى عليه‌السلام آمنوا بمحمد صلى‌الله‌عليه‌وآله‌وسلم فيعطيكم الله رحمة لأجل إيمانكم بعيسى عليه‌السلام ورحمة لأجل إيمانكم بمحمد صلى‌الله‌عليه‌وآله‌وسلم ( وَيَجْعَلْ لَكُمْ نُوراً تَمْشُونَ بِهِ ) بين الناس فإن الإنسان المحكّم عقله والمتبع لله ورسوله يكون له نور يعرف به الحق من الباطل فيحكمه الناس في أمورهم ويستشيرون منه في أعمالهم كمن عنده المصباح في الليل المظلم حيث يستنير الناس بنور مصباحه ( وَيَغْفِرْ ) الله ( لَكُمْ ) ذنوبكم ( وَاللهُ غَفُورٌ ) كثير الغفران ( رَحِيمٌ ) بعباده فيغفر ذنوبهم ، ويعطيهم الجنة من رحمته. [30] يقال في العرف « إن المطلب كذا ، حتى لا يعلم زيد » أي أتركه حتى لا يعلم ، إذا كان إنسانا معاندا لا يريد العلم ، والظاهر من الآية هو هذا ، أي أن من آمن بالله والرسول له كفلان ونور وغفران ( لِئَلَّا يَعْلَمَ أَهْلُ الْكِتابِ ) أي اتركهم حتى لا يعلموا ، وإنما يتركون لأنهم معاندون ، فيبتدئ قوله سبحانه ( أَلَّا يَقْدِرُونَ عَلى شَيْءٍ مِنْ فَضْلِ اللهِ وَأَنَّ الْفَضْلَ بِيَدِ اللهِ يُؤْتِيهِ مَنْ يَشاءُ وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ (29) اللهِ ) أن مخففة من الثقيلة ، واسمه ضمير محذوف ، أي أنهم لا يقدرون على إعطاء أو منع شيء من فضل الله ، فلا يقدرون على منع فضله « بالكفيلين والنور والغفران » عن المسلمين ، كما لا يقدرون على منح مثل هذا الفضل لأنفسهم و « أن لا يقدرون » عطف على « لئلا يعلم » أي أنهم لا يعلمون الحق ، ولا يقدرون على صرف الأجر ( وَأَنَّ الْفَضْلَ بِيَدِ اللهِ ) وهذا تأكيد لبيان أنهم « لا ( يَقْدِرُونَ عَلى شَيْءٍ مِنْ فَضْلِ اللهِ ) ( يُؤْتِيهِ ) يعطي الله ذلك الفضل ل ( مَنْ يَشاءُ ) ممن اتبع أوامره ( وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ ) نسأله سبحانه أن يمنحنا من ذلك الفضل وهو المستعان. تقريب القرآن الى الأذهان من آية ( 1) سورة المجادلة إلى آية ( 13) سورة التحريم بسم الله الرحمن الرحيم الحمد لله رب العالمين والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين (58)` },
            { text: "لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّن فَضْلِ ٱللَّهِ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ", tafsir: `` }
        ]
    },
    58: { // سورة المجادلة
        name: "المجادلة",
        basmalaTafsir: ``,
        verses: [
            { text: "قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ", tafsir: `المرأة ( الَّتِي تُجادِلُكَ ) أي تراجعك وتتكلم معك يا رسول الله ( فِي ) أمر ( زَوْجِها ) واسم المرأة « خولة » واسم زوجها « أوس » ( وَتَشْتَكِي إِلَى اللهِ ) حالها وما نزل من المكروه ( وَاللهُ يَسْمَعُ تَحاوُرَكُما ) أي تخاطبكما أنتما يا رسول الله ، ويا أيتها المرأة ( إِنَّ اللهَ سَمِيعٌ ) يسمع الكلام ( بَصِيرٌ ) يبصر الأحوال ، فأنتما باطلاعه سبحانه استماعا وإبصارا ، قال في المجمع ـ بتلخيص ـ : نزلت الآيات في امرأة من الأنصار من خزرج. واسمها « خولة » وزوجها « أوس » وذلك أنها كانت حسنة الجسم فرآها زوجها ساجدة في صلاتها ، فلما انصرفت أرادها ، فأبت عليه ، فغضب عليها ، وكان امرءا فيه سرعة ولمم ، فقال لها : أنت عليّ كظهر أمي ، ثم ندم على ما قال ، وكان الظهار من طلاق أهل الجاهلية ، فقال لها : ما أظنك إلا وقد حرمت عليّ ، فقالت : لا تقل ذلك وأت رسول الله صلى‌الله‌عليه‌وآله‌وسلم فاسأله ؟ فقال : إني أجد أني أستحي من أن أسأله عن هذا. قالت : فدعني أسأله ؟ فقال : سليه فأتت النبي صلى‌الله‌عليه‌وآله‌وسلم فقالت : يا رسول الله إن زوجي أوس بن الصامت تزوجني وأنا شابة غنية ذات مال وأهل حتى إذا أكل مالي وأفنى شبابي ، وتفرق أهلي وكبر سني ظاهر مني ، وقد ندم فهل من شيء يجمعني وإياه فتنعشني به ؟ فقال : ما أراك إلا حرمت عليه ـ أراد صلى‌الله‌عليه‌وآله‌وسلم الحرمة الموقتة التي تحل بالكفارة ـ فقالت : يا رسول الله والذي أنزل عليك الكتاب ما ذكر طلاقا ، وأنه أبو ولدي وأحب الناس إلي ؟ فقال صلى‌الله‌عليه‌وآله‌وسلم : ما أراك إلا حرمت عليه ، ولم أؤمر في شأنك بشيء الَّذِينَ يُظاهِرُونَ مِنْكُمْ مِنْ نِسائِهِمْ ما هُنَّ أُمَّهاتِهِمْ إِنْ فجعلت تراجع رسول الله صلى‌الله‌عليه‌وآله‌وسلم ، وإذا قال لها رسول الله صلى‌الله‌عليه‌وآله‌وسلم حرمت عليه هتفت وقالت : اشكوا إلى الله فاقتي وحاجتي وشدة حالي ، اللهمّ فأنزل على لسان نبيك ، وكان هذا أول ظهار في الإسلام. وقالت : انظر في أمري جعلني الله فداك. فنزل على الرسول صلى‌الله‌عليه‌وآله‌وسلم الوحي ، ثم قال صلى‌الله‌عليه‌وآله‌وسلم : ادعي زوجك فتلا عليه رسول الله صلى‌الله‌عليه‌وآله‌وسلم « قد سمع الله » إلى تمام الآيات ، فقال صلى‌الله‌عليه‌وآله‌وسلم : هل تستطيع أن تعتق رقبة ؟ قال : إذا يذهب مالي كله والرقبة غالية وأنى قليل المال فقال صلى‌الله‌عليه‌وآله‌وسلم : هل تستطيع أن تصوم شهرين متتابعين ؟ فقال : و الله يا رسول الله إني إذا لم آكل ثلاث مرات كلّ بصري وخشيت أن تعشى عيني ، قال : فهل تستطيع أن تطعم ستين مسكينا ؟ قال : لا والله إلا أن تعينني على ذلك يا رسول الله ، فقال صلى‌الله‌عليه‌وآله‌وسلم : إني معينك بخمسة عشر صاعا وإني داع لك بالبركة ، فأعانه صلى‌الله‌عليه‌وآله‌وسلم بذلك (1) . [3] ثم بين سبحانه ذم « الظهار » بقوله ( الَّذِينَ يُظاهِرُونَ مِنْكُمْ ) أيها المؤمنون ( مِنْ نِسائِهِمْ ) أي يقولون لهن : « أنت كظهر أمي » فإن هذا اللفظ كان طلاقا في الجاهلية ، ومعناه : أنه كما يحرم على ظهر الأم ، كذلك تحرمين أيتها الزوجة علي ، وقد أقر الإسلام كون هذا اللفظ محرّما للزوجة ، إذا اجتمع فيه شروط الطلاق ، من كونه بمحضر العدلين وما أشبه ، إلا أنه حرم الطلاق بهذا النحو وجعل الرجوع فيه الكفارة ( ما هُنَ ) أي لسن الزوجات ، المقول فيهن هذا القول ( أُمَّهاتِهِمْ ) فإن مجرد اللفظ لا يجعل من الزوجة أمّا ( إِنْ ( 1) مجمع البيان : ج 9 ص 408. أُمَّهاتُهُمْ إِلاَّ اللاَّئِي وَلَدْنَهُمْ وَإِنَّهُمْ لَيَقُولُونَ مُنْكَراً مِنَ الْقَوْلِ وَزُوراً وَإِنَّ اللهَ لَعَفُوٌّ غَفُورٌ (2) وَالَّذِينَ يُظاهِرُونَ مِنْ نِسائِهِمْ ثُمَّ يَعُودُونَ لِما قالُوا فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا أُمَّهاتُهُمْ ) أي أمهات هؤلاء المظاهرين ( إِلَّا ) النساء ( اللَّائِي ) جمع التي ( وَلَدْنَهُمْ ) فلا أمومة حقيقية بين المظاهر والمظاهر منها ( وَإِنَّهُمْ لَيَقُولُونَ مُنْكَراً مِنَ الْقَوْلِ ) فإن تشبيه الزوجة بالأم قول منكر ، فلا شرعية لهذا القول ، وكل شيء لا يكون له حقيقة ولا شرعية فهو باطل ( وَزُوراً ) أي كذبا ، فإن المظاهر إذا جعل ظهر امرأته كظهر أمه ، ولم يكن بحقيقة كان كذبا ، لكن لا ييأس القائل من عفو الله وفضله فإن أبواب التوبة مفتوحة ( وَإِنَّ اللهَ لَعَفُوٌّ ) كثير العفو عن العصاة ( غَفُورٌ ) لذنوبهم. وأما الفرق أن العفو هو عدم العقاب ، وذلك لا يلازم الستر بحيث لا يكون ذنبه ظاهرا ، كما نرى أن الحكومات قد تعفوا عن مجرم لكن جرمه مذكور ثابت في الدفتر ، أما الغفران فهو الستر للمعصية ، حتى تمحى عن ديوانه سبحانه. [4] ثم جاء السياق ليبين حكم الظهار وما يترتب عليه ( وَالَّذِينَ يُظاهِرُونَ مِنْ نِسائِهِمْ ) المظاهرة مشتقة من « الظهر » والإتيان ب « من » لأن الظهر يبتدأ من جانب المرأة ( ثُمَّ يَعُودُونَ لِما قالُوا ) بأن يريدون الرجوع إلى النساء ونقض كلامهم السابق المقتضي للتحريم فاللازم عليهم لحلية الوطي ورجوع الزوجة كما كانت ( فَتَحْرِيرُ رَقَبَةٍ ) أي يجعل عبدا مملوكا حرا بالعتق ، وإنما قيل له رقبة بعلاقة الجزء والكل ( مِنْ قَبْلِ أَنْ يَتَمَاسَّا ) أي يمس أحد الزوجين الآخر ، وهو كناية عن الجماع ، فإن الجماع لا يحل قبل التحرير ذلِكُمْ تُوعَظُونَ بِهِ وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ (3) فَمَنْ لَمْ يَجِدْ فَصِيامُ شَهْرَيْنِ مُتَتابِعَيْنِ مِنْ قَبْلِ أَنْ يَتَمَاسَّا فَمَنْ لَمْ يَسْتَطِعْ فَإِطْعامُ سِتِّينَ مِسْكِيناً ذلِكَ لِتُؤْمِنُوا بِاللهِ وَرَسُولِهِ وَتِلْكَ ( ذلِكُمْ ) ذا إشارة إلى التحرير و « كم » خطاب ، أي أن وجوب التحرير عليكم مما ( تُوعَظُونَ بِهِ ) والوعظ هو التحرير عن عمل يوجب العقاب ، فإن ترك التحرير والمماسة موجب للعقاب لأنه عصيان ( وَاللهُ بِما تَعْمَلُونَ ) من المماسة بدون الكفارة أو بعدها ( خَبِيرٌ ) عالم مطلع ، فلا تفعلوا ما يوجب عليكم عقابا.` },
            { text: "ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمْ إِنْ أُمَّهَٰتُهُمْ إِلَّا ٱلَّٰٓـِٔى وَلَدْنَهُمْ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًا مِّنَ ٱلْقَوْلِ وَزُورًا وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ", tafsir: `` },
            { text: "وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍ مِّن قَبْلِ أَن يَتَمَآسَّا ذَٰلِكُمْ تُوعَظُونَ بِهِۦ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ", tafsir: `` },
            { text: "فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتِلْكَ حُدُودُ ٱللَّهِ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ", tafsir: `ظاهر من زوجته وأراد العود و ( لَمْ يَجِدْ ) أي لم يتمكن من عتق رقبة إما لعدم وجود المال لاشترائه ، أو لعدم وجود أصل العبد ـ كما في زماننا ـ فكفارته صيام ( شَهْرَيْنِ مُتَتابِعَيْنِ ) التتابع هو التوالي ومجيء الواحد بعقب الآخر ، أي أن يصوم شهرين بلا فصل إفطار يوم بين أيام الشهرين ( مِنْ قَبْلِ أَنْ يَتَمَاسَّا ) أي يجامعا الرجل والمرأة ( فَمَنْ ) ظاهر و ( لَمْ يَسْتَطِعْ ) العتق ولا الصيام وأراد الرجوع فعليه إطعام ( سِتِّينَ مِسْكِيناً ) أي فقيرا بأن يشبع بطنهم أو يعطي لكل واحد ثلاثة أرباع من الحنطة ـ مثلا ـ ( ذلِكَ ) الحكم بالكفارة للمظاهر المريد للعود إنما شرع ( لِتُؤْمِنُوا بِاللهِ وَرَسُولِهِ ) أي ليرسخ الإيمان في قلوبكم فإن رسوخ الإيمان إنما هو بتتابع الأعمال والتكاليف ، فإن التكاليف توقظ القلب وتقوي الملكة فيه ، وحيث إن الإيمان كسائر الصفات شيء تدريجي يحدث آنا بعد آن ، صح الإتيان بالفعل باعتبار المستقبل ، كقوله « اهدنا الصراط » وقد تقدم تفصيله ( وَتِلْكَ ) الكفارات حُدُودُ اللهِ وَلِلْكافِرِينَ عَذابٌ أَلِيمٌ (4) إِنَّ الَّذِينَ يُحَادُّونَ اللهَ وَرَسُولَهُ كُبِتُوا كَما كُبِتَ الَّذِينَ مِنْ قَبْلِهِمْ وَقَدْ أَنْزَلْنا آياتٍ بَيِّناتٍ وَلِلْكافِرِينَ عَذابٌ مُهِينٌ (5) يَوْمَ يَبْعَثُهُمُ اللهُ جَمِيعاً فَيُنَبِّئُهُمْ بِما عَمِلُوا أَحْصاهُ اللهُ وَنَسُوهُ وَاللهُ عَلى كُلِّ ( حُدُودُ اللهِ ) أي هي الحدود للإيمان التي قررها الله سبحانه ، فلا يسمح للمؤمن الخروج منها ، بالعصيان ، كما لا يسمح للإنسان أن يخرج من حدود المدينة نحو الأعداء ( وَلِلْكافِرِينَ ) بحدود الله المنكرين لها ( عَذابٌ أَلِيمٌ ) مؤلم موجع.` },
            { text: "إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ وَقَدْ أَنزَلْنَآ ءَايَٰتٍۭ بَيِّنَٰتٍ وَلِلْكَٰفِرِينَ عَذَابٌ مُّهِينٌ", tafsir: `حاده بمعنى خالفه ( وَرَسُولَهُ ) بأن لا يمتثلون أوامرهما ( كُبِتُوا ) أي أذلوا وأخزوا ، من الكبت بمعنى الإذلال ( كَما كُبِتَ الَّذِينَ مِنْ قَبْلِهِمْ ) من الكفار والمشركين ، وإذلالهم بنصرة الإسلام عليهم في الدنيا ، وعذابهم في الآخرة ( وَقَدْ أَنْزَلْنا آياتٍ ) أي علائم وأدلة ( بَيِّناتٍ ) واضحات ظاهرات ، على أصول العقيدة ، وأحكام الشريعة ، فلا عذر للشخص أن يقول لم أعرف ولم أدر ( وَلِلْكافِرِينَ ) بالآيات ( عَذابٌ مُهِينٌ ) يهينهم ويذلهم. [7] والعذاب المهين إنما هو في ( يَوْمَ يَبْعَثُهُمُ اللهُ ) أي يحييهم ويحشرهم ( جَمِيعاً ) فلا يترك منهم أحد ، ولا مفر لأحد من بأسه سبحانه ( فَيُنَبِّئُهُمْ ) أي يخبرهم الله ( بِما عَمِلُوا ) إخبارا لأجل العذاب ، فإن المجرم يعد جرمه أولا ثم يعاقب لئلا يقول عذبت ظلما ( أَحْصاهُ اللهُ ) أي عدده سبحانه في كتابه وحفظه ( وَنَسُوهُ ) فإن الغالب إن الإنسان ينسى أعماله التي عمل بها ( وَاللهُ عَلى كُلِّ شَيْءٍ شَهِيدٌ (6) أَ لَمْ تَرَ أَنَّ اللهَ يَعْلَمُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ ما يَكُونُ مِنْ نَجْوى ثَلاثَةٍ إِلاَّ هُوَ رابِعُهُمْ وَلا خَمْسَةٍ إِلاَّ هُوَ سادِسُهُمْ وَلا أَدْنى مِنْ ذلِكَ وَلا أَكْثَرَ إِلاَّ هُوَ مَعَهُمْ أَيْنَ ما كانُوا ثُمَّ يُنَبِّئُهُمْ بِما عَمِلُوا يَوْمَ الْقِيامَةِ شَيْءٍ شَهِيدٌ ) أي شاهد حاضر ، فيعرف كل ما يصدر من الإنسان ، ويأمر الملائكة بتثبيته ، ليجازي به يوم القيامة.` },
            { text: "يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ", tafsir: `` },
            { text: "أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ", tafsir: `أي ألم تدرك ، فإن الرؤية قد تكون بالعين ، وقد تكون بالقلب ، والمخاطب هو الرسول أو كل من يتأتى منه العلم ( أَنَّ اللهَ يَعْلَمُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) لا يغيب عنه شيء من الأشياء ؟ فكيف لا يعلم أعمال الجاحدين والكافرين ؟ والاستفهام تقريري ، وهو بمثابة الدليل لقوله ( يُنَبِّئُهُمْ بِما عَمِلُوا ) و ( اللهُ عَلى كُلِّ شَيْءٍ شَهِيدٌ ) ثم أكد عموم علمه سبحانه بأنه شامل حتى للأسرار التي يفضي بها الإنسان إلى إنسان سرّا وفي إخفات ( ما يَكُونُ مِنْ نَجْوى ) « من » زائدة لعموم النفي ، و « النجوى » هو الحديث السري يدور بين اثنين أو أكثر في منأى من الناس ( ثَلاثَةٍ ) أي ثلاثة أشخاص ( إِلَّا هُوَ ) سبحانه ( رابِعُهُمْ ) يسمع ما يقولون. ( وَلا ) نجوى ( خَمْسَةٍ ) أشخاص ( إِلَّا هُوَ سادِسُهُمْ ) يسمع كلامهم ( وَلا أَدْنى مِنْ ذلِكَ ) بأن يكون المتناجين اثنين ( وَلا أَكْثَرَ ) بأن يكونوا أكثر من خمسة ( إِلَّا هُوَ ) سبحانه ( مَعَهُمْ ) بالعلم والاطلاع ( أَيْنَ ما كانُوا ) من بقاع الأرض ، وغيرها ( ثُمَّ يُنَبِّئُهُمْ ) أي يخبرهم ( بِما عَمِلُوا ) في الدنيا ( يَوْمَ الْقِيامَةِ ) ليجازيهم عليه فإن إِنَّ اللهَ بِكُلِّ شَيْءٍ عَلِيمٌ (7) أَ لَمْ تَرَ إِلَى الَّذِينَ نُهُوا عَنِ النَّجْوى ثُمَّ يَعُودُونَ لِما نُهُوا عَنْهُ وَيَتَناجَوْنَ بِالْإِثْمِ وَالْعُدْوانِ وَمَعْصِيَةِ الرَّسُولِ وَإِذا جاؤُكَ حَيَّوْكَ بِما لَمْ يُحَيِّكَ بِهِ اللهُ الثواب والعقاب بعد الإخبار تكريما للمثاب ، وإهانة للمعاقب ، ( إِنَّ اللهَ بِكُلِّ شَيْءٍ عَلِيمٌ ) يعلم الأشياء كلها فلا يخفى عليه شيء.` },
            { text: "أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا فَبِئْسَ ٱلْمَصِيرُ", tafsir: `يا رسول الله ( إِلَى الَّذِينَ نُهُوا عَنِ النَّجْوى ) قال ابن عباس : إنها نزلت في اليهود والمنافقين كانوا يتناجون فيما بينهم وينظرون إلى المؤمنين ويتغامزون بأعينهم فإذا رأى المؤمنون نجواهم قالوا : ما نراهم إلا وقد بلغهم عن أقربائنا وإخواننا الذين خرجوا في السرايا قتل أو مصيبة أو هزيمة ، فكان ذلك يحزنهم فشكوا إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم فنهى الرسول عن النجوى فلم ينتهوا عن ذلك ، فأنزل سبحانه هذه الآية (1) ( ثُمَّ يَعُودُونَ لِما نُهُوا عَنْهُ ) غير مبالين بالنهي. ( وَيَتَناجَوْنَ ) فيما بينهم ( بِالْإِثْمِ ) فيكنّ بعضهم لبعض آثامه ( وَالْعُدْوانِ ) أي التعدي على الناس والتعدي عن الحق ( وَمَعْصِيَةِ الرَّسُولِ ) بأن كان بعضهم يوصي بعضا بعصيان الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَإِذا جاؤُكَ ) هؤلاء المتناجون بالباطل ( حَيَّوْكَ ) يا رسول الله ( بِما لَمْ يُحَيِّكَ بِهِ اللهُ ) أي تحية ظاهرها مليح وباطنها قبيح ، فقد كان اليهود يقولون للرسول عوض التحية « السام عليك » والسام هو الموت ، يخفون ذلك موهمين أنهم قالوا « السّلام عليك » وقد كان فريق آخر يقول في تحيته « أنعم صباحا ، وأنعم مساء » وهي تحية أهل الجاهلية ، ( 1) مجمع البيان : ج 9 ص 413. وَيَقُولُونَ فِي أَنْفُسِهِمْ لَوْ لا يُعَذِّبُنَا اللهُ بِما نَقُولُ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَها فَبِئْسَ الْمَصِيرُ (8) يا أَيُّهَا الَّذِينَ آمَنُوا إِذا تَناجَيْتُمْ فَلا تَتَناجَوْا بِالْإِثْمِ وَالْعُدْوانِ وَمَعْصِيَةِ الرَّسُولِ وَتَناجَوْا بِالْبِرِّ وَالتَّقْوى وَاتَّقُوا اللهَ الَّذِي إِلَيْهِ تُحْشَرُونَ (9) فنهاهم الرسول صلى‌الله‌عليه‌وآله‌وسلم عن ذلك وقال « قد أبدلنا الله بخير من ذلك تحية أهل الجنة السّلام عليكم » والاستفهام في قوله « ألم تر » للإنكار ، أي لماذا يفعل هؤلاء هكذا ( وَيَقُولُونَ ) هؤلاء اليهود والمنافقون ( فِي أَنْفُسِهِمْ ) أي بعضهم لبعض أو خلجانا في صدورهم ( لَوْ لا يُعَذِّبُنَا اللهُ بِما نَقُولُ ) أي لو كان محمد صلى‌الله‌عليه‌وآله‌وسلم نبيا حقا ، فهلا ينزل الله علينا العذاب ؟ أليس ذلك دليل على أنه ليس بنبي ؟ ويأتي الجواب لاستفهامهم التعنتي هذا ( حَسْبُهُمْ ) أي كافيهم عقوبة ( جَهَنَّمُ ) التي ( يَصْلَوْنَها ) أي يدخلونها يوم القيامة ( فَبِئْسَ الْمَصِيرُ ) أي المرجع والمحل لسكناهم ، أما عدم تعذيب الله فلأنه لا يعذب الله في الدنيا كل عاص ، وإلا ما ترك على ظهرها من دابة.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَٰجَيْتُمْ فَلَا تَتَنَٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ", tafsir: `بعضكم مع بعض ( فَلا تَتَناجَوْا بِالْإِثْمِ وَالْعُدْوانِ وَمَعْصِيَةِ الرَّسُولِ ) أي لا تفعلوا كفعل المنافقين واليهود ـ كما سبق ـ ( وَتَناجَوْا بِالْبِرِّ ) أي بأفعال الخير ، كأن يناجي أحدهم الآخر بأن ينفق في سبيل الله ( وَالتَّقْوى ) كأن يناجيه في ترك معصية أو فعل طاعة مما يتقي به عن عذاب الله ( وَاتَّقُوا اللهَ ) أي خافوا عقابه ( الَّذِي إِلَيْهِ تُحْشَرُونَ ) أي إلى حسابه وجزائه تنتقلون بعد المبعث والحياة الآخرة. إِنَّمَا النَّجْوى مِنَ الشَّيْطانِ لِيَحْزُنَ الَّذِينَ آمَنُوا وَلَيْسَ بِضارِّهِمْ شَيْئاً إِلاَّ بِإِذْنِ اللهِ وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ (10) يا أَيُّهَا الَّذِينَ آمَنُوا إِذا قِيلَ لَكُمْ تَفَسَّحُوا فِي الْمَجالِسِ` },
            { text: "إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ", tafsir: `الذي يتعاطاه الكفار والمنافقون ( مِنَ ) أعمال ( الشَّيْطانِ ) وإيحاءاته ، وإنما يوحي إلى أوليائه بذلك ( لِيَحْزُنَ الَّذِينَ آمَنُوا ) بأن يظنوا أن المتناجين ينقلون فيما بينهم خبرا محزنا ، أو يدبرون مؤامرة ، أو يستهزئون بالمؤمنين أو ما أشبه ( وَلَيْسَ ) نجواهم ( بِضارِّهِمْ ) أي لا يضر المؤمنين ( شَيْئاً ) فان النجوى ليس إلا عملا باطلا لغوا ( إِلَّا بِإِذْنِ اللهِ ) فإن الله مطّلع على نجواهم ، فإن اقتضت حكمته أن لا يحول بينهم وبين ما دبروا من المكر ، كان يضرهم ، أما إذا لم يرد الله سبحانه ضرر المؤمنين حال بينهم وبين ما يدبرون بالنجوى ، فاللازم أن يتوجه المؤمنون إلى الله بالضراعة ليدفع كيد الكفار والمنافقين عنهم ( وَعَلَى اللهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ ) بأن يكلوا أمرهم إليه سبحانه ، فإنه نعم الحفيظ. [12] وإذا فرغ السياق من بيان أدب من آداب المجالس ، بذكر بعض الأمور المرتبطة بالنجوى ، بمناسبة تحدث المرأة مع الرسول حول الظهار ، الذي كان حوارا في المجلس ومما يحدث في المجالس ، جاء السياق ليبين أدبا آخر من آداب المجالس فقال سبحانه : ( يا أَيُّهَا الَّذِينَ آمَنُوا إِذا قِيلَ لَكُمْ ) والقائل أيّ شخص كان ( تَفَسَّحُوا ) أي اتسعوا ( فِي الْمَجالِسِ ) بأن تجمعوا أنفسكم في فَافْسَحُوا يَفْسَحِ اللهُ لَكُمْ وَإِذا قِيلَ انْشُزُوا فَانْشُزُوا يَرْفَعِ اللهُ الَّذِينَ آمَنُوا مِنْكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجاتٍ وَالله ُ بِما تَعْمَلُونَ الجلوس ، حتى يتسع المكان لشخص آخر ( فَافْسَحُوا ) ووسعوا المكان ( يَفْسَحِ اللهُ لَكُمْ ) أي يوسع الله لكم الأمر ، أو يوسع الله لكم منازلكم في الجنة ، فقد ورد أن المسلمين كانوا يتنافسون على المجلس في محضر رسول الله صلى‌الله‌عليه‌وآله‌وسلم فإذا رأوا من جاءهم مقبلا ضنوا بمجلسهم عند رسول الله صلى‌الله‌عليه‌وآله‌وسلم أن يفسح بعضهم لبعض ( وَإِذا قِيلَ ) لكم ( انْشُزُوا ) أي قوموا عن أماكنكم ليجلس غيركم ، من « نشز » بمعنى ارتفع ( فَانْشُزُوا ) أي فقوموا ، قالوا وكان سبب نزول هذا أن الرسول صلى‌الله‌عليه‌وآله‌وسلم كان يكرم أهل بدر ، وذات يوم والناس آخذون مكانهم حول الرسول صلى‌الله‌عليه‌وآله‌وسلم ورد بعض أهل بدر فلم يفسح الجالسون لهم مكان ، فقال الرسول صلى‌الله‌عليه‌وآله‌وسلم لبعض الجالسين قوموا حتى يجلس أهل بدر ، فقاموا لكن الكراهية بدت في وجوههم واستغل المنافقون ذلك فقالوا لمن أقيم : أ هكذا عدل الرسول صلى‌الله‌عليه‌وآله‌وسلم حيث يقيمكم ليجلس غيركم ذلك المكان ؟ فنزل ذلك (1) . ( يَرْفَعِ اللهُ الَّذِينَ آمَنُوا مِنْكُمْ ) إيمانا صحيحا من الأعماق ( وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجاتٍ ) في الدنيا وفي الجنة ، فهذا الامتثال للرسول بالقيام حسب أمره موجب لرفعتكم في الدنيا والآخرة ، وفيه تناسب حسن بين قيامهم من المجالس ، ورفعة درجتهم ، والدرجات إنما هي بحسب مراتب الإيمان والعلم ، ( وَاللهُ بِما تَعْمَلُونَ ( 1) مجمع البيان : ج 9 ص 417. خَبِيرٌ (11) يا أَيُّهَا الَّذِينَ آمَنُوا إِذا ناجَيْتُمُ الرَّسُولَ فَقَدِّمُوا بَيْنَ يَدَيْ نَجْواكُمْ صَدَقَةً خَبِيرٌ ) أي عالم مطلع فيجازيكم حسب أعمالكم. [13] وبعد ذلك جاء السياق لبيان أدب آخر من آداب مجلس الرسول صلى‌الله‌عليه‌وآله‌وسلم وفيه تلميح إلى أن ذلك أدب عام ، فقد سبق منا أن أمثال هذه الآيات إنما أتي بها للإلماع إلى الخطوط العامة في الأحكام والآداب ، وإن لم يكن لها مصاديق خارجية بعد موت الرسول صلى‌الله‌عليه‌وآله‌وسلم ومن يرتبط بتلك الآيات مباشرة ( يا أَيُّهَا الَّذِينَ آمَنُوا إِذا ناجَيْتُمُ الرَّسُولَ ) أي أردتم الإسرار في أذنه ، فإن الفعل يأتي بمعنى الإرادة كهذه الآية ، كما أن الإرادة تأتي بمعنى الفعل كقوله ( إِنَّما يُرِيدُ اللهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيراً ) (1) و ( يُرِيدُ اللهُ بِكُمُ الْيُسْرَ ) (2) وما أشبه ذلك ( فَقَدِّمُوا بَيْنَ يَدَيْ نَجْواكُمْ ) أي أمام النجوى ( صَدَقَةً ) فقد كان الأشراف ـ في زعمهم ـ يأتون إلى الرسول يناجونه بالترهات ، إظهارا لفضلهم ـ كما جرت عادة أمثالهم إلى هذا اليوم ـ يريدون إراءة الناس ان الرسول صلى‌الله‌عليه‌وآله‌وسلم يسمع لقولهم ويرعاهم فجاءت هذه الآية رادعة لهم ، وفيه الأمر بتعظيم الرسول صلى‌الله‌عليه‌وآله‌وسلم وإنفاع الفقراء ، والنهي عن الإفراط في السؤال ، والميز بين المخلص والمنافق ، ومحب الآخرة ومحب الدنيا ، فلما سمعوا بهذه الآية انتهوا ، باستثناء الإمام أمير المؤمنين عليه‌السلام ، فصرف دينارا عشرة دراهم ، وأخذ يعطي درهما للفقير ويناجي ، ودرهما آخر ويناجي ، وهكذا حتى أنفق العشرة (3) . ( 1) الأحزاب : 34. ( 2) البقرة : 186. ( 3) راجع بحار الأنوار : ج 35 ص 378. ذلِكَ خَيْرٌ لَكُمْ وَأَطْهَرُ فَإِنْ لَمْ تَجِدُوا فَإِنَّ اللهَ غَفُورٌ رَحِيمٌ (12) أَ أَشْفَقْتُمْ أَنْ تُقَدِّمُوا بَيْنَ يَدَيْ نَجْواكُمْ صَدَقاتٍ فَإِذْ لَمْ تَفْعَلُوا وَتابَ اللهُ عَلَيْكُمْ فَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ ( ذلِكَ ) أي إعطاء الصدقة قبل النجوى ( خَيْرٌ لَكُمْ ) لأن فيه تحصيل الثواب ، وأداء الواجب ، والدلالة على السخاء ، وتعظيم الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَأَطْهَرُ ) لأن التصدق يطهّر النفس من الرذيلة والشح ( فَإِنْ لَمْ تَجِدُوا ) ما تتصدقون به قبل النجوى ( فَإِنَّ اللهَ غَفُورٌ ) يستر عليكم ترك ذلك ( رَحِيمٌ ) بكم فلا يكلّفكم التصدق بل يجوّز لكم النجوى بدون الصدقة ، وستره سبحانه إنما هو بعدم إيجابه التصدق ، حتى يأثم المناجي بدون التصدق ، فلا يقال : لا مجال لقوله « غفور » في المقام ، إذ الغفران عن الذنب ولا ذنب في المقام ؟ ولما نزلت هذه الآية لم يتقدم أحد من النجوى إلا الإمام كما سبق ، فأنزل الله سبحانه رفع الحكم بقوله :` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةً ذَٰلِكَ خَيْرٌ لَّكُمْ وَأَطْهَرُ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَٰتٍ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ", tafsir: `أي هل خفتم من الفقر أيها المسلمون ( أَنْ تُقَدِّمُوا بَيْنَ يَدَيْ نَجْواكُمْ ) للرسول صلى‌الله‌عليه‌وآله‌وسلم ( صَدَقاتٍ ) ؟ وكان الإتيان بالجمع باعتبار كون « النجوى » جنسا شاملا لأفراد متعددة ، فلكل فرد صدقة ، وهذا استفهام توبيخي ، بأنه كيف تركتم هذه الفضيلة للخوف من الفقر مع العلم أن الصدقة لم تكن محددة ، فكان يكفي القليل منها ( فَإِذْ لَمْ تَفْعَلُوا ) أي لم تتصدقوا ، وتركتم النجوى بخلاف من الإنفاق ( وَتابَ اللهُ عَلَيْكُمْ ) بأن عفى تقصيركم في هذه الفضيلة فاعملوا بسائر أحكام الإسلام فقد رفع عنكم هذا الحكم فلا مانع بعد ذلك من النجوى بدون الصدقة ( فَأَقِيمُوا الصَّلاةَ ) بالإتيان بها بحدودها ( وَآتُوا الزَّكاةَ ) أي وَأَطِيعُوا اللهَ وَرَسُولَهُ وَاللهُ خَبِيرٌ بِما تَعْمَلُونَ (13) أَ لَمْ تَرَ إِلَى الَّذِينَ تَوَلَّوْا قَوْماً غَضِبَ اللهُ عَلَيْهِمْ ما هُمْ مِنْكُمْ وَلا مِنْهُمْ أعطوها ( وَأَطِيعُوا اللهَ وَرَسُولَهُ ) في سائر أوامرهما ( وَاللهُ خَبِيرٌ بِما تَعْمَلُونَ ) فأنتم بعينه وتحت اطلاعه ، فلا تعملوا ما يخالف أوامره حتى تستحقوا العقاب. قال الإمام أمير المؤمنين عليه‌السلام : إن في كتاب الله لآية ما عمل بها أحد قبلي ولا يعمل بها أحد بعدي ( يا أَيُّهَا الَّذِينَ آمَنُوا إِذا ناجَيْتُمُ الرَّسُولَ ) كان لي دينار فبعته بعشرة دراهم فكلما أردت أن أناجي رسول الله صلى‌الله‌عليه‌وآله‌وسلم قدم درهما (1) ، أقول : قوله « ءأشفقتم » لا ينافي عدم وجود النسخ في القرآن ، لأن الظاهر كون الأمر بتقديم الصدقة في الآية السابقة ، كان امتحانيا من قبيل رؤيا إبراهيم عليه‌السلام ، ولإظهار فضيلة الإمام عليه‌السلام ـ كذا يقول المنكرون للنسخ ـ . [15] وبمناسبة ما تقدم من النجوى ، أتى السياق ليبين احترام السر وأنه لا يجوز إظهاره للأعداء ( أَ لَمْ تَرَ ) يا رسول الله ، أو أيها الرائي ( إِلَى الَّذِينَ تَوَلَّوْا ) بالصداقة والوداد ( قَوْماً ) من الكفار ( غَضِبَ اللهُ عَلَيْهِمْ ) قال في المجمع : والمراد به قوم من المنافقين كانوا يوالون اليهود ويفشون إليهم أسرار المؤمنين (2) ( ما هُمْ ) أي ليس هؤلاء المنافقين ( مِنْكُمْ ) أيها المؤمنون ( وَلا مِنْهُمْ ) أي من الكفار ، بل ( 1) بحار الأنوار : ج 17 ص 29. ( 2) مجمع البيان : ج 9 ص 419. وَيَحْلِفُونَ عَلَى الْكَذِبِ وَهُمْ يَعْلَمُونَ (14) أَعَدَّ اللهُ لَهُمْ عَذاباً شَدِيداً إِنَّهُمْ ساءَ ما كانُوا يَعْمَلُونَ (15) اتَّخَذُوا أَيْمانَهُمْ جُنَّةً فَصَدُّوا عَنْ سَبِيلِ اللهِ فَلَهُمْ عَذابٌ مُهِينٌ (16) لَنْ تُغْنِيَ عَنْهُمْ أَمْوالُهُمْ وَلا أَوْلادُهُمْ مِنَ اللهِ شَيْئاً أُولئِكَ أَصْحابُ النَّارِ هُمْ مذبذبين بين ذلك لا إلى هؤلاء ولا إلى هؤلاء ( وَ ) إذا قيل لهم لم تنافقوا ( يَحْلِفُونَ ) لتبرئة ساحة أنفسهم ( عَلَى الْكَذِبِ ) بأنا لا نساير الكفار ولا ننافق ( وَهُمْ يَعْلَمُونَ ) أنهم كاذبون في قولهم وأنهم منافقون.` },
            { text: "أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ", tafsir: `` },
            { text: "أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `أي هيأ الله ( لَهُمْ ) أي لهؤلاء المنافقين ( عَذاباً شَدِيداً ) في الدنيا بالخزي والفضيحة وفي الآخرة بالنار والنكال ( إِنَّهُمْ ساءَ ما كانُوا يَعْمَلُونَ ) من النفاق وموالاة أعداء الله تعالى.` },
            { text: "ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ", tafsir: `هؤلاء المنافقون الذين حلفوا لكم ( أَيْمانَهُمْ ) جمع يمين وهي الحلف ( جُنَّةً ) أي سترة وترسا يدفعون بها عن نفوسهم التهمة والظنة إذا ظهر منهم النفاق ( فَصَدُّوا ) أنفسهم ، والناس الضعاف الإيمان ( عَنْ سَبِيلِ اللهِ ) أي الطريق الموصل إلى مرضاته ( فَلَهُمْ عَذابٌ مُهِينٌ ) يذلهم ويهينهم جزاء على نفاقهم.` },
            { text: "لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `أي لا تفيد هؤلاء المنافقين في دفع عذاب الله عنهم ( أَمْوالُهُمْ ) التي جمعوها ( وَلا أَوْلادُهُمْ ) الذين خلفوهم ( مِنَ اللهِ ) أي من بأس الله ونكاله ( شَيْئاً ) فلا تدفعان عنهم ولو بعض العذاب ( أُولئِكَ ) المنافقون ( أَصْحابُ النَّارِ ) الملازمون لها ، كالصاحب الذي يلازم صاحبه ( هُمْ فِيها خالِدُونَ (17) يَوْمَ يَبْعَثُهُمُ اللهُ جَمِيعاً فَيَحْلِفُونَ لَهُ كَما يَحْلِفُونَ لَكُمْ وَيَحْسَبُونَ أَنَّهُمْ عَلى شَيْءٍ أَلا إِنَّهُمْ هُمُ الْكاذِبُونَ (18) اسْتَحْوَذَ عَلَيْهِمُ الشَّيْطانُ فَأَنْساهُمْ ذِكْرَ اللهِ فِيها خالِدُونَ ) إلى الأبد ، و قد روي أن الآيات نزلت في منافق كان يجالس اليهود ويأخذ عنهم نفاقا ، فلما اطلع الرسول صلى‌الله‌عليه‌وآله‌وسلم على أمره نهاه ، فقال للرسول صلى‌الله‌عليه‌وآله‌وسلم أنه يأخذ عنهم صفته صلى‌الله‌عليه‌وآله‌وسلم الموجودة في التوراة ، وحلف على ذلك كذبا وتغطية لأمره ، لكن الوحي فضحه وفشى أمره. [19] هم أصحاب النار في ( يَوْمَ يَبْعَثُهُمُ اللهُ ) أي هؤلاء المنافقين يحييهم بعد الممات للحساب والجزاء ( جَمِيعاً ) بغير أن يترك منهم أحدا وهذا التأكيد لئلا يحتمل أحد أنه يترك ، كما هو الشأن في الدنيا إذ يترك بعض القوم ـ جهلا أو نسيانا ـ في الدعوات العامة وما أشبهها ( فَيَحْلِفُونَ لَهُ ) أي الله سبحانه ، بأنهم كانوا مؤمنين في دار الدنيا ( كَما يَحْلِفُونَ لَكُمْ ) في الحال ظانين أن الله لا يعلم أمرهم ، وينطلي عليه كذبهم بمجرد الحلف ( وَيَحْسَبُونَ ) أي يظنون ( أَنَّهُمْ عَلى شَيْءٍ ) بأن أيمانهم الكاذبة تروج هنا ، كما كانت تروج في الدنيا لدى المؤمنين ( أَلا إِنَّهُمْ هُمُ الْكاذِبُونَ ) في كلامهم ويمينهم فلا تروج الأيمان المكذوبة هناك ، بل يعرفون بالكذب والدجل.` },
            { text: "يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ أَلَآ إِنَّهُمْ هُمُ ٱلْكَٰذِبُونَ", tafsir: `` },
            { text: "ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ أُو۟لَٰٓئِكَ حِزْبُ ٱلشَّيْطَٰنِ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَٰنِ هُمُ ٱلْخَٰسِرُونَ", tafsir: `على هؤلاء المنافقين ( الشَّيْطانُ ) أي استولى عليهم ، والاستحواذ هو الاستيلاء ، من « حاذ » بمعنى « حاز » كالذي يحوز شيئا لنفسه ويختاره لشخصه ( فَأَنْساهُمْ ذِكْرَ اللهِ ) حتى أنهم أُولئِكَ حِزْبُ الشَّيْطانِ أَلا إِنَّ حِزْبَ الشَّيْطانِ هُمُ الْخاسِرُونَ (19) إِنَّ الَّذِينَ يُحَادُّونَ اللهَ وَرَسُولَهُ أُولئِكَ فِي الْأَذَلِّينَ (20) كَتَبَ اللهُ لَأَغْلِبَنَّ أَنَا وَرُسُلِي إِنَّ اللهَ قَوِيٌّ عَزِيزٌ (21) لا يذكرونه سبحانه حتى يخافوا منه ، فينقلعوا عن النفاق والعصيان ( أُولئِكَ ) المنافقون ( حِزْبُ الشَّيْطانِ ) جماعته وأتباعه ( أَلا إِنَّ حِزْبَ الشَّيْطانِ هُمُ الْخاسِرُونَ ) الذين خسروا دنياهم وآخرتهم ، فإن الدنيا تزول ، ولهم في الآخرة النار. [21] ثم انتقل السياق من المنافقين ، إلى كل مخالف لله ورسوله ( إِنَّ الَّذِينَ يُحَادُّونَ اللهَ ) أي يتجاوزون حدوده بالمخالفة ( وَرَسُولَهُ ) فيما جاء من الأحكام ( أُولئِكَ فِي الْأَذَلِّينَ ) فلا أحد أذل منهم في الدنيا والآخرة ، وكأن الأذلون فرقة سابقة على الإسلام ، فهؤلاء المحادون في زمن الرسول صلى‌الله‌عليه‌وآله‌وسلم أو بعده داخلون في أولئك ، وكأن هؤلاء أكثر ذلّا وهوانا من العصاة من المؤمنين ، وبهذا الاعتبار عبر عنهم بالأذل ، أو أنهم أذل من الكافر غير المحادد. [22] وهل يظن هؤلاء المحادون أن عملهم يثمر لهم نجاحا ، أو للإسلام هبوطا ؟ كلا ! فقد ( كَتَبَ اللهُ ) في اللوح المحفوظ وقرر ( لَأَغْلِبَنَّ أَنَا وَرُسُلِي ) على كل محاد ومخالف ، وقد جرب العالم صدق هذه المقالة ، فالآخذون بزمام العالم حتى في هذا اليوم المظلم هم الرسل كموسى عليه‌السلام وعيسى عليه‌السلام ومحمد صلى‌الله‌عليه‌وآله‌وسلم ، ولهم من الأتباع أكثر من نصف أهل العالم ، ومناهجهم سارية ـ قليلا أو كثيرا ـ في كل العالم ( إِنَّ اللهَ قَوِيٌ ) على نصر أنبيائه ( عَزِيزٌ ) غالب في سلطانه ، فلا يتمكن أحد على أن يغلبه أو يغلب رسله ، و قد روي أن المسلمين لما لا تَجِدُ قَوْماً يُؤْمِنُونَ بِاللهِ وَالْيَوْمِ الْآخِرِ يُوادُّونَ مَنْ حَادَّ اللهَ وَرَسُولَهُ وَلَوْ كانُوا آباءَهُمْ أَوْ أَبْناءَهُمْ أَوْ إِخْوانَهُمْ أَوْ عَشِيرَتَهُمْ أُولئِكَ كَتَبَ فِي قُلُوبِهِمُ رأوا ما يفتح الله عليهم من القرى قالوا : ليفتحن الله علينا الروم وفارس فقال المنافقون : أتظنون أن فارسا والروم كبعض القرى التي غلبتم عليها ؟ فأنزل الله هذه الآية (1) . [23] ثم جاء السياق ليبين وظيفة المسلم أمام الكافر ، وأنه يلزم عليه أن لا يواد الكافر مهما كان ، خلافا لأولئك المنافقين الذين كانوا يوادون الكافرين ( لا تَجِدُ ) يا رسول الله ، أو أيها المسلم ( قَوْماً يُؤْمِنُونَ بِاللهِ وَالْيَوْمِ الْآخِرِ ) إيمانا صحيحا ( يُوادُّونَ ) الموادة المحابة ، من باب « المفاعلة » ( مَنْ حَادَّ اللهَ ) أي خالف الله ( وَرَسُولَهُ ) بترك أوامرهما والكفر بهما ، والمعنى : إنه لا تجتمع موالاة الكفار مع الإيمان ، فمن والاهم فليس بمؤمن ، وان أظهر الإيمان ( وَلَوْ كانُوا ) أي كان الذين يحادون الله ورسوله ( آباءَهُمْ ) ، أي آباء المؤمنين ( أَوْ أَبْناءَهُمْ أَوْ إِخْوانَهُمْ أَوْ عَشِيرَتَهُمْ ) بأن قربت قرابتهم ، فإن الكفر يقطع قرابة المؤمن بالكفار وإن بقي رجحان بعض أقسام الصلة ، إذا كان الكافر أبا أو أما أو ما أشبه ، كما قال سبحانه ، ( وَإِنْ جاهَداكَ عَلى أَنْ تُشْرِكَ بِي ما لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُما وَصاحِبْهُما فِي الدُّنْيا مَعْرُوفاً ) (2) ( أُولئِكَ ) الذين لا يوادون الكفار ( كَتَبَ ) الله أي أثبت ( فِي قُلُوبِهِمُ ( 1) مجمع البيان : ج 9 ص 421. ( 2) لقمان : 16. الْإِيمانَ وَأَيَّدَهُمْ بِرُوحٍ مِنْهُ وَيُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ خالِدِينَ فِيها رَضِيَ اللهُ عَنْهُمْ وَرَضُوا عَنْهُ أُولئِكَ حِزْبُ اللهِ أَلا إِنَّ حِزْبَ اللهِ هُمُ الْمُفْلِحُونَ (22) الْإِيمانَ ) بالألطاف الخفية بهم حيث رآهم في طريق الحق. ( وَأَيَّدَهُمْ ) أي قوّاهم الله سبحانه ( بِرُوحٍ مِنْهُ ) أي بروح من عنده تعالى ، فإن المؤمن الصامد توجد فيه روح قوية توجب التزام أحكام الله سبحانه ، حتى أن أقوى أسباب الكفر لا تتمكن من زحزحته ( وَيُدْخِلُهُمْ ) الله في الآخرة ( جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا ) أي من تحت أشجارها وقصورها ( الْأَنْهارُ ) من عسل وخمر ولبن وماء حال كونهم ( خالِدِينَ ) أي دائمين باقين ( فِيها ) أي في تلك الجنات ( رَضِيَ اللهُ عَنْهُمْ ) حيث علم فيهم الإيمان الراسخ والعمل الصالح ( وَرَضُوا عَنْهُ ) بما منحهم من الفضل والإيمان في الدنيا والجنان في الآخرة ( أُولئِكَ ) المتصفون بتلك الصفات ( حِزْبُ اللهِ ) جماعته وأتباعه ـ في مقابل حزب الشيطان ـ ( أَلا ) فلينتبه السامع ( إِنَّ حِزْبَ اللهِ هُمُ الْمُفْلِحُونَ ) الذين فازوا وظفروا بخير الدنيا وسعادة الآخرة ، قالوا نزلت هذه الآية في « حاطب » حيث كاتب أهل مكة يخبرهم بإقبال الرسول صلى‌الله‌عليه‌وآله‌وسلم نحوهم للفتح ، بعد ما كان الرسول صلى‌الله‌عليه‌وآله‌وسلم نهى أصحابه أن يفشوا الخبر ، فلما عوتب في ذلك ، اعتذر بأن أهله في مكة فأراد أن يكون له يد على أهلها ، حتى لو كانت الدائرة على المسلمين راعى أهل مكة يده عندهم ، فلا يؤذوا زوجته وأهله. (59)` },
            { text: "إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ فِى ٱلْأَذَلِّينَ", tafsir: `` },
            { text: "كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ", tafsir: `` },
            { text: "لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ أُو۟لَٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَٰنَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ وَيُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ أُو۟لَٰٓئِكَ حِزْبُ ٱللَّهِ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ", tafsir: `` }
        ]
    },
    59: { // سورة الحشر
        name: "الحشر",
        basmalaTafsir: ``,
        verses: [
            { text: "سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `أي نزهه سبحانه عن النقائص ، ويجوز في سبح تعديه بلا واسطة نحو « سبحه » وتعديه مع الواسطة نحو « سبح له » باعتبار أن التسبيح له لا لغيره ( ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) والمراد الظرف والمظروف ، والمراد بالتسبيح إما التكويني بأن كل شيء يدل على وجود الإله وسائر صفاته ، دلالة الأثر على المؤثر ، أو التسبيح بألسنتها التي لا نفقهها ، كما قال : كل شيء في الكون يشعر لكن منع الناس عن شعور المشاعر ( وَهُوَ الْعَزِيزُ ) الغالب في سلطانه ( الْحَكِيمُ ) يفعل الأشياء حسب الحكمة والصلاح.` },
            { text: "هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ مِن دِيَٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَٰٓأُو۟لِى ٱلْأَبْصَٰرِ", tafsir: `الله سبحانه ( الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتابِ ) كل أهل الكتاب كفار ، لكن منهم من آمن بالرسول ، فخرج عن الكفر ، ومنهم من لم يؤمن فيقال له « كفر » إما باعتبار استمراره في الكفر من قبيل « اهدنا » ، أو باعتبار أنه كان إلى قبل بعثة الرسول مؤمنا ـ إذ كان تكليفه هو دينه ـ فإذ جاء الرسول ولم يؤمن صار كافرا والمراد بهم هنا يهود « بني النضير » ( مِنْ دِيارِهِمْ ) بأن سلط المؤمنين عليهم وأيدهم ، حتى يتمكنوا من إخراجهم ( لِأَوَّلِ الْحَشْرِ ) الحشر هو الجمع من مكان ما ظَنَنْتُمْ أَنْ يَخْرُجُوا وَظَنُّوا أَنَّهُمْ مانِعَتُهُمْ حُصُونُهُمْ مِنَ اللهِ فَأَتاهُمُ اللهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا وَقَذَفَ فِي قُلُوبِهِمُ الرُّعْبَ يُخْرِبُونَ بُيُوتَهُمْ بِأَيْدِيهِمْ وَأَيْد ِي الْمُؤْمِنِينَ فَاعْتَبِرُوا إلى مكان آخر ـ ولعل المراد لأول مرة في إخراج اليهود من المدينة بصورة جماعية ـ ثم بعد ذلك أخرج غيرهم ، حتى لا يبقى في جزيرة العرب اليهود إطلاقا ، فإنهم أهل مؤامرة ودسائس ، فأراد الرسول صلى‌الله‌عليه‌وآله‌وسلم إخلاء البلاد منهم ومن كيدهم ، لئلا يدبروا المؤامرات على الدين الجديد. ( ما ظَنَنْتُمْ ) أيها المسلمون ( أَنْ يَخْرُجُوا ) أي اليهود بهذه السرعة لما كنتم تعلمون من شدة بطشهم وشوكتهم ( وَظَنُّوا ) أي اليهود ( أَنَّهُمْ مانِعَتُهُمْ ) أي تمنعهم من المسلمين ( حُصُونُهُمْ ) جمع حصن وهي القلعة التي يتحصن فيها الإنسان خوفا من العدو المهاجم ( مِنْ ) بأس ( اللهِ ) بأنه سبحانه إذا أراد بهم شيئا وقفت حصونهم أمام إرادته ( فَأَتاهُمُ اللهُ ) أي جاءهم أمر الله بالخراب لقلاعهم ، والتشريد لهم ( مِنْ حَيْثُ لَمْ يَحْتَسِبُوا ) أي لم يظنوا أنهم يمكن أن يؤتوا من تلك الجهة بأن ألقى الرعب في قلوبهم وأرخى قواهم ، وكسر شوكتهم ومنعتهم ( وَقَذَفَ ) أي ألقى الله سبحانه ( فِي قُلُوبِهِمُ الرُّعْبَ ) أي الخوف ، فإنهم لما رأوا كثرة شوكة المسلمين انهارت قواهم ، وأول الهزيمة هو : الرعب وخور القوى وانهيار الأعصاب ( يُخْرِبُونَ ) أي أولئك اليهود ( بُيُوتَهُمْ بِأَيْدِيهِمْ ) فقد كانوا يهدمون بيوتهم لئلا ينتفع بها المؤمنون ( وَأَيْدِي الْمُؤْمِنِينَ ) فقد كان المؤمنون يخربون بيوتهم ليصلوا إليهم ويهزموهم ( فَاعْتَبِرُوا ) واتعظوا يا أُولِي الْأَبْصارِ (2) ( يا أُولِي الْأَبْصارِ ) أي أصحاب العقول ، بأن الله سبحانه إذا حاده جماعة كيف يهزمهم ويغلب عليهم ، حتى أنهم بأنفسهم يهدمون بيوتهم التي هي أعز ما يكون لديهم ، والمراد بالاعتبار النظر في الأمور ليرى الإنسان بها أمورا أخر لها ارتباط وثيق بها. وقد ذكر المفسرون أن هذه الآيات نزلت في « بني النضير » وتفصيل قصتهم على ما في « قادة الإسلام » (1) : قتل أحد أصحاب الرسول نفرين ممن كانا في عهد الإسلام ، وكان قتله لهما اشتباها ، فأراد النبي صلى‌الله‌عليه‌وآله‌وسلم أن يستقرض ديتهما من بني النضير ، وهم يهود قرب المدينة ، عددهم زهاء الألف ، فأظهروا قبول إقراض الدية ، ودعوا الرسول صلى‌الله‌عليه‌وآله‌وسلم إلى داخل الحصن. لكن الرسول صلى‌الله‌عليه‌وآله‌وسلم أبى واتكأ على جدار الحصن ، وهناك نزل عليه جبرئيل وأخبره بأنهم عازمون على الغدر به ، وتبين الرسول صلى‌الله‌عليه‌وآله‌وسلم ذلك من حركاتهم ، حيث إنهم تآمروا بينهم أن يذهب أحدهم على سطح الجدار الذي كان الرسول صلى‌الله‌عليه‌وآله‌وسلم متكئا عليه فيلقي على رأس الرسول صلى‌الله‌عليه‌وآله‌وسلم حجرا حتى يقضي على حياته الشريفة. قفل الرسول راجعا إلى المدينة ، قبل أن يأخذ القرض ، وأرسل رسولا إلى بني النضير إذ نقضتم ميثاقكم وأردتم الغدر ، فاخرجوا من بلادي ولقد أمهلتكم عشرة أيام ، وحينذاك لم يجدوا مناصا عن الخروج إلا أن بعض المنافقين ، وعدهم النصر ، ونهاهم عن الخروج ، فلم يخرجوا ، وأخبروا النبي صلى‌الله‌عليه‌وآله‌وسلم إنهم لن يخرجوا فليفعل ( 1) للمؤلف. وَلَوْ لا أَنْ كَتَبَ اللهُ عَلَيْهِمُ الْجَلاءَ لَعَذَّبَهُمْ فِي الدُّنْيا وَلَهُمْ فِي الْآخِرَةِ عَذابُ النَّارِ (3) الرسول صلى‌الله‌عليه‌وآله‌وسلم ما بدا له وعزموا على القتال ، فخرج الرسول صلى‌الله‌عليه‌وآله‌وسلم مع جمع من أصحابه ، ورايته بيد الإمام أمير المؤمنين عليه‌السلام وحاصروا حصونهم وأخذوا يحتلون بيوتهم ، فكانت اليهود تنسحب من دار إلى دار ، وكلما انسحبت هدّمت البناء الذي في معرض الاحتلال واستماتوا ، فأراد الرسول صلى‌الله‌عليه‌وآله‌وسلم قطع آمالهم عن أراضيهم ، فأمر بقطع نخيلهم. يئس اليهود عن النجدة ، وأرسلوا إلى النبي صلى‌الله‌عليه‌وآله‌وسلم رسولا يطلبون منه أن يسمح لهم بالخروج جميعا ، فأذن لهم الرسول صلى‌الله‌عليه‌وآله‌وسلم ، بشرط أن لا يحملوا أكثر مما تحمله إبلهم فقط ، لكنهم لم يقبلوا ، وبقوا مستميتين ، ولما ضيق عليهم الحصار قبلوا شرط الرسول صلى‌الله‌عليه‌وآله‌وسلم ، لكن الرسول جزاهم عن عنادهم ، فلم يسمح لهم بحمل شيء من أموالهم ، وإنما أذن لهم بالخروج بدون حمل أثقالهم ، فقبلوا الشرط وخرجوا وحدهم ، وخلوا أموالهم كلها للإسلام ، فقسم الأموال بين المهاجرين الأولين ، وأعطى منها لنفرين من الأنصار ، وبجلاء بني النضير استراح المسلمون من عدو لدود لهم ، كان يكيد لاجتثاث الإسلام من جذوره.` },
            { text: "وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابُ ٱلنَّارِ", tafsir: `أي حكم الله ( عَلَيْهِمُ ) أي على بني النضير ( الْجَلاءَ ) أي الانتقال من ديارهم ، والجلاء عن أوطانهم ( لَعَذَّبَهُمْ فِي الدُّنْيا ) بأن أمر الرسول بقتلهم وإهلاكهم كما أنه سبحانه فعل ذلك ببني قريظة ( وَلَهُمْ فِي الْآخِرَةِ عَذابُ النَّارِ ) لما تمادوا في كفرهم وعصيانهم. ذلِكَ بِأَنَّهُمْ شَاقُّوا اللهَ وَرَسُولَهُ وَمَنْ يُشَاقِّ اللهَ فَإِنَّ اللهَ شَدِيدُ الْعِقابِ (4) ما قَطَعْتُمْ مِنْ لِينَةٍ أَوْ تَرَكْتُمُوها قائِمَةً عَلى أُصُولِها فَبِإِذْنِ اللهِ وَلِيُخْزِيَ الْفاسِقِينَ (5)` },
            { text: "ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ", tafsir: `الإخراج لهم عن ديارهم ، وإعداد النار لهم في الآخرة بسبب أنهم ( شَاقُّوا اللهَ ) أي عادوه ( وَ ) حاربوا ( رَسُولَهُ وَمَنْ يُشَاقِّ اللهَ ) بالمخالفة والمحاربة ( فَإِنَّ اللهَ شَدِيدُ الْعِقابِ ) أي فليستعد للعقاب الشديد ، لأنه تعالى « أرحم الراحمين في موضع العفو والرحمة ، وأشد المعاقبين في موضع النكال والنقمة » .` },
            { text: "مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَٰسِقِينَ", tafsir: `أيها المسلمون ( مِنْ لِينَةٍ ) أي نخلة كريمة من أنواع النخيل ، وإنما سمي لينة للين ثمره ، وتقبل سعفه للتصنيع ( أَوْ تَرَكْتُمُوها قائِمَةً عَلى أُصُولِها ) أي جذوعها بأن لم تقطعوها ـ فقد قطع المسلمون بعض النخيل لبني النضير وتركوا بعضها قائمة ـ ( فَبِإِذْنِ اللهِ ) فقد تحرج المسلمون عن هذا العمل ، بأنه إن لزم القطع فكان ما أبقوا غير جائز ، وإن لزم الإبقاء كان ما قطعوا غير جائز ، ولذا جاء البيان ليبرر موقفهم ويطمئن قلوبهم ، فإن ما احتيج إلى قطعه في الحرب والتنكيل قطع ، وما لم يحتج إلى قطعه أبقي ، ( وَلِيُخْزِيَ ) أي يذل الله ( الْفاسِقِينَ ) أي أولئك اليهود بهذا القطع والإبقاء ، فما قطع أورث فيهم حسرة كيف قطع المسلمون ما غرسوه وربوه ، وما أبقي أورث فيهم حسرة كيف أبقي حتى ينتفع المسلمون به ؟ [7] ثم يأتي السياق ليبين أحكام الغنيمة التي غنموها في إجلاء بني النضير ، بأنها خاصة للرسول صلى‌الله‌عليه‌وآله‌وسلم وأقربائه لأن المسلمين لم يتعبوا لأجلها وَما أَفاءَ اللهُ عَلى رَسُولِهِ مِنْهُمْ فَما أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلا رِكابٍ وَلكِنَّ اللهَ يُسَلِّطُ رُسُلَهُ عَلى مَنْ يَشاءُ وَاللهُ عَلى كُلِّ شَيْءٍ قَدِ يرٌ (6) وذلك بخلاف الغنيمة التي تعب المسلمون في تحصيلها ، فإنها تقسم خمسة أقسام أربعة منها للمسلمين ، وواحدة منها للرسول وأقربائه ، وإنما خصص القسم الأول بالرسول وآله ، لأنهم لما منعوا من الزكاة احتاجوا إلى سد نفقاتهم وذلك إنما هو بالفيء والخمس ، ولأنه لا بد وأن يكون للرسول صلى‌الله‌عليه‌وآله‌وسلم حصة زائدة ليتمكن من إدارة شؤون المسلمين المرتبطة بأمور الدولة ـ كما تخصص لرؤساء الحكومات ـ اليوم ـ حصة معينة من الخزينة لسد نفقاتهم المرتبطة بالشؤون العامة ـ ( وَما أَفاءَ اللهُ ) الفيء هو الغنيمة ، وأصله بمعنى الرجوع ، وإنما سميت الغنيمة فيئا ، لبيان أنها كانت بيد الكفار غصبا ، فرجعت إلى أصحابها الشرعيين وهم المؤمنون الذين خلق الله لهم كل شيء ( عَلى رَسُولِهِ مِنْهُمْ ) أي من بني النضير ( فَما أَوْجَفْتُمْ ) أيها المسلمون ، و « ما » نافية ، والإيجاف تسيير الخيل والركاب من وجف يجف ، بمعنى تحرك باضطراب ، إذ الفتح بالقهر يلازم الاضطراب في الحركة ( عَلَيْهِ ) أي على ذلك الفيء ( مِنْ خَيْلٍ ) هي الفرس ( وَلا رِكابٍ ) هي الإبل ، أي أنكم لم تحصلوا على تلك الغنيمة بسبب الفتح بخيل أو إبل حتى يكون لكم ذلك الفيء. ( وَلكِنَّ اللهَ يُسَلِّطُ رُسُلَهُ عَلى مَنْ يَشاءُ ) من الكفار بإيقاع الرعب في قلوبهم حتى يفتح الرسول صلى‌الله‌عليه‌وآله‌وسلم مدنهم بلا حرب ولا تعب ( وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فيتمكن من تسليط الرسل على الكفار بلا حرب. ما أَفاءَ اللهُ عَلى رَسُولِهِ مِنْ أَهْلِ الْقُرى فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي الْقُرْبى وَالْيَتامى وَالْمَساكِينِ وَابْنِ السَّبِيلِ كَيْ لا يَكُونَ دُولَةً بَيْنَ الْأَغْنِياءِ مِنْكُمْ [8] وإذا تمهدت هذه المقدمة ـ وهي أن المسلمين إن لم يتعبوا على هذا الفيء ـ جاء السياق ليذكر حكمه ، وانه ليس لهم ، وإنما هو للرسول وآله ( ما أَفاءَ اللهُ ) أي ما أرجع الله سبحانه ( عَلى رَسُولِهِ مِنْ ) أموال ( أَهْلِ الْقُرى ) الكافرة التي حصل الرسول عليها بدون حرب ( فَلِلَّهِ ) تعالى ـ تشريفا للرسول ـ وإلا فكل شيء له سبحانه ( وَلِلرَّسُولِ ) بتمليك الله إياه ( وَلِذِي الْقُرْبى ) أي أهل بيت رسول الله وقرابته ، والمراد بهم الأئمة الطاهرون عليهم‌السلام . ( وَالْيَتامى ) جمع يتيم وهو من مات أبوه ( وَالْمَساكِينِ ) جمع مسكين وهو الفقير الذي أسكنه الفقر من الحركة ( وَابْنِ السَّبِيلِ ) وهو المنقطع في سفره الذي لا يعرف من أمره شيء ، ولذا ينسب إلى الطريق. وقد ثبت أن المراد بهؤلاء السادة من آل الرسول صلى‌الله‌عليه‌وآله‌وسلم ، ثم بين سبحانه الحكمة في جعل الفيء هكذا بقوله : ( كَيْ لا يَكُونَ ) الفيء ( دُولَةً ) وهي اسم للشيء الذي يتداوله القوم فيما بينهم يكون لهذا مرة ولهذا مرة ( بَيْنَ الْأَغْنِياءِ مِنْكُمْ ) حتى لا يعمل في الفيء ما كان يعمل في الجاهلية ، فقد كان إذا وقع غزو أخذ الرؤساء الأموال ، ومن المعلوم أن الرؤساء يتداولون المال بينهم بالضيافة والزواج لأبناء بعضهم من بنات بعض ، واستقبال بعضهم لبعض وهكذا مما يوجب نقل المال من هذا الرئيس إلى ذاك الرئيس فيبقى الفقراء محرومون ، وهذه العلّة أي قوله « لكي » مع العلة السابقة وهي « فما أوجفتم » يتمّان وَما آتاكُمُ الرَّسُولُ فَخُذُوهُ وَما نَهاكُمْ عَنْهُ فَانْتَهُوا وَاتَّقُوا اللهَ إِنَّ اللهَ شَدِيدُ الْعِقابِ (7) المطلوب ، إذ لا يخلو أمر الفيء بين أن يكون للرؤساء ، كالجاهلية ، أو للمسلمين كالغنائم ، أو للرسول وآله ، وإذ قد نفي الأول لأنه يوجب احتكار المال بين الأغنياء ، والثاني لأن المسلمين لم يتعبوا في تحصيله حتى يستحقوا شيئا ، لم يبق إلّا الثالث. ثم لما كان هذا الحكم شاقّا عليهم نزل قوله : ( وَما آتاكُمُ الرَّسُولُ ) أي أعطاكم من الأحكام ( فَخُذُوهُ ) أي تمسكوا به واعملوا بفحواه ( وَما نَهاكُمْ عَنْهُ ) وبين لكم حرمته ( فَانْتَهُوا ) عنه ولا ترتكبوه ( وَاتَّقُوا اللهَ ) أي خافوا عقابه فلا تخالفوه ( إِنَّ اللهَ شَدِيدُ الْعِقابِ ) لمن ترك أوامره وخالفه. قال في المجمع ـ ناقلا ـ إن الآية نزلت في رؤساء المسلمين قالوا له : يا رسول الله خذ صفيك والربع ودعنا والباقي فهكذا كنا نفعل في الجاهلية وأنشدوه لك المرباع منها والصفايا وحكمك والنشيطة والفضول فنزلت الآية فقالت الصحابة سمعا وطاعة لأمر الله وأمر رسوله (1) . [9] ثم بين سبحانه وصف الطوائف الأربع من آل الرسول صلى‌الله‌عليه‌وآله‌وسلم الذين خصص بهم الفيء ـ الذي لم يوجف عليه بخيل ولا ركاب ـ وليس ما يأتي من الوصف إلا كحكمة للتشريع حال نزول الآيات لا إنها أوصاف مشروطة دائما. ( 1) مجمع البيان : ج 9 ص 432. لِلْفُقَراءِ الْمُهاجِرِينَ الَّذِينَ أُخْرِجُوا مِنْ دِيارِهِمْ وَأَمْوالِهِمْ يَبْتَغُونَ فَضْلاً مِنَ اللهِ وَرِضْواناً وَيَنْصُرُونَ اللهَ وَرَسُولَهُ أُولئِكَ هُمُ الصَّادِقُونَ (8) وَالَّذِينَ تَبَوَّؤُا الدَّارَ وَالْإِيمانَ مِنْ قَبْلِهِمْ ( لِلْفُقَراءِ ) بدل لقوله ( لِذِي الْقُرْبى .. . ) أو ( وَالْيَتامى .. ) وهذا هو الأوفق بما ثبت من أن الإمام الذي يأخذ الفيء لا يشترط فيه الفقر ـ إلا أن يكون حكمه حال النزول ، كما ذكرنا ـ فلا تخصيص ( الْمُهاجِرِينَ ) الذين هاجروا من مكة إلى المدينة ( الَّذِينَ أُخْرِجُوا مِنْ دِيارِهِمْ ) أخرجهم الكفار ظلما وعدوانا ( وَأَمْوالِهِمْ ) إذ خلفوا أموالهم وراء ظهرهم ( يَبْتَغُونَ ) أي يطلبون هؤلاء المهاجرون ( فَضْلاً مِنَ اللهِ ) بأن يتفضل سبحانه عليهم عوض ما خلفوه وراءهم من الديار والأموال ( وَرِضْواناً ) بأن يرضى عنهم ( وَيَنْصُرُونَ اللهَ ) أي ينصرون دينه سبحانه ( وَرَسُولَهُ ) بالجهاد بين يديه لإعلاء كلمة الإسلام ( أُولئِكَ ) المتصفون بتلك الصفات ( هُمُ الصَّادِقُونَ ) الذين صدقوا في إيمانهم حيث أتوا بمقتضيات الإيمان. [10] وإذ جرى مدح المهاجرين ، جاء السياق ليمدح الأنصار ، بقوله ( وَالَّذِينَ تَبَوَّؤُا الدَّارَ ) يعني المدينة ، وهي دار الهجرة ، ومعنى « تبوؤا » اتخذوها منزلا ، ومبوءا ، من « باء » بمعنى رجع ويسمى المنزل مبوءا لأن الإنسان كلما خرج رجع إليه ( وَالْإِيمانَ ) أي تبوؤا الإيمان ، فهو كالمنزل الذي يتخذه الإنسان محل استراحة ورجوع ، فكلما نزل به أمر رجع إلى الإيمان يستلهمه العلاج والخلاص ، أو أن التقدير « آثروا الإيمان » ( مِنْ قَبْلِهِمْ ) أي قبل هجرة المهاجرين إلى المدينة ، فإن أهل المدينة آمنوا قبل هجرة المهاجرين يُحِبُّونَ مَنْ هاجَرَ إِلَيْهِمْ وَلا يَجِدُونَ فِي صُدُورِهِمْ حاجَةً مِمَّا أُوتُوا وَيُؤْثِرُونَ عَلى أَنْفُسِهِمْ وَلَوْ كانَ بِهِمْ خَصاصَةٌ وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُولئِكَ هُمُ الْمُفْلِحُونَ (9) وَالَّذِينَ جاؤُ مِنْ بَعْدِهِمْ يَقُولُونَ رَبَّنَا اغْفِرْ لَنا وَلِإِخْوانِنَا ( يُحِبُّونَ مَنْ هاجَرَ إِلَيْهِمْ ) من مكة وسائر القرى الكافرة ـ وهذا هو خبر « الذين » ـ والمعنى كما أن للمهاجرين المدح بما تقدم ، للأنصار المدح بأنهم يحبون المهاجرين ( وَلا يَجِدُونَ ) أي هؤلاء الأنصار ( فِي صُدُورِهِمْ حاجَةً مِمَّا أُوتُوا ) أي لا يحسدون المهاجرين من جهة ما آتاهم الرسول صلى‌الله‌عليه‌وآله‌وسلم من غنائم بني النضير ، ( وَيُؤْثِرُونَ عَلى أَنْفُسِهِمْ ) أي يقدمون المهاجرين في الإسكان والإحسان ، على أنفسهم ( وَلَوْ كانَ بِهِمْ ) أي بهؤلاء الأنصار ( خَصاصَةٌ ) أي احتياج وفقر ، فإنهم يرجحون المهاجرين على حاجة أنفسهم ، ومثل هذا الإنسان أعظم ثوابا ممن ينفق وهو غني. ( وَمَنْ يُوقَ شُحَّ نَفْسِهِ ) أي من يحفظ بلطف الله سبحانه ، من بخل النفس ، بأن لا تغلبه نفسه فتبخل ( فَأُولئِكَ هُمُ الْمُفْلِحُونَ ) أي الفائزون بالدرجات الرفيعة. [11] وإذ فرغ السياق عن المهاجرين والأنصار ، جاء ليمدح التابعين لهم بإحسان إلى يوم القيامة بقوله ( وَالَّذِينَ جاؤُ مِنْ بَعْدِهِمْ يَقُولُونَ ) بأن أسلموا من بعد المهاجرين والأنصار ، قولهم هذا ـ مما يدل على رسوخ الإيمان فيهم ـ ( رَبَّنَا اغْفِرْ لَنا ) ذنوبنا ( وَ ) اغفر ( لِإِخْوانِنَا الَّذِينَ سَبَقُونا بِالْإِيمانِ وَلا تَجْعَلْ فِي قُلُوبِنا غِلاًّ لِلَّذِينَ آمَنُوا رَبَّنا إِنَّكَ رَؤُفٌ رَحِيمٌ (10) أَ لَمْ تَرَ إِلَى الَّذِينَ نافَقُوا يَقُولُونَ لِإِخْوانِهِمُ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتابِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلا نُطِيعُ فِيكُمْ أَحَداً أَبَداً وَإِنْ قُوتِلْتُمْ لَنَنْصُرَنَّكُمْ الَّذِينَ سَبَقُونا بِالْإِيمانِ ) من المهاجرين والأنصار وغيرهم ( وَلا تَجْعَلْ فِي قُلُوبِنا غِلًّا ) أي حقدا وغشّا وعداوة ( لِلَّذِينَ آمَنُوا ) من مضى منهم أو من عاصرناهم وإنما قال « لا تجعل » لبيان أن اللطف منه سبحانه ، حتى إذا لم يلطف بإنسان كان معرضا للغل ، والمعنى لا تتركنا على أحوالنا ، حتى يستولي علينا الشيطان والنفس ، فتكون أنفسنا معرضا للغل ( رَبَّنا إِنَّكَ رَؤُفٌ ) بعبادك ( رَحِيمٌ ) بهم ، وهذا تعليم للمؤمنين كيف ينبغي أن يكونوا اتجاه من سبقهم ، وتجاه سائر المؤمنين المعاصرين لهم. [12] وإذا سبق مدح المؤمنين وبيان صفاتهم ، جاء السياق ليظهر طرفا من أحوال المنافقين بقوله : ( أَ لَمْ تَرَ ) يا رسول الله ، أو أيها الرائي ، والاستفهام للتعجب والاستنكار ( إِلَى الَّذِينَ نافَقُوا ) بأن أظهروا الإيمان وأبطنوا الكفر ( يَقُولُونَ لِإِخْوانِهِمُ ) في الكفر ( الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتابِ ) أي كفروا بالرسول صلى‌الله‌عليه‌وآله‌وسلم ، والمراد بهم يهود بني النضير ( لَئِنْ أُخْرِجْتُمْ ) أي أخرجكم الرسول من دياركم وبلادكم ( لَنَخْرُجَنَّ مَعَكُمْ ) موافقة لكم ، فلا نبقى في بلادنا ، ( وَلا نُطِيعُ فِيكُمْ ) أي في أمر قتالكم ( أَحَداً ) يعنون الرسول صلى‌الله‌عليه‌وآله‌وسلم ( أَبَداً ) فإذا أمرنا بقتالكم لا نقاتلكم ( وَإِنْ قُوتِلْتُمْ ) بأن قاتلكم الرسول والمسلمون ( لَنَنْصُرَنَّكُمْ ) وَاللهُ يَشْهَدُ إِنَّهُمْ لَكاذِبُونَ (11) لَئِنْ أُخْرِجُوا لا يَخْرُجُونَ مَعَهُمْ وَلَئِنْ قُوتِلُوا لا يَنْصُرُونَهُمْ وَلَئِنْ نَصَرُوهُمْ لَيُوَلُّنَّ الْأَدْبارَ ثُمَّ لا يُنْصَرُونَ (12) لَأَنْتُمْ أَشَدُّ رَهْبَةً فِي صُدُورِهِمْ أي نكون في جهتكم ضد الرسول والمسلمين ( وَاللهُ يَشْهَدُ إِنَّهُمْ ) أي هؤلاء المنافقين ( لَكاذِبُونَ ) في أقوالهم ، فلا يخرجون مع بني النضير ولا يقاتلون معهم فقد قالوا : إن عبد الله بن أبي كان يحرض اليهود على الاستمائة وقتال الرسول ويمنيهم بهذه المواعيد الكاذبة ، وكان كما قال الله سبحانه كذب حين أتى وقت العمل.` },
            { text: "وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `` },
            { text: "مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ", tafsir: `` },
            { text: "لِلْفُقَرَآءِ ٱلْمُهَٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ", tafsir: `` },
            { text: "وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةً مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ", tafsir: `` },
            { text: "وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌ رَّحِيمٌ", tafsir: `` },
            { text: "أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ", tafsir: `` },
            { text: "لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَٰرَ ثُمَّ لَا يُنصَرُونَ", tafsir: `أي أخرج النبي صلى‌الله‌عليه‌وآله‌وسلم بني النضير ( لا يَخْرُجُونَ ) أي هؤلاء المنافقون ( مَعَهُمْ ) تشاركا معهم في الفرار والتخلص ( وَلَئِنْ قُوتِلُوا ) أي قاتلهم المسلمون ( لا يَنْصُرُونَهُمْ ) كما زعموا ( وَلَئِنْ نَصَرُوهُمْ ) على فرض مستحيل ( لَيُوَلُّنَّ الْأَدْبارَ ) أي ينهزمون عن مقابلة الرسول والمسلمين ويسلمون بني النضير طعمة سائغة لحراب المسلمين ( ثُمَ ) اليهود ( لا يُنْصَرُونَ ) على فرض أنهم بقوا معهم ولم يولوا الأدبار ، لأن المنافقين أذل من أن يتمكنوا من المقاومة أمام الرسول وكتائب المسلمين المجاهدة. [14] ثم يأتي السياق ليبين أن المنافقين خائفون من المسلمين أشد الخوف فكيف يتمكنون من نصرة اليهود في قبال المسلمين ؟ ( لَأَنْتُمْ ) أيها المسلمون ( أَشَدُّ رَهْبَةً ) أي خوفا ( فِي صُدُورِهِمْ ) أي صدور هؤلاء المنافقين ، أو اليهود ، وإنما قال « في صدورهم » لأن الصدر مكان مِنَ اللهِ ذلِكَ بِأَنَّهُمْ قَوْمٌ لا يَفْقَهُونَ (13) لا يُقاتِلُونَكُمْ جَمِيعاً إِلاَّ فِي قُرىً مُحَصَّنَةٍ أَوْ مِنْ وَراءِ جُدُرٍ بَأْسُهُمْ بَيْنَهُمْ شَدِيدٌ تَحْسَبُهُمْ جَمِيعاً وَقُلُوبُهُمْ شَتَّى القلب والقلب مبعث النفس التي تحمل الخوف والاطمئنان ( مِنَ اللهِ ) فهم لا يخافون من الله قدر ما يخافون منكم ، لأنهم يرونكم ولا يرون الله سبحانه ، ولم يتمكن الإيمان في قلوبهم حتى يخافونه ، ( ذلِكَ ) أي شدّة خوفهم منكم بسبب أنهم ( قَوْمٌ لا يَفْقَهُونَ ) أي لا يعقلون ولا يعرفون عظمته سبحانه ، ومن لم يعرف الملك لم يهبه. [15] ثم بين سبحانه أن قتال اليهود للمسلمين ليس مثل سائر الحروب ، فإنهم لشدة خوفهم من المسلمين واختلاف الكلمة فيما بينهم لا جرأة لهم على المقاتلة السافرة ، وذلك مما يشجع المسلمين على القتال ( لا يُقاتِلُونَكُمْ ) أيها المسلمون ، هؤلاء اليهود ( جَمِيعاً ) أي في حال اجتماعهم ـ وذلك لبيان شدة ضعفهم حتى أن جميعهم لا يتمكنون من القتال إلا بالكيفية الآتية ـ أو المراد بضمير الفاعل : اليهود والمنافقون ، وجميعا لتأكيد ذلك ( إِلَّا فِي قُرىً مُحَصَّنَةٍ ) أي لا يبرزون لحربكم إلا وهم متحصنون بالقرى ذوات الحصون والامتناع ( أَوْ مِنْ وَراءِ جُدُرٍ ) جمع جدار ، يرمونكم بالنبل والحجارة وما أشبه. ( بَأْسُهُمْ بَيْنَهُمْ شَدِيدٌ ) يعني أن عداوة بعضهم لبعض شديدة ، فلا ائتلاف بينهم ولا اتحاد ، حتى تتفق قلوبهم ويشجعوا في مقاتلتكم ( تَحْسَبُهُمْ ) أي تظنهم يا رسول الله ، أو أيها الرائي ( جَمِيعاً ) أي متفقين متراصين ( وَ ) الحال ليسوا كذلك بل ( قُلُوبُهُمْ شَتَّى ) جمع ذلِكَ بِأَنَّهُمْ قَوْمٌ لا يَعْقِلُونَ (14) كَمَثَلِ الَّذِينَ مِنْ قَبْلِهِمْ قَرِيباً ذاقُوا وَبالَ أَمْرِهِمْ وَلَهُمْ عَذابٌ أَلِيمٌ (15) شتيت كمرضى ومريض ، والشتيت هو المتفرق ، أي أن قلوبهم متفرقة ( ذلِكَ ) الذي ذكر في وصفهم بسبب أنهم ( قَوْمٌ لا يَعْقِلُونَ ) ما فيه الرشد مما فيه الغي ، ومن لا يعقل يكون بما ذكر له من الصفة ، وهذه الصفات في اليهود إنما تولدت من منهجين ينهجون عليهما الأول : ـ زعمهم بأنهم شعب الله المختار. والثاني : تكالبهم على المادة ، فإن الاتفاق وسائر الفضائل إنما تتولد من التواضع وتحكيم الروحيات في الأمور ، فإذا زعم كل إنسان أنه فاضل لم يرضخ لغيره مما يسبب التشتيت ، وإذا اتجه الإنسان نحو المادة لم تهذب نفسه حتى ينبع منها الخير والفضيلة ، ولذا نرى عبر التاريخ ، اليهود بين معتد ، وبين مطارد ، إن صار لهم شيء اعتدوا ثم جاء من يطاردهم ، وهكذا دواليك ، وقد رأينا في عصرنا قصة اعتدائهم في « ألمانيا » ومطاردة « هتلر » لهم .. . ثم اعتدائهم في المسلمين ، وأخذت السحب تتجمع هنا وهناك لمطاردتهم. [16] ومثل بني النضير ( كَمَثَلِ الَّذِينَ مِنْ قَبْلِهِمْ قَرِيباً ) وهم بنو قينقاع الذين نقضوا عهد الرسول فأمرهم صلى‌الله‌عليه‌وآله‌وسلم بالخروج ( ذاقُوا وَبالَ أَمْرِهِمْ ) أي عاقبة عملهم السيئة ، و ( لَهُمْ عَذابٌ أَلِيمٌ ) أي مؤلم موجع في الآخرة ، وقد كان عبد الله بن أبيّ المنافق وعدهم النصر ، فلم ينصرهم ، كما غر بني النضير وخذلهم حين التحموا بجيش المسلمين. كَمَثَلِ الشَّيْطانِ إِذْ قالَ لِلْإِنْسانِ اكْفُرْ فَلَمَّا كَفَرَ قالَ إِنِّي بَرِيءٌ مِنْكَ إِنِّي أَخافُ اللهَ رَبَّ الْعالَمِينَ (16) فَكانَ عاقِبَتَهُما أَنَّهُما فِي النَّارِ خالِدَيْنِ فِيها وَذلِكَ جَزاءُ الظَّالِمِينَ (17) يا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ وَلْتَنْظُرْ نَفْسٌ ما قَدَّمَتْ لِغَدٍ [17] فكان مثله ( كَمَثَلِ الشَّيْطانِ ) في تغريره ثم خذلانه وتسليمه إلى عذاب الله ( إِذْ قالَ لِلْإِنْسانِ اكْفُرْ ) بأن وسوس إليه وزين الكفر في نظره حتى أطاعه فكفر ( فَلَمَّا كَفَرَ ) وخالف الله سبحانه بما استحق به عذابه ( قالَ ) الشيطان ( إِنِّي بَرِيءٌ مِنْكَ ) أيها الكافر لا أنصرك ولا أخلصك من عذاب الله ( إِنِّي أَخافُ اللهَ رَبَّ الْعالَمِينَ ) وهل الخائف يتمكن من نصرة غيره ؟ وكذلك ابن أبيّ غرّ بني النضير وبني قينقاع حتى حاربا الرسول ، فلم ينصرهما بل خذلهما.` },
            { text: "لَأَنتُمْ أَشَدُّ رَهْبَةً فِى صُدُورِهِم مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ", tafsir: `` },
            { text: "لَا يُقَٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ بَأْسُهُم بَيْنَهُمْ شَدِيدٌ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ", tafsir: `` },
            { text: "كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًا ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "كَمَثَلِ ٱلشَّيْطَٰنِ إِذْ قَالَ لِلْإِنسَٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَٰلِدَيْنِ فِيهَا وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ", tafsir: `أي عاقبة الشيطان والإنسان الذي غرّه فكفر ، ( أَنَّهُما فِي النَّارِ ) حال كونهما ( خالِدَيْنِ فِيها ) أي استحقا النار ولقيا العذاب ، ذاك بإغرائه ، وهذا بكفره ( وَذلِكَ ) العقاب ( جَزاءُ الظَّالِمِينَ ) الذين ظلموا أنفسهم بالكفر اغترارا بكلام الشيطان.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ", tafsir: `أي خافوا عقابه ، فلا تتركوا أوامره ، وتخصيص الخطاب بالمؤمنين لأنهم المنتفعون به وإلا فالتقوى تجب على كل أحد ( وَلْتَنْظُرْ نَفْسٌ ) أي لينظر كل إنسان ويفكر في ( ما قَدَّمَتْ لِغَدٍ ) أي ليوم القيامة ، هل أنه قدم الصالح أو الفاسد ، الثواب وَاتَّقُوا اللهَ إِنَّ اللهَ خَبِيرٌ بِما تَعْمَلُونَ (18) وَلا تَكُونُوا كَالَّذِينَ نَسُوا اللهَ فَأَنْساهُمْ أَنْفُسَهُمْ أُولئِكَ هُمُ الْفاسِقُونَ (19) لا يَسْتَوِي أَصْحابُ النَّارِ وَأَصْحابُ الْجَنَّةِ أَصْحابُ الْجَنَّةِ هُمُ الْفائِزُونَ (20) أو العقاب بمعنى لزوم تقديم الشيء الحسن وإن كل عمل يعمله الإنسان فإنما يراه غدا ( وَاتَّقُوا اللهَ ) فلا تخالفوا أوامره وزواجره ( إِنَّ اللهَ خَبِيرٌ بِما تَعْمَلُونَ ) مطلع على أعمالكم فيجازيكم غدا عليها.` },
            { text: "وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ أُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ", tafsir: `يا أيها المؤمنون ( كَالَّذِينَ نَسُوا اللهَ ) بأن آمنوا ثم نسوا الله فخالفوه ، كأهل الكتاب ، وليس المراد نسيانهم له حقيقة ، بل أعم من ذلك وممن ترك الأوامر ، فإن العالم التارك كالناسي في عدم الامتثال ( فَأَنْساهُمْ ) الله ( أَنْفُسَهُمْ ) أي جعلهم الله ناسين حتى أنهم لم يعملوا لنجاتها وخلاصها كالإنسان الذي ينسى نفسه فلا يهتم بشأنها ( أُولئِكَ ) الذين تلك صفتهم ( هُمُ الْفاسِقُونَ ) الخارجون عن طاعة الله تعالى. [21] وهل يتساوى هؤلاء الذين يدخلون النار جزاء لكفرهم وعصيانهم مع الذين يدخلون الجنة جزاء لإيمانهم وعملهم الصالح ؟ كلا ( لا يَسْتَوِي أَصْحابُ النَّارِ ) الملازمون لها ( وَأَصْحابُ الْجَنَّةِ ) الدائمون فيها ( أَصْحابُ الْجَنَّةِ هُمُ الْفائِزُونَ ) الذين فازوا بالثواب والنجاة. [22] وكيف لا يخشع الكفار للقرآن حتى يؤمنوا بما جاء به ، والحال أن القرآن لو نزل على جبل لخشع ؟ فما يخشع له الجبل الجامد ، كيف لَوْ أَنْزَلْنا هذَا الْقُرْآنَ عَلى جَبَلٍ لَرَأَيْتَهُ خاشِعاً مُتَصَدِّعاً مِنْ خَشْيَةِ اللهِ وَتِلْكَ الْأَمْثالُ نَضْرِبُها لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ (21) هُوَ اللهُ الَّذِي لا إِلهَ إِلاَّ هُوَ لا يخشع له القلب القاسي ( فَهِيَ كَالْحِجارَةِ أَوْ أَشَدُّ قَسْوَةً ) (1) ( لَوْ أَنْزَلْنا هذَا الْقُرْآنَ عَلى جَبَلٍ ) بأن كان الجبل هو المخاطب بالقرآن الموظف للعمل به ( لَرَأَيْتَهُ ) أي رأيت يا رسول الله ، أو أيها الرائي ، ذلك الجبل ( خاشِعاً ) خاضعا خائفا ( مُتَصَدِّعاً ) أي منشقا ( مِنْ خَشْيَةِ اللهِ ) وخوفه ، وهذا إما على نحو الحقيقة باعتبار أن للجماد إدراكا وان كنا لا نعرف كيفية إدراكه ، كما قال سبحانه ( يا جِبالُ أَوِّبِي مَعَهُ ) (2) وقال ( قالَتا أَتَيْنا طائِعِينَ ) (3) وقال ( وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ ) (4) وقال ( وَأَشْفَقْنَ مِنْها ) (5) وإما على المجاز كناية عن قوة ما في القرآن من النفوذ والمضي حتى إن الجبل ـ مع عظمته ـ لو عقل لخشع وتصدع ، فكيف لا يخشع الإنسان ؟ ( وَتِلْكَ الْأَمْثالُ نَضْرِبُها لِلنَّاسِ ) أي هذا المثل وما أشبهه نبينها للناس ، وهذا مثل لشدة نفوذ القرآن ومضيه ، لتقريب عظمة القرآن إلى الأذهان ( لَعَلَّهُمْ يَتَفَكَّرُونَ ) أي لكي يتفكروا فيما ضرب له المثل ، فإن المثل يقرب الذهن إلى الممثّل له ، فيكون مجال التفكير فيه أوسع. [23] ثم أتى السياق لبيان جملة من صفات الله سبحانه ، لبيان خضوع الوجود كله له تعالى كما أن الجبل يخضع لكلامه ( هُوَ اللهُ الَّذِي لا إِلهَ إِلَّا هُوَ ) ( 1) البقرة : 75. ( 2) سبأ : 11. ( 3) فصلت : 12. ( 4) الإسراء : 45. ( 5) الأحزاب : 73. عالِمُ الْغَيْبِ وَالشَّهادَةِ هُوَ الرَّحْمنُ الرَّحِيمُ (22) هُوَ اللهُ الَّذِي لا إِلهَ إِلاَّ هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ أي لا متصرف في الكون ولا معبود بالحق إلا هو وحده بلا شريك ( عالِمُ الْغَيْبِ وَالشَّهادَةِ ) فيعلم كل شيء سواء كان غائبا عن الحواس كالملك والجن وما أشبههما ، أو تشهده الحاسة وتدركه كالمرئيات والمسموعات وما إليهما. أو عن الباقر عليه‌السلام انه قال : الغيب ما لم يكن والشهادة ما كان ( هُوَ الرَّحْمنُ ) المتفضل على جميع خلقه ( الرَّحِيمُ ) المتفضل على المؤمنين ، فاطلاعه اطلاع رحمن رحيم لا اطلاع قسي غليظ شديد.` },
            { text: "لَا يَسْتَوِىٓ أَصْحَٰبُ ٱلنَّارِ وَأَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ", tafsir: `` },
            { text: "لَوْ أَنزَلْنَا هَٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُۥ خَٰشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ ٱللَّهِ وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ", tafsir: `` },
            { text: "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ", tafsir: `` },
            { text: "هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ", tafsir: `والتكرار يفيد التركيز في مقابل عبّاد الأوثان والطبيعيين ومن إليهم ( الْمَلِكُ ) السيد المطاع المالك للكون ( الْقُدُّوسُ ) المنزه من كل نقص وعيب وآفة وقبيح ، من القدس وهو الطهارة والنزاهة ( السَّلامُ ) الذي سلّم الكون منه تعالى ، فليس كالملوك المفسدين للعباد والبلاد ، أو المعنى انه السالم من الآفات ، حتى كأنه قطعة من السلام من باب « زيد عدل » . ( الْمُؤْمِنُ ) الذي سلّم خلقه من ظلمه ، أو واهب الإيمان ، أو بمعنى أن له تعلقا بالخلق كما أن للمؤمن تعلقا بالخالق ، فإن أصل الإيمان التعلّق بشيء ( الْمُهَيْمِنُ ) المسيطر على الكون ، من الهيمنة بمعنى السيطرة ( الْعَزِيزُ ) الغالب في سلطانه أو هو ما قل وجوده وكثر نفعه ، والله أظهر المصاديق لذلك ، لتفرده واحتياج الكون إليه ( الْجَبَّارُ ) الذي يجبر الكسر ، أو الذي يقهر غيره ، فإن الكون كله الْمُتَكَبِّرُ سُبْحانَ اللهِ عَمَّا يُشْرِكُونَ (23) هُوَ اللهُ الْخالِقُ الْبارِئُ الْمُصَوِّرُ لَهُ الْأَسْماءُ الْحُسْنى يُسَبِّحُ لَهُ ما فِي السَّماواتِ وَالْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ (24) مقهور له مسيّر بإرادته ( الْمُتَكَبِّرُ ) الذي تكبر وتعالى عن كل ما يوجب نقصا وحاجة ( سُبْحانَ اللهِ ) أنزهه تنزيها ( عَمَّا يُشْرِكُونَ ) عما يشرك به المشركون من الأصنام والأوثان.` },
            { text: "هُوَ ٱللَّهُ ٱلْخَٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `` }
        ]
    },
    60: { // سورة الممتحنة
        name: "الممتحنة",
        basmalaTafsir: ``,
        verses: [
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَٰدًا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ", tafsir: `الذي يعاديني بالكفر والعصيان ( وَعَدُوَّكُمْ ) الذي يعاديكم بالاستهزاء والمحاربة وسائر أنواع العداوة ( أَوْلِياءَ ) توالونهم وتنصرونهم ، جمع « ولي » في حال كونكم ( تُلْقُونَ إِلَيْهِمْ بِالْمَوَدَّةِ ) أي تبذلون لهم ودكم وحبكم ، عمل المحب لمحبه ، كما فعل « حاطب » بأهل مكة الذين هم أعداء الله وأعداء المسلمين ( وَقَدْ كَفَرُوا ) أولئك الأعداء ( بِما جاءَكُمْ مِنَ الْحَقِ ) الإسلام والقرآن والرسول ، وهم ( يُخْرِجُونَ الرَّسُولَ وَإِيَّاكُمْ ) عن بلادهم ـ كما فعل كفار مكة ـ والإخراج إنما كان ل ( أَنْ تُؤْمِنُوا ) أي لإيمانكم ( بِاللهِ رَبِّكُمْ ) وهل يوالي الإنسان مثل هذا العدو ؟ ( إِنْ كُنْتُمْ خَرَجْتُمْ ) أيها المؤمنون من بلادكم ( جِهاداً فِي سَبِيلِي ) أي لأجل الجهاد في سبيل الله ( وَابْتِغاءَ مَرْضاتِي ) أي طلبا لرضاي والمعنى أن غرضكم من الخروج والهجرة الجهاد وطلب رضا الله ، فلا توادوا عدو الله وعدوكم ـ أهل مكة ـ ( تُسِرُّونَ إِلَيْهِمْ بِالْمَوَدَّةِ ) أي تعلمونهم في السر بينكم وبينهم مودة وحب ( وَ ) هل يخفى عملكم هذا على الله ؟ كلا ف ( أَنَا أَعْلَمُ ) من كل أحد ( بِما أَخْفَيْتُمْ وَما أَعْلَنْتُمْ ) أي بخفايا أموركم وظواهرها فلا يغيب عليّ وَمَنْ يَفْعَلْهُ مِنْكُمْ فَقَدْ ضَلَّ سَواءَ السَّبِيلِ (1) إِنْ يَثْقَفُوكُمْ يَكُونُوا لَكُمْ أَعْداءً وَيَبْسُطُوا إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُمْ بِالسُّوءِ وَوَدُّوا لَوْ تَكْفُرُونَ (2) لَنْ تَنْفَعَكُمْ أَرْحامُكُمْ وَلا أَوْلادُكُمْ يَوْمَ الْقِيامَةِ يَفْصِلُ بَيْنَكُمْ شيء ، وسأجازيكم عليها ( وَمَنْ يَفْعَلْهُ ) أي يفعل الإسرار بالمودة ( مِنْكُمْ ) أيها المؤمنون ( فَقَدْ ضَلَّ سَواءَ السَّبِيلِ ) أي عدل عن طريق الحق إلى المهلكة ، وسواء الطريق : وسطه.` },
            { text: "إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءً وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ", tafsir: `أي إن يصادف كفار مكة لكم أيها المؤمنون في الحرب ( يَكُونُوا لَكُمْ أَعْداءً ) يبادرونكم بالمحاربة ، فعل العدو بعدوه ، وهذا لنفي ما زعمه حاطب من أنهم أحباؤه ، فتأتي الآية لتبين إن إظهار حبهم له ولعائلته إظهار مكذوب لا حقيقة له ( وَيَبْسُطُوا إِلَيْكُمْ ) أيها المؤمنون ( أَيْدِيَهُمْ ) بالضرب والقتل ( وَأَلْسِنَتَهُمْ ) بالسب والقذف ( بِالسُّوءِ ) أي بما يسيئوكم ، فلا يتركون وسيلة من وسائل الإساءة إلا عملوها بالنسبة إليكم ( وَوَدُّوا ) أي أحب هؤلاء الكفار ( لَوْ تَكْفُرُونَ ) أنتم بالله كما كفروا هم ، فلا يسبب إهلاككم مودّة أمثال هؤلاء الكفار فإنه :` },
            { text: "لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَٰدُكُمْ يَوْمَ ٱلْقِيَٰمَةِ يَفْصِلُ بَيْنَكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `أيها المؤمنون ( أَرْحامُكُمْ ) أي قراباتكم ( وَلا أَوْلادُكُمْ ) والمعنى لا يحملنكم التحفظ على القرابة والأولاد على مخالفة الله والرسول وموادة الكفار ، كما فعل حاطب حيث أراد التحفظ على أهله بمكة فخالف الرسول بأن كتب إلى الكفار ، يعلمهم بقصد الرسول صلى‌الله‌عليه‌وآله‌وسلم فتح مكة ( يَوْمَ الْقِيامَةِ يَفْصِلُ ) الله ( بَيْنَكُمْ ) فيدخل أهل وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ (3) قَدْ كانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إِبْراهِيمَ وَالَّذِينَ مَعَهُ إِذْ قالُوا لِقَوْمِهِمْ إِنَّا بُرَآؤُا مِنْكُمْ وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللهِ كَفَرْنا بِكُمْ وَبَدا بَيْنَنا وَبَيْنَكُمُ الْعَداوَةُ وَالْبَغْضاءُ أَبَداً حَتَّى تُؤْمِنُوا بِاللهِ وَحْدَهُ إِلاَّ قَوْلَ إِبْراهِيمَ الإيمان الجنة ويدخل أهل الكفر والعصيان النار ، فلا تفعلوا ما تستحقون به النيران ( وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ ) يبصركم ويرى أعمالكم ، فلا تفعلوا ما تستحقون به سخطه وعقابه.` },
            { text: "قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ", tafsir: `أيها المؤمنون ( أُسْوَةٌ حَسَنَةٌ ) أي اقتداء حسن ، الأسوة هي القدوة وهو اسم لما يؤتسى ويقتدى به ( فِي إِبْراهِيمَ ) الخليل عليه‌السلام ( وَالَّذِينَ ) آمنوا ( مَعَهُ ) أي فاقتدوا بهم أيها المؤمنون في مقاطعة الكفار ( إِذْ قالُوا لِقَوْمِهِمْ ) الكافرين ( إِنَّا بُرَآؤُا مِنْكُمْ ) جمع بريء ، فلا نواليكم ( وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللهِ ) أي ومن أصنامكم التي تعبدونها ، والمعنى لا علاقة لنا بها ، بل نظهر انها باطلة ليست بآلهة ، فعل العدو بعدوه ، وإن لم تكن معاداة حقيقية بين الإنسان وبين الجماد ( كَفَرْنا بِكُمْ ) أي قالوا لقومهم جحدنا طريقتكم ، أو خطاب للأصنام ، والإتيان بلفظ العاقل لتوحيد سياق كلام المؤمنين مع كلام الكافرين فإنهم كانوا يزعمون العقل والإدراك للأصنام ( وَبَدا ) أي ظهر ( بَيْنَنا وَبَيْنَكُمُ ) أيها القوم الكافرين ( الْعَداوَةُ وَالْبَغْضاءُ ) وهو أشد العداوة الموجبة لكون العداء في الباطن ، من « بغض » ( أَبَداً ) أي إلى الأبد ما دمتم أنتم على الكفر ( حَتَّى تُؤْمِنُوا بِاللهِ وَحْدَهُ ) وتخلعوا عبادة الأصنام ( إِلَّا قَوْلَ إِبْراهِيمَ ) أي اقتدوا بإبراهيم ، إلا في هذا القول ـ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَما أَمْلِكُ لَكَ مِنَ اللهِ مِنْ شَيْءٍ رَبَّنا عَلَيْكَ تَوَكَّلْنا وَإِلَيْكَ أَنَبْنا وَإِلَيْكَ الْمَصِيرُ (4) رَبَّنا لا تَجْعَلْنا فِتْنَةً لِلَّذِينَ كَفَرُوا وَاغْفِرْ لَنا رَبَّنا إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ (5) الذي قال لأبيه وذلك كان قبل نهي الله سبحانه ـ ( لِأَبِيهِ ) أي عمه آزر ( لَأَسْتَغْفِرَنَّ لَكَ ) أي أطلب غفران الله لك ، وكان ذلك لموعدة وعده إياه ، فلما تبيّن له أنه عدوّ لله تبرأ منه ، فلا ينبغي للمسلم أن يقتدي بذلك ، بأن يستغفر للكافر ويحتمل أن الاستثناء من قوله « إنا برآء منكم » أي قالوا للكفار إنّا أعداء لكم ، إلا إبراهيم وعد عمه بالاستغفار قبل أن يتبين أنه عدو لله ، ثم قال إبراهيم لعمه ( وَما أَمْلِكُ لَكَ ) يا عم ( مِنَ اللهِ مِنْ شَيْءٍ ) فإذا أراد بك شيئا لم أملك أن أرد العقاب عنك ، ثم قال إبراهيم والمؤمنون به ( رَبَّنا عَلَيْكَ تَوَكَّلْنا ) فقد وكلنا أمورنا إليك ( وَإِلَيْكَ أَنَبْنا ) الإنابة هي الرجوع أي رجعنا إليك في أمورنا ، فإن الإنسان باعتبار أنه مخلوق لله تعالى كأنه جاء من عنده ، فهو إذا أطاع كان بمنزلة الراجع إليه سبحانه ، تشبيها للمعقول بالمحسوس ( وَإِلَيْكَ الْمَصِيرُ ) أي ان منتهى أمورنا إليك ، ونعود في يوم القيامة إلى حسابك وجزائك.` },
            { text: "رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `أي لا تجعلنا امتحانا لهم فإن الكافر يمتحن بالكفر وبإيذاء المؤمنين وبالعصيان ، وإذا وقع المؤمن مورد امتحان الكافر ، أو ذي وقد لا يطيق ذلك ، أو المراد لا تسلطهم علينا فيفتنونا بعذاب لا نتحمله ( وَاغْفِرْ لَنا ) أي استر علينا وامح سيئاتنا ( رَبَّنا إِنَّكَ أَنْتَ الْعَزِيزُ ) الذي لا يغلب القاهر في سلطانه ( الْحَكِيمُ ) الذي يفعل كل شيء حسب الصلاح والحكمة ، ولعل حكاية هذه لَقَدْ كانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِمَنْ كانَ يَرْجُوا اللهَ وَالْيَوْمَ الْآخِرَ وَمَنْ يَتَوَلَّ فَإِنَّ اللهَ هُوَ الْغَنِيُّ الْحَمِيدُ (6) عَسَى اللهُ أَنْ يَجْعَلَ بَيْنَكُمْ وَبَيْنَ الَّذِينَ عادَيْتُمْ مِنْهُمْ مَوَدَّةً وَاللهُ قَدِيرٌ وَاللهُ الجمل لتعليم المسلمين كيف يدعون الله سبحانه.` },
            { text: "لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ", tafsir: `أيها المؤمنون في عصر الرسالة ( فِيهِمْ أُسْوَةٌ حَسَنَةٌ ) « في » بمعنى النسبة ، أي بالنسبة إلى إبراهيم ومن آمن معه اقتداء حسن ، فهم خير مقتدى لكم في أعمالكم ، ومقاطعتهم للكفار وإنما كرر ذلك لما رتب عليه بقوله ( لِمَنْ كانَ يَرْجُوا اللهَ وَالْيَوْمَ الْآخِرَ ) أي أن هذه الأسوة والاقتداء إنما هي للذي يرجو ثواب الله سبحانه « ليعتقد بالجزاء والحساب في الآخرة » أما المنكر لذلك فلا معنى لاقتدائه بمن اعتقد بالله وهذا للإشارة إلى التلازم بين الإيمان وبين الاقتداء ( وَمَنْ يَتَوَلَ ) أي يعرض عن هذا الاقتداء ، فلم يقتد بإبراهيم ، بل اتخذ من الكفار أولياء ( فَإِنَّ اللهَ هُوَ الْغَنِيُ ) الذي لا يحتاج إلى أحد وإلى عمل ( الْحَمِيدُ ) المحمود بذاته فلا يحتاج إلى طاعة المطيع وحمد الحامد ، والمعنى : أن الذي يعرض يضر نفسه ، ولا يضر الله سبحانه لغناه المطلق. [8] وإذا تريدون أيها المؤمنون موادة أهل مكة لما بينكم من الصلات النسبية والسوابق فلعله سبحانه يهيئ وسائل هدايتهم حتى لا يكون محظور في موادتهم ( عَسَى اللهُ ) أي لعله سبحانه ( أَنْ يَجْعَلَ بَيْنَكُمْ ) أيها المؤمنون ( وَبَيْنَ الَّذِينَ عادَيْتُمْ ) أي اتخذتموهم أعداء ( مِنْهُمْ ) أي من أهل مكة ( مَوَدَّةً ) بسبب الإسلام ( وَاللهُ قَدِيرٌ ) على ذلك ( وَاللهُ غَفُورٌ رَحِيمٌ (7) لا يَنْهاكُمُ اللهُ عَنِ الَّذِينَ لَمْ يُقاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللهَ يُحِبُّ الْمُقْسِطِينَ (8) إِنَّما يَنْهاكُمُ اللهُ عَنِ الَّذِينَ قاتَلُوكُمْ فِي الدِّينِ وَأَخْرَجُوكُمْ مِنْ دِيارِكُمْ وَظاهَرُوا عَلى إِخْراجِكُمْ غَفُورٌ ) لما سلف منكم من موادتهم في حال كفرهم ( رَحِيمٌ ) يتفضل عليكم بالرحمة بالإضافة إلى الغفران والعفو. [9] وإذا كان المفهوم من الآيات السابقة ما يشمل تحريم موادة كل كافر استثنى السياق من ذلك بقوله ( لا يَنْهاكُمُ ) أيها المؤمنون ( اللهُ عَنِ ) موادة ( الَّذِينَ لَمْ يُقاتِلُوكُمْ فِي ) أمر ( الدِّينِ ) أي من جهة أنكم متدينون بالإسلام ( وَلَمْ يُخْرِجُوكُمْ مِنْ دِيارِكُمْ ) بأن كان كافرا مسالما ( أَنْ تَبَرُّوهُمْ ) بدل اشتمال عن قوله « عن الذين » أي لا ينهاكم الله عن بر هؤلاء ( وَتُقْسِطُوا إِلَيْهِمْ ) أي تعدلوا فيما بينكم وبينهم ، بأن تبادلوا الحب والوداد قيل ان المسلمين استأمروا النبي صلى‌الله‌عليه‌وآله‌وسلم في أن يبروا أقرباءهم من المشركين (1) وقيل ان قتيلة بنت عبد العزيز قدمت مشركة على بنتها أسماء بهدايا فلم تقبلها ولم تأذن لها بالدخول ، فنزلت هذه الآية ( إِنَّ اللهَ يُحِبُّ الْمُقْسِطِينَ ) أي الذين يعدلون في أمورهم.` },
            { text: "عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةً وَٱللَّهُ قَدِيرٌ وَٱللَّهُ غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ", tafsir: `` },
            { text: "إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَٰرِكُمْ وَظَٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ وَمَن يَتَوَلَّهُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ", tafsir: `أيها المؤمنون ( عَنِ ) موادة ( الَّذِينَ قاتَلُوكُمْ فِي الدِّينِ ) فقاتلوكم من جهة أنكم متدينون ( وَأَخْرَجُوكُمْ مِنْ دِيارِكُمْ ) منازلكم ، في مكة وغيرها ( وَظاهَرُوا عَلى إِخْراجِكُمْ ) أي تعاون ( 1) مجمع البيان : ج 9 ص 450. أَنْ تَوَلَّوْهُمْ وَمَنْ يَتَوَلَّهُمْ فَأُولئِكَ هُمُ الظَّالِمُونَ (9) يا أَيُّهَا الَّذِينَ آمَنُوا إِذا جاءَكُمُ الْمُؤْمِناتُ مُهاجِراتٍ فَامْتَحِنُوهُنَّ اللهُ أَعْلَمُ بِإِيمانِهِنَّ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِناتٍ فَلا تَرْجِعُوهُنَّ إِلَى الْكُفَّارِ لا هُنَّ بعضهم مع بعض في تشريدكم من بلادكم ( أَنْ تَوَلَّوْهُمْ ) أي ينهاكم الله عن توليهم واتخاذهم أولياء وهذا بدل اشتمال عن قوله : ( الَّذِينَ قاتَلُوكُمْ ) ( وَمَنْ يَتَوَلَّهُمْ ) أي يتخذهم أولياء وأحباء ( فَأُولئِكَ هُمُ الظَّالِمُونَ ) الذين ظلموا أنفسهم بالعصيان لله والرسول. [11] وبمناسبة الحديث عن موادة الكفار يأتي السياق ليذكر بعض أحكام النساء مما له رابطة بالكلام ( يا أَيُّهَا الَّذِينَ آمَنُوا إِذا جاءَكُمُ الْمُؤْمِناتُ مُهاجِراتٍ ) من دار الكفر إلى دار الإسلام ( فَامْتَحِنُوهُنَ ) أي اختبروهن حتى تعرفوا صدق إيمانهن وهجرتهن. في الصافي عن القمي قال : إذا لحقت امرأة من المشركين بالمسلمين تمتحن بأن تحلف بالله أنه لم يحملها على اللحوق بالمسلمين بغض لزوجها الكافر ولا حب لأحد من المسلمين وإنما حملها على ذلك الإسلام ، فإذا حلفت على ذلك قبل إسلامها (1) . و ( اللهُ أَعْلَمُ بِإِيمانِهِنَ ) منكم فليس عليكم إلا الإيمان والعمل حسب ذلك ( فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِناتٍ ) أي صادقات في إيمانهن من الحلف وسائر العلامات والإمارات ( فَلا تَرْجِعُوهُنَّ إِلَى الْكُفَّارِ ) أي إلى بلاد الكفار ( لا هُنَ ) أي المؤمنات ( 1) تفسير القمي : ج 2 ص 362. حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ وَآتُوهُمْ ما أَنْفَقُوا وَلا جُناحَ عَلَيْكُمْ أَنْ تَنْكِحُوهُنَّ إِذا آتَيْتُمُوهُنَّ أُجُورَهُنَّ وَلا تُمْسِكُوا بِعِصَمِ الْكَوافِرِ ( حِلٌ ) أي حلال ( لَهُمْ ) فإن الكافر لا يحق له مس المسلمة ( وَلا هُمْ يَحِلُّونَ لَهُنَ ) فإنهم يصبحون كالأجانب بالنسبة إلى المؤمنات ( وَآتُوهُمْ ) أي أعطوا الكفار ـ الأزواج ـ أيها المؤمنون ، حين حبستم نساءهم عن الرجوع إليهم ( ما أَنْفَقُوا ) على المرأة من المهر فإن الزوجة تردّ على زوجها صداقها الذي أعطاها ثم يتزوجها المسلم ( وَلا جُناحَ عَلَيْكُمْ ) أي لا حرج عليكم أيها المؤمنون ( أَنْ تَنْكِحُوهُنَ ) فإن إسلامهن أبطل عقدهن السابق بالكفار ـ على تفصيل مذكور في الفقه ـ . ( إِذا آتَيْتُمُوهُنَّ أُجُورَهُنَ ) أي أعطيتم النساء مهورهن ، بمعنى أن الحلّية متوقفة على العقد والمهر ( وَلا تُمْسِكُوا بِعِصَمِ الْكَوافِرِ ) أي لا تعقدوا أيها المسلمون على الكافرة ، فإن الإمساك هو الأخذ ، وعصم جمع عصمة وسمي العقد عصمة لأنه به يعصم كل من الزوجين عن الفجور ، والكوافر جمع كافرة ، وكما لا يجوز الابتداء على عقد الكافرة كذلك لا يجوز البقاء على العقد فيما لو أسلم الرجل ، وبقيت المرأة كافرة ـ على تفصيل مذكور في الفقه (1) ـ وجاءت هذه الجملة بمناسبة نكاح المسلمة بالكافر ، يعني كما لا يجوز نكاح المسلمة للكافر كذلك لا يجوز نكاح المسلم للكافرة ( 1) موسوعة الفقه : ج 65 ، كتاب النكاح جزء 4. وَسْئَلُوا ما أَنْفَقْتُمْ وَلْيَسْئَلُوا ما أَنْفَقُوا ذلِكُمْ حُكْمُ اللهِ يَحْكُمُ بَيْنَكُمْ وَاللهُ عَلِيمٌ حَكِيمٌ (10) وَإِنْ فاتَكُمْ شَيْءٌ مِنْ أَزْواجِكُمْ إِلَى الْكُفَّارِ فَعاقَبْتُمْ ( وَ ) إذا لحقت منكم ـ أيها المسلمون ـ امرأة بدار الكفر ، بأن كفرت وارتدت وذهبت إلى الكفار ( سْئَلُوا ) واطلبوا من الكفار ( ما أَنْفَقْتُمْ ) عليها من المهر ( وَلْيَسْئَلُوا ) أي الكفار ( ما أَنْفَقُوا ) من المهر على امرأة كافرة أسلمت والتحقت بكم ـ لقاعدة التقابل بين الفئتين ـ فهم يطالبون مهر نسائهم إذا أسلمن والتحقن بكم وأنتم تطالبون مهر نسائكم إذا كفرن والتحقن بهم. ( ذلِكُمْ ) « ذا » إشارة إلى ما تقدم من الأحكام و « كم » خطاب للمؤمنين ( حُكْمُ اللهِ ) الذي قرره ( يَحْكُمُ بَيْنَكُمْ ) أيها المسلمون والكافرون ( وَاللهُ عَلِيمٌ ) بالأحكام وما يصلح للبشر ( حَكِيمٌ ) فيما يأمر وينهي فليست هذه الأحكام إلا حسب الصلاح والحكمة ، قالوا وقد كان من بنود صلح الحديبية أن الرجال يردون كل إلى المحل الذي فر منه ، فإذا جاء رجل من الكفار إلى المسلمين ردوه ، وكذا بالعكس ولم يكن ذكر للنساء في بنود الصلح وإذ تم الصلح وكتبوا الكتاب جاءت « سبيعة بنت الحرث » مسلمة إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم فجاء زوجها في طلبها وكان كافرا فقال يا محمد صلى‌الله‌عليه‌وآله‌وسلم اردد علي امرأتي فنزلت هذه الآية (1) .` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَٰتُ مُهَٰجِرَٰتٍ فَٱمْتَحِنُوهُنَّ ٱللَّهُ أَعْلَمُ بِإِيمَٰنِهِنَّ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَٰتٍ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ وَءَاتُوهُم مَّآ أَنفَقُوا۟ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ذَٰلِكُمْ حُكْمُ ٱللَّهِ يَحْكُمُ بَيْنَكُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ", tafsir: `` },
            { text: "وَإِن فَاتَكُمْ شَىْءٌ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ", tafsir: `أيها المؤمنون ( شَيْءٌ مِنْ أَزْواجِكُمْ ) أي أحد من نسائكم ( إِلَى الْكُفَّارِ ) بأن لحقن بهم مرتدات ( فَعاقَبْتُمْ ) أي غزوتم ( 1) بحار الأنوار : ج 20 ص 337. فَآتُوا الَّذِينَ ذَهَبَتْ أَزْواجُهُمْ مِثْلَ ما أَنْفَقُوا وَاتَّقُوا اللهَ الَّذِي أَنْتُمْ بِهِ مُؤْمِنُونَ (11) وأصبتم من الكفار عقبى ـ وهي الغنيمة ـ وامتنع الكافر أن يعطيكم مهر زوجتكم التي لحقت بهم ( فَآتُوا ) أي أعطوا أيها المؤمنون ( الَّذِينَ ذَهَبَتْ أَزْواجُهُمْ ) أي المؤمنين ارتدت زوجاتهم وفرت إلى الكفار ( مِثْلَ ما أَنْفَقُوا ) من المهور عليهن. والحاصل أن الزوجة إذا فرت ولم يقبل الكفار أن يدفعوا مهرها إلى زوجها المسلم أعطى الإمام مهرها لزوجها من الغنيمة التي حصلت من المعاقبة ( وَاتَّقُوا اللهَ ) أي خافوا عقابه فلا تخالفوا أمره بأن تمنعوا الزوج المسلم عن المهر إذا فرت زوجته ولم يبذل الكفار مهرها ( الَّذِي أَنْتُمْ بِهِ مُؤْمِنُونَ ) فإن من مقتضيات الإيمان التقوى. روي في الجوامع أنه لما نزلت الآية المتقدمة أدى المؤمنون ما أمروا به من نفقات المشركين على نسائهم وأبى المشركون أن يردوا شيئا من مهور الكوافر إلى أزواجهن المسلمين فنزلت هذه الآية (1) . قال القمي : وكان سبب ذلك أن عمر بن الخطاب كانت عنده فاطمة بنت أبي أمية بن المغيرة فكرهت الهجرة معه وأقامت مع المشركين فنكحها معاوية بن أبي سيفان فأمر الله رسوله أن يعطي عمر مثل صداقها (2) . و روي عن الصادق والباقر عليهما‌السلام أنهما سئلا ما معنى العقوبة ها هنا ؟ قالا : إن الذي ذهبت امرأته فعاقبت على امرأة أخرى غيرها يعني تزوجها فإذا هو تزوج امرأة أخرى غيرها فعلى الإمام أن ( 1) راجع بحار الأنوار : ج 20 ص 339. ( 2) تفسير القمي : ج 2 ص 363. يا أَيُّهَا النَّبِيُّ إِذا جاءَكَ الْمُؤْمِناتُ يُبايِعْنَكَ عَلى أَنْ لا يُشْرِكْنَ بِاللهِ شَيْئاً وَلا يَسْرِقْنَ وَلا يَزْنِينَ وَلا يَقْتُلْنَ أَوْلادَهُنَّ وَلا يَأْتِينَ بِبُهْتانٍ يَفْتَرِينَهُ يعطي له مهر امرأته الذاهبة (1) . أقول : فعلى هذا فمعنى « عاقبتم » تزوجتم بأخرى عقيبها ، كما أنه لا يبعد أن يكون القيد سواء كان بالمعنى السابق أو هذا المعنى من باب القيد الغالب لا أن له خصوصية فإنّ على الإمام إعطاء المهر للمسلم الفارّة زوجته سواء أراد التزويج أم لا وسواء غنموا أم لا. والله أعلم.` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَٰنٍ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `أي النساء اللائي يردن الإيمان فهو من باب مجاز المشارفة نحو « من قتل قتيلا فله سلبه » ( يُبايِعْنَكَ ) أي يردن بيعتك وقد كان ترتيب بيعة النساء أن يضع الرسول صلى‌الله‌عليه‌وآله‌وسلم يده في ظرف من الماء فيخرجها ثم تأتي النساء فيضعن أيديهن في ذلك ومعنى البيعة أن المبايع يبيع كل شيء له لله والرسول ، كما قال سبحانه ( إِنَّ اللهَ اشْتَرى مِنَ الْمُؤْمِنِينَ أَنْفُسَهُمْ وَأَمْوالَهُمْ ) (2) ( عَلى ) شرط ( أَنْ لا يُشْرِكْنَ بِاللهِ ) بأن يوحدنه ولا يتخذن معه شريكا ( شَيْئاً ) أي أيّ نوع من أنواع الشريك كان ( وَلا يَسْرِقْنَ ) لا من أزواجهن ولا من غير أزواجهن ( وَلا يَزْنِينَ ) بالرجال الأجانب سواء كنّ ذوات بعل أم لا ( وَلا يَقْتُلْنَ أَوْلادَهُنَ ) لا بالإسقاط ولا بالوأد ولا بسائر أقسام القتل ( وَلا يَأْتِينَ بِبُهْتانٍ يَفْتَرِينَهُ ) أي بكذب يكذبنه في مولود يوجد لديهن ( 1) تهذيب الأحكام : ج 6 ص 313. ( 2) التوبة : 111. بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلا يَعْصِينَكَ فِي مَعْرُوفٍ فَبايِعْهُنَّ وَاسْتَغْفِرْ لَهُنَّ اللهَ إ ِنَّ اللهَ غَفُورٌ رَحِيمٌ (12) ( بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَ ) أي لا يلحقن بأزواجهن غير أولادهم بأن يزنين فيلدن من الزنى ثم ينسبنه إلى أزواجهن ! فإن المولود إنما يلد بين الرجلين ويرتضع بين اليدين ، وهذا غير النهي عن الزنى ـ الذي سبق ـ . وقال بعض : إن المرأة في الجاهلية كانت تلتقط المولود ثم تنسبه إلى الزوج فنهين عن ذلك (1) ( وَلا يَعْصِينَكَ ) يا رسول الله ( فِي مَعْرُوفٍ ) قال الإمام الصادق عليه‌السلام : هو ما فرض الله عليهن من الصلاة والزكاة وما أمرهن به من خير (2) ، أقول : وكان الإتيان بقوله : « في معروف » مع أن الرسول لا يأمر إلا بالمعروف ، التنبيه على أن الرسول شأنه الأمر بالمعروف ترغيبا لهن للعمل بأوامره ( فَبايِعْهُنَ ) أي اقبل بيعتهن ولهن الجنة والثواب على مثل هذه البيعة ( وَاسْتَغْفِرْ لَهُنَّ اللهَ ) أي اطلب من الله غفران ذنوبهن السالفات ( إِنَّ اللهَ غَفُورٌ ) يغفر الذنب ( رَحِيمٌ ) يتفضل بالإضافة على الغفران ، بالرحمة والفضل. روي إن النبي صلى‌الله‌عليه‌وآله‌وسلم بايعهن وكان على الصفا ، وكان عمر أسفل منه وهند بنت عتبة زوجة أبي سفيان متنقبة متنكرة مع النساء خوفا من أن يعرفها رسول الله صلى‌الله‌عليه‌وآله‌وسلم ، فقال صلى‌الله‌عليه‌وآله‌وسلم : أبايعكن على أن لا تشركن بالله شيئا ، فقالت هند : إنك لتأخذ علينا أمرا ما رأيناك أخذته على الرجال ، وذلك أنه صلى‌الله‌عليه‌وآله‌وسلم بايع الرجال يؤمئذ على الإسلام والجهاد فقط .. فقال : ولا تسرقن فقالت هند : إن أبا سفيان رجل ممسك وإني ( 1) بحار الأنوار : ج 21 ص 97. ( 2) بحار الأنوار : ج 79 ص 76. يا أَيُّهَا الَّذِينَ آمَنُوا لا تَتَوَلَّوْا قَوْماً غَضِبَ اللهُ عَلَيْهِمْ قَدْ يَئِسُوا مِنَ الْآخِرَةِ كَما يَئِسَ الْكُفَّارُ مِنْ أَصْحابِ الْقُبُورِ (13) أصبت من ماله هناك فلا أدري أ يحل لي أم لا ؟ فقال أبو سفيان : ما أصبت من مالي فيما مضى وفيما غبر فهو لك حلال فضحك رسول الله صلى‌الله‌عليه‌وآله‌وسلم وعرفها. فقال صلى‌الله‌عليه‌وآله‌وسلم : ولا تقتلن أولادكن فقالت هند : ربيناهم صغارا وقتلتموهم كبارا وأنتم وهم أعلم ، وكان ابنها حنظلة بن أبي سفيان قتله علي بن أبي طالب عليه‌السلام يوم بدر ، فضحك عمر حتى استلقى وتبسم النبي صلى‌الله‌عليه‌وآله‌وسلم ولما قال : لا تأتين ببهتان ، فقالت هند : والله إن البهتان قبيح وما تأمرنا إلا بالرشد ومكارم الأخلاق ، ولما قال ولا يعصينك في معروف فقالت هند : ما جلسنا مجلسنا هذا وفي أنفسنا أن نعصيك في كل شيء (1) . [14] وأخيرا يأتي السياق ليعود إلى ما استبدئ به من تحريم موادة الكفار الذي لأجله نزلت السورة ( يا أَيُّهَا الَّذِينَ آمَنُوا لا تَتَوَلَّوْا قَوْماً ) من الكفار ( غَضِبَ اللهُ عَلَيْهِمْ ) ، فقد روي أنها نزلت في بعض فقراء المسلمين كانوا يواصلون اليهود ليصيبوا من ثمارهم ، ومعنى التولي الموادة والمحابة واتخاذهم أولياء ( قَدْ يَئِسُوا مِنَ الْآخِرَةِ ) فإنهم منكرون لها ( كَما يَئِسَ الْكُفَّارُ مِنْ أَصْحابِ الْقُبُورِ ) بأن يرجعوا إلى الدنيا ، فهم والكفار سواء في عدم الاعتقاد بالآخرة ، وان أظهر أولئك الاعتقاد بها كذبا وتدليسا. ( 1) مستدرك الوسائل : ج 14 ص 279. (61)` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْـَٔاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَٰبِ ٱلْقُبُورِ", tafsir: `` }
        ]
    },
    61: { // سورة الصف
        name: "الصف",
        basmalaTafsir: ``,
        verses: [
            { text: "سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `والمراد الأعم من الظرف والمظروف ، وإنما كرر هذه الآية في أول السورة السابقة وهذه السورة تأكيدا وتركيزا في الذهن ، فإن تسبيح الكون ـ سواء كان بالمعنى التكويني أو الإدراكي ـ شيء غريب عن الأذهان يحتاج إلى التركيز والترسيخ ( وَهُوَ الْعَزِيزُ ) الغالب في سلطانه ( الْحَكِيمُ ) الذي يفعل الأشياء حسب الصلاح والحكمة ، وهي وضع كل شيء موضعه. [3] وقد كان قسم من المؤمنين يقولون إذا لقينا العدو لا نفر ونرجع عنهم ، حتى إذا كان يوم أحد فروا فنزلت ( يا أَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ ما لا تَفْعَلُونَ ) ؟ استفهام إنكاري فإن القول بدون الفعل أقبح من السكوت مع عدم الفعل ، كما أن الفعل بدون القول أحسن من الفعل بعد القول ـ إذا لم يكن لتشجيع أو نحو ذلك من العناوين ـ قالوا : الناس في الخير على أربعة أقسام : قائل فاعل ، وقائل غير فاعل ، وغير قائل غير فاعل ، وغير قائل فاعل ، والأحسن الأخير ، والأقبح الثاني والأول خير من الثالث.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ", tafsir: `` },
            { text: "كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ", tafsir: `أي كبر من حيث المقت والغضب عنده سبحانه ( أَنْ تَقُولُوا ما لا تَفْعَلُونَ ) .` },
            { text: "إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِى سَبِيلِهِۦ صَفًّا كَأَنَّهُم بُنْيَٰنٌ مَّرْصُوصٌ", tafsir: `لإعلاء كلمته وسبيل رضوانه صَفًّا كَأَنَّهُمْ بُنْيانٌ مَرْصُوصٌ (4) وَإِذْ قالَ مُوسى لِقَوْمِهِ يا قَوْمِ لِمَ تُؤْذُونَنِي وَقَدْ تَعْلَمُونَ أَنِّي رَسُولُ اللهِ إِلَيْكُمْ فَلَمَّا زاغُوا أَزاغَ اللهُ قُلُوبَهُمْ في حال كونهم مصطفين ( صَفًّا ) بلا تبعثر أو تفرق ( كَأَنَّهُمْ بُنْيانٌ مَرْصُوصٌ ) كأنهم في شدة ثباتهم بناء قد رصّ ، أي أحكم بناؤه يقال رصصت البناء أي أحكمته. روي إن المسلمين قالوا : لو علمنا أحب الأعمال إلى الله تعالى لبذلنا فيه أموالنا وأنفسنا فأنزل الله ( إِنَّ اللهَ يُحِبُّ الَّذِينَ ) الآية فلما كان يوم أحد وتولوا أنزل الله سبحانه « لم تقولون » ؟ [6] ثم جاء السياق ليحذر المسلمين أن يكونوا كأصحاب موسى عليه‌السلام يؤذونه بعد أن علموا أنه نبي من عند الله تعالى ، فإن ترك القتال إيذاء للرسول ومخالفة لأمره ( وَ ) اذكر يا رسول الله ( إِذْ قالَ مُوسى لِقَوْمِهِ ) بني إسرائيل الذين آمنوا به ( يا قَوْمِ لِمَ تُؤْذُونَنِي ) بأفعالكم كعبادة العجل ، وأقوالكم كقولهم ( فَاذْهَبْ أَنْتَ وَرَبُّكَ فَقاتِلا ) (1) ( وَقَدْ تَعْلَمُونَ أَنِّي رَسُولُ اللهِ ) « قد » للتحقيق ، وإن كان الأكثر في فعل المضارع أن يكون للتقريب ، ولعل النكتة فيه أن احتمال كونه رسولا كاف في كفهم عن أذاه ( إِلَيْكُمْ ) بعثني إليكم لهدايتكم. لكن القوم تمادوا في إيذائه عليه‌السلام ( فَلَمَّا زاغُوا ) أي مالوا عن الحق بالاستمرار في أذاه كما هو طبيعة اليهود ( أَزاغَ اللهُ قُلُوبَهُمْ ) أي تركهم وشأنهم ومنع عنهم الألطاف الخفية حتى مالت قلوبهم ، ونسبة ( 1) المائدة : 25. وَاللهُ لا يَهْدِي الْقَوْمَ الْفاسِقِينَ (5) وَإِذْ قالَ عِيسَى ابْنُ مَرْيَمَ يا بَنِي إِسْرائِيلَ إِنِّي رَسُولُ اللهِ إِلَيْكُمْ مُصَدِّقاً لِما بَيْنَ يَدَيَّ مِنَ التَّوْراةِ وَمُبَشِّراً بِرَسُولٍ يَأْتِي مِنْ بَعْدِي اسْمُهُ أَحْمَدُ فَلَمَّا جاءَهُمْ بِالْبَيِّناتِ الزيغ إليه سبحانه ، لأنه إذا ترك الإنسان جذبته الأهواء الموجبة للزيغ ( وَاللهُ لا يَهْدِي الْقَوْمَ الْفاسِقِينَ ) فمن خرج عن طاعة الله بعد الدليل والبرهان تركه سبحانه وشأنه ولم يلطف به الألطاف الخفية. [7] وهكذا فعل اليهود بعيسى بن مريم عليه‌السلام آذوه بعد ما جاءهم بالبينات ( وَ ) اذكر يا رسول الله ( إِذْ قالَ عِيسَى ابْنُ مَرْيَمَ ) والإصرار في القرآن على إضافة عيسى بمريم عليه‌السلام لنفي كونه ابن الله ( يا بَنِي إِسْرائِيلَ ) والمراد بهم اليهود ( إِنِّي رَسُولُ اللهِ إِلَيْكُمْ ) بعثني لهدايتكم وإرشادكم في حال كوني ( مُصَدِّقاً لِما بَيْنَ يَدَيَ ) أي ما تقدمني ، فإن الشيء الذي أمام الإنسان هو بين يديه ـ مجازا ـ ( مِنَ التَّوْراةِ ) التي جاء بها موسى عليه‌السلام . ( وَمُبَشِّراً بِرَسُولٍ ) أي أبشركم برسول من عند الله تعالى ( يَأْتِي مِنْ بَعْدِي اسْمُهُ أَحْمَدُ ) يعني نبينا محمد صلى‌الله‌عليه‌وآله‌وسلم ـ وقد ذكر الشيخ محمد صادق فخر الإسلام ، في كتابه أنيس الأعلام ـ وهو ممن كان مسيحيا فأسلم ـ قصة طويلة حول هذا الأمر وأن اسم الرسول « فارقليطا » المفسر بأحمد وهي في كتابهم ـ وهذه هي عادة الأنبياء عليهم‌السلام يصدقون السابقين ويبشرون باللاحقين لأنهم أخوة من عند الله لبيان منهج واحد ، وإنما الفروق في المزايا والخصوصيات التابعة للظروف ( فَلَمَّا جاءَهُمْ ) عيسى ، أو لما جاءهم الرسول ـ أحمد ـ ( بِالْبَيِّناتِ ) أي قالُوا هذا سِحْرٌ مُبِينٌ (6) وَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ الْكَذِبَ وَهُوَ يُدْعى إِلَى الْإِسْلامِ وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ (7) يُرِيدُونَ لِيُطْفِؤُا نُورَ اللهِ بِأَفْواهِهِمْ وَاللهُ مُتِمُّ نُورِهِ الأدلة الواضحات ( قالُوا هذا سِحْرٌ مُبِينٌ ) أي سحر ظاهر ولم يؤمنوا ، فإن كان الضمير راجعا إلى عيسى ، كان ردفا لتكذيب اليهود لموسى ، وإن كان راجعا إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم كانت الآيات في صدد بيان الرسالات الثلاث ، وإن أهل الملتين السابقتين كيف استقبلوا الرسول صلى‌الله‌عليه‌وآله‌وسلم المبشر به لديهم.` },
            { text: "وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ", tafsir: `` },
            { text: "وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَٰتِ قَالُوا۟ هَٰذَا سِحْرٌ مُّبِينٌ", tafsir: `` },
            { text: "وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَٰمِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ", tafsir: `أي أيّ شخص أكثر ظلما ( مِمَّنِ افْتَرى عَلَى اللهِ الْكَذِبَ ) أي اختلق الكذب على الله ، وقال لكلامه إنه سحر ولرسوله إنه ساحر كاذب ، ( وَهُوَ يُدْعى إِلَى الْإِسْلامِ ) الذي فيه سعادته في الدنيا والآخرة ( وَاللهُ لا يَهْدِي ) بالألطاف الخفية ( الْقَوْمَ الظَّالِمِينَ ) الذين ظلموا أنفسهم بالكفر والعناد بعد ما رأوا النور والهدى ، ودلهم على الطريق فلم يسلكوه.` },
            { text: "يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ", tafsir: `هؤلاء الكفار المعاصرون لك يا رسول الله ( لِيُطْفِؤُا نُورَ اللهِ ) وهو رسوله ومنهاجه ( بِأَفْواهِهِمْ ) وإنما سمي نورا لأنه ينير دروب الحياة المظلمة بمناهج تسبب السعادة والوصول إلى الهدف ، كمن معه المصباح في الليلة المظلمة حيث لا يصطدم بشيء بل يسلك السبيل حتى يصل إلى المطلوب ، وإنما قال « بأفواههم » لأنهم ظنوا أنهم يتمكنون من إطفاء نور الإسلام ، بالتكذيب والتهريج. ( وَاللهُ مُتِمُّ نُورِهِ ) أي مظهر دينه ، فإن النور إذا أطفئ لم يتم وَلَوْ كَرِهَ الْكافِرُونَ (8) هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَلَوْ كَرِهَ الْمُشْرِكُونَ (9) يا أَيُّهَا الَّذِينَ آمَنُوا هَلْ أَدُلُّكُمْ عَلى تِجارَةٍ تُنْجِيكُمْ مِنْ عَذابٍ أَلِيمٍ (10) امتداده في الزمان ، أمّا إذا لم يطفأ استمر وامتد وتم ( وَلَوْ كَرِهَ الْكافِرُونَ ) من بقاء نور الله وإضاءته للعالم.` },
            { text: "هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ", tafsir: `الله سبحانه ( الَّذِي أَرْسَلَ رَسُولَهُ ) محمدا صلى‌الله‌عليه‌وآله‌وسلم ( بِالْهُدى ) أي مع الهداية للبشرية إلى السعادة الأبدية ( وَ ) ب ( دِينِ الْحَقِ ) وهو دين الإسلام ( لِيُظْهِرَهُ ) أي أن الإرسال كان لأجل إظهار هذا الدين ( عَلَى الدِّينِ كُلِّهِ ) أي على كل الأديان ، فإن « الدين » جنس ولذا جيء له ب « كله » فإن الإسلام يغلب الأديان كلها على نحوين : الأول بالحجة والدليل ، وهذا موجود منذ زمن الرسول صلى‌الله‌عليه‌وآله‌وسلم ، والثاني بالغلبة والسيطرة وهذه تكون في زمن الإمام الحجة عليه‌السلام . فقد سئل الإمام أمير المؤمنين عليه‌السلام عن هذه الآية وأنه هل ظهر الإسلام ؟ قال عليه‌السلام : كلا فو الذي نفسي بيده حتى لا تبقى قرية إلا وينادى فيها بشهادة أن لا إله إلا الله بكرة وعشيا (1) ( وَلَوْ كَرِهَ الْمُشْرِكُونَ ) الذين أشركوا بالله ، فإنه يعلو على رغم أنوفهم.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَٰرَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ", tafsir: `إنما خص المؤمنين بالخطاب ، مع أنه أعم ، لأنهم المنتفعون بالخطاب العاملون به دون سواهم ( هَلْ أَدُلُّكُمْ ) أي هل تريدون أن أهديكم وأرشدكم ( عَلى تِجارَةٍ تُنْجِيكُمْ مِنْ عَذابٍ أَلِيمٍ ) على نحو الاستفهام الطلبي. ( 1) تأويل الآيات : ص 663. تُؤْمِنُونَ بِاللهِ وَرَسُولِهِ وَتُجاهِدُونَ فِي سَبِيلِ اللهِ بِأَمْوالِكُمْ وَأَنْفُسِكُمْ ذلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ (11) يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ وَمَساكِنَ طَيِّبَةً فِي جَنَّاتِ عَدْنٍ [12] ثم بين تلك التجارة ، التي لها أربح الأثمان ، وهل شيء أنفع من نجاة الإنسان من عذاب مؤلم موجع ؟ ( تُؤْمِنُونَ بِاللهِ ) بأن تعتقدوا به إلها واحدا ( وَرَسُولِهِ ) بأن تصدقوه فيما جاء به ، والمراد إيمانا باقيا راسخا ـ فلا ينافي ذلك كونهم مؤمنين ، كقوله ( يا أَيُّهَا الَّذِينَ آمَنُوا آمِنُوا ) (1) ـ ( وَتُجاهِدُونَ فِي سَبِيلِ اللهِ ) أي تتبعون أنفسكم بالمشاق التي منها الحرب لأجل إعلاء كلمة الله ( بِأَمْوالِكُمْ ) بأن تبذلوها لأجله تعالى ( وَأَنْفُسِكُمْ ) بأن ترخصوها في أوامره ، حتى إذا استلزمت إزهاق أنفسكم وقتلكم في سبيله ( ذلِكُمْ ) « ذا » إشارة و « كم » خطاب ، أي ما ذكر من الإيمان والجهاد ـ باعتبار كل واحد ـ ( خَيْرٌ لَكُمْ ) من الشرك الذي مصيره النار والعقاب ( إِنْ كُنْتُمْ تَعْلَمُونَ ) والمعنى إن كنتم عالمين لعلمتم أن الإيمان والجهاد خير وأنفع من الكفر والكسالة. [13] وإذا فعلتم ذلك ( يَغْفِرْ ) الله ( لَكُمْ ذُنُوبَكُمْ ) السالفة ( وَيُدْخِلْكُمْ ) الله تعالى ( جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا ) أي من تحت قصورها وأشجارها ( الْأَنْهارُ ) من عسل وماء ولبن وخمر ( وَ ) يدخلكم في تلك الجنات ( مَساكِنَ طَيِّبَةً ) جمع مسكن وهو المنزل ، سمي بذلك لأنه محل سكون الإنسان ( فِي جَنَّاتِ عَدْنٍ ) يقال عدن بالمكان إذا أقام فيه ، أي ( 1) النساء : 137. ذلِكَ الْفَوْزُ الْعَظِيمُ (12) وَأُخْرى تُحِبُّونَها نَصْرٌ مِنَ اللهِ وَفَتْحٌ قَرِيبٌ وَبَشِّرِ الْمُؤْمِنِينَ (13) يا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا أَنْصارَ اللهِ كَما قالَ عِيسَى ابْنُ مَرْيَمَ لِلْحَوارِيِّينَ مَنْ أَنْصارِي إِلَى اللهِ قالَ الْحَوارِيُّونَ نَحْنُ أَنْصارُ اللهِ في جنات أنتم دائمون فيها خالدين لا خروج لكم عنها ( ذلِكَ ) الغفران للذنب والدخول في الجنات ( الْفَوْزُ ) والظفر بالمطلوب والسعادة ( الْعَظِيمُ ) الذي ليس فوقه سعادة وفلاح.` },
            { text: "تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ", tafsir: `` },
            { text: "يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَمَسَٰكِنَ طَيِّبَةً فِى جَنَّٰتِ عَدْنٍ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `` },
            { text: "وَأُخْرَىٰ تُحِبُّونَهَا نَصْرٌ مِّنَ ٱللَّهِ وَفَتْحٌ قَرِيبٌ وَبَشِّرِ ٱلْمُؤْمِنِينَ", tafsir: `لكم مضافا إلى نعمة الفوز بالجنان ، نعمة ( أُخْرى ) إذا آمنتم وجاهدتم ( تُحِبُّونَها ) وهي نعمة دنيوية ( نَصْرٌ ) لكم على الكفار ( مِنَ ) طرف ( اللهِ ) سبحانه ، لأنه ينصركم على الأعداء ، وإن كانت قواكم المادية أقل منهم ( وَفَتْحٌ قَرِيبٌ ) لبلادهم ، وقد كان كما أقام سبحانه فقد فتحوا مكة وفارس والروم وكثير من أماكن المشركين والكفار في مدة ووجيزة ( وَبَشِّرِ ) يا رسول الله ( الْمُؤْمِنِينَ ) بهذين الثوابين ، إن صدقوا في الإيمان وقاموا بواجب الجهاد.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّـۧنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ فَـَٔامَنَت طَّآئِفَةٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَٰهِرِينَ", tafsir: `` }
        ]
    },
    62: { // سورة الجمعة
        name: "الجمعة",
        basmalaTafsir: ``,
        verses: [
            { text: "يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ", tafsir: `أي ينزه الله من النقائص ، تنزيها إما تكوينيا ، لأن في كل شيء له آية دالة على أنه خالق عالم قدير ، وإما بلسان تفقهه ( ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) السماء وما فيها ، والأرض وما فيها فإن الظرف قد يطلق على الإثنين ، كما أن المظروف قد يطلق على الإثنين ( الْمَلِكِ ) السلطان على الكون بقول مطلق ، فإن سلطة ما عداه تعالى مجازية ( الْقُدُّوسِ ) المنزه عن كل نقص ، من قدس بمعنى تنزه ( الْعَزِيزِ ) الغالب في سلطانه ( الْحَكِيمِ ) الذي يفعل الأشياء بالحكمة والصلاح.` },
            { text: "هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّـۧنَ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍ مُّبِينٍ", tafsir: `الله تعالى ( الَّذِي بَعَثَ ) أي أرسل ( فِي الْأُمِّيِّينَ ) الأمي منسوب إلى الأم والمراد بهم العرب ، سموا بذلك إما لأنهم من أهل « أم القرى » أي مكة المكرمة ـ المسماة بذلك لأن القرى دحيت من تحتها ـ وإما لأن الغالب منهم لم يكونوا يعرفون القراءة والكتابة فهم ـ في جهلهم ـ كالذي خلق من الأم لا يعرف شيئا ، والبعث في الأميين لا يلازم أن يكون لهم وحدهم ، حتى تدل الآية على خصوص نبوته صلى‌الله‌عليه‌وآله‌وسلم ( رَسُولاً ) لأجل هدايتهم ( مِنْهُمْ ) أي من أنفسهم ومن أهل بلدهم. ( يَتْلُوا ) أي يقرأ ( عَلَيْهِمْ ) أي على أولئك الأميين ( آياتِهِ ) أدلّته ، أو آيات القرآن ( وَيُزَكِّيهِمْ ) أي يطهرهم تطهيرا علميا ، فإن المعلم الرقيب يطهر تلاميذه من أدران القلوب والجوارح بحفظهم عن الرذائل وَيُعَلِّمُهُمُ الْكِتابَ وَالْحِكْمَةَ وَإِنْ كانُوا مِنْ قَبْلُ لَفِي ضَلالٍ مُبِينٍ (2) وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ وَهُوَ الْعَزِيزُ الْحَكِيمُ (3) ذلِكَ فَضْلُ اللهِ يُؤْتِيهِ مَنْ يَشاءُ وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ (4) والأعمال المنكرة ( وَيُعَلِّمُهُمُ الْكِتابَ ) أحكامه وشرائعه ( وَالْحِكْمَةَ ) بأن يعرفوا وضع الأشياء مواضعها ، فإن الحكمة هي وضع الشيء موضعه ( وَإِنْ كانُوا ) هؤلاء الأميون ( مِنْ قَبْلُ ) أي قبل أن يأتيهم الرسول ( لَفِي ضَلالٍ مُبِينٍ ) أي في انحراف ظاهر ، فلا عقائد صحيحة ولا أعمال صالحة ولا عادات طيبة ، ولا أخلاق فاضلة ، يعني أنه يوصلهم إلى أرقى مراقي الكمال ، وإن كانوا قبل ذلك في أبعد متاهات الضلالة.` },
            { text: "وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `يعلّم ( آخَرِينَ مِنْهُمْ ) أي من أولئك الأميين ، ممن يأتي بعدهم إلى يوم القيامة ، وكونهم منهم إما باعتبار أنهم من نسلهم أو باعتبار أنهم بالإيمان يكونون من جنس أولئك ( لَمَّا يَلْحَقُوا بِهِمْ ) « لمّا » لما لم يقع وينتظر وقوعه ، أي لم يلحقوا ـ بعد ـ بهم ، مع أنه ينتظر لحوقهم ( وَهُوَ الْعَزِيزُ ) الغالب في سلطانه فيتمكن من الهداية للآخرين ( الْحَكِيمُ ) الذي يضع الأشياء مواضعها.` },
            { text: "ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ", tafsir: `أي الإرسال ، بالنسبة إلى المرسل بأن جعله نبيا ، أو بالنسبة إلى المرسل إليهم بأن شرفهم بأن هداهم ( فَضْلُ اللهِ ) لطفه ورحمته ( يُؤْتِيهِ ) أي يعطيه ( مَنْ يَشاءُ ) من عباده لكن المعلوم أن الله لا يعطي شيئا إلا حسب الحكمة ، بمن كان صالحا للإعطاء ، ( وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ ) الذي فضله أعظم من فضل كل ـ ذي فضل ، وإعطاء كل معطي. مَثَلُ الَّذِينَ حُمِّلُوا التَّوْراةَ ثُمَّ لَمْ يَحْمِلُوها كَمَثَلِ الْحِمارِ يَحْمِلُ أَسْفاراً بِئْسَ مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآياتِ اللهِ وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ (5) قُلْ يا أَيُّهَا الَّذِينَ هادُوا إِنْ [6] ثم نبّه السياق المسلمين بوجوب التمسك بالشريعة حتى لا يكونوا كاليهود الذين تركوا العمل بالتوراة ، بعد ما تمسكوا بها في زمن موسى عليه‌السلام ( مَثَلُ الَّذِينَ حُمِّلُوا التَّوْراةَ ) أي حمّلهم الله التوراة ، وكأن الوجه في التعبير ب « حملوا » إفادة أنهم إنما تمسكوا بها بكل صعوبة وتحميل لا بالطوع والرغبة ( ثُمَّ لَمْ يَحْمِلُوها ) بأن تركوا العمل بها باختيار ، ولذا جاء الفعل هنا من باب المجرد ، والمراد ب « لم يحملوها » رفضوها وتركوا أحكامها ( كَمَثَلِ الْحِمارِ يَحْمِلُ أَسْفاراً ) جمع سفر وهو الكتاب ، والحمار الذي يحمل الكتب على ظهره لا يستفيد منها ، واليهود مثل ذلك فإنهم مع كون التوراة بين أظهرهم لا يستفيدون منها ولا يعملون بأحكامها فمن تمسك بالقرآن ظاهرا ولم يعمل به كان مثله كذلك ، ( بِئْسَ ) المثل ( مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآياتِ اللهِ ) والمراد بهم اليهود الذين كذبوا بالتوراة ـ تكذيبا عمليا ـ أو كذبوا بآيات الله في القرآن ، والمعنى بئس القوم قوم هذا مثلهم ، فإن المثل السيئ لا يكون إلا للشخص السيئ ، ( وَاللهُ لا يَهْدِي ) بالألطاف الخفية ( الْقَوْمَ الظَّالِمِينَ ) الذين ظلموا أنفسهم بالكفر والعصيان ، بعد أن هداهم إلى الطريق فلم يسلكوه. [7] وقد كان اليهود يزعمون أنهم أولياء الله ـ بعد تركهم العمل بالتوراة ـ ويأتي السياق ليفند زعمهم هذا ( قُلْ ) يا رسول الله لهؤلاء اليهود ( يا أَيُّهَا الَّذِينَ هادُوا ) أي سمّوا يهودا ، وتهودوا ( إِنْ زَعَمْتُمْ أَنَّكُمْ أَوْلِياءُ لِلَّهِ مِنْ دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِنْ كُنْتُمْ صادِقِينَ (6) وَلا يَتَمَنَّوْنَهُ أَبَداً بِما قَدَّمَتْ أَيْدِيهِمْ وَاللهُ عَلِيمٌ بِالظَّالِمِينَ (7) قُلْ إِنَّ الْمَوْتَ الَّذِي تَفِرُّونَ مِنْهُ فَإِنَّهُ مُلاقِيكُمْ ثُمَّ تُرَدُّونَ إِلى عالِمِ الْغَيْبِ وَالشَّهادَةِ زَعَمْتُمْ أَنَّكُمْ أَوْلِياءُ لِلَّهِ ) وأنكم شعب الله المختار ( مِنْ دُونِ النَّاسِ ) وأن سائر الناس لا يحبهم الله ، وليسوا بأولياء الله ( فَتَمَنَّوُا الْمَوْتَ إِنْ كُنْتُمْ صادِقِينَ ) في زعمكم ، فإن الولي لا يخاف من الموت ، إذ يعلم بعلو حاله هناك.` },
            { text: "مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "قُلْ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `` },
            { text: "وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ", tafsir: `أي لا يتمنى اليهود الموت ( أَبَداً ) أي إلى الأبد بسبب ما عملوا من كفرهم وعصيانهم وأن أحوالهم في الآخرة سيئة من ما ( قَدَّمَتْ أَيْدِيهِمْ ) ونسبة التقديم إلى اليد باعتبار أن اليد هي الأكثر عملا ، من باب علاقة الجزء والكل ( وَاللهُ عَلِيمٌ بِالظَّالِمِينَ ) عالم بأحوالهم وسيجازيهم على ظلمهم ، وهذا تهديد لليهود. [9] وهل ينفع عدم تمنيهم الموت وفرارهم منه ؟ ( قُلْ ) يا رسول الله لهم ( إِنَّ الْمَوْتَ الَّذِي تَفِرُّونَ مِنْهُ ) بتوفير أسباب الصحة لأنفسكم ، وعدم حضوركم في مواضع الخطر خوفا من الموت ( فَإِنَّهُ مُلاقِيكُمْ ) يلقاكم وينزل بكم لا محالة ( ثُمَ ) بعد الموت ( تُرَدُّونَ ) أي ترجعون ، فإن الإنسان حيث صدر عن إرادة الله سبحانه ، كان ذهابه إلى حسابه وجزائه ، شبيها بالرد والرجوع إليه ( إِلى عالِمِ الْغَيْبِ ) أي ما غاب عن الحواس ( وَالشَّهادَةِ ) أي ما ظهر للحواس وشهدها ، أي حضرها الشخص ، والمراد أنه تعالى يعلم السر والعلانية فَيُنَبِّئُكُمْ بِما كُنْتُمْ تَعْمَلُونَ (8) يا أَيُّهَا الَّذِينَ آمَنُوا إِذا نُودِيَ لِلصَّلاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلى ذِكْرِ اللهِ ( فَيُنَبِّئُكُمْ ) أي يخبركم ـ إخبار الذي يريد الجزاء ـ ( بِما كُنْتُمْ تَعْمَلُونَ ) من الأعمال الحسنة أو القبيحة. [10] وإذا تبين لزوم العمل بالشريعة حتى لا يكون المسلم ، كمثل اليهود في تركهم العمل بالتوراة ، جاء السياق ليبين شريعة عظيمة هي صلاة الجمعة ، وهذه الصلاة واجبة في زمن الحضور ، أما زمن الغيبة فلعلمائنا فيها خلاف ، والذي استظهرته أن وجوبها خاص بالإمام أو مأذونه في زمان بسط يد الإمام ، ولذا لم يرد قيام الأئمة من بعد الإمام الحسين بها ، ولم يكن ذلك لأجل التقية ، وهذا هو السر في اشتهار تركها بين فقهائنا ( يا أَيُّهَا الَّذِينَ آمَنُوا إِذا نُودِيَ لِلصَّلاةِ ) وقد كان الرسول صلى‌الله‌عليه‌وآله‌وسلم إذا جلس على المنبر لخطبة الجمعة أذّن بلال على باب المسجد ، وكذا جرى أبو بكر وعمر بعده حتى جاء عثمان ، فكان يؤذن على سطح داره أولا ثم إذا جلس على المنبر أذن ثانيا ـ وهذا هو الأذان الثالث الذي قالوا عنه بأنه بدعة ، وكونه ثالثا باعتبار الأذان الإعلامي ، والأذان على المنبر ، المشروعين ـ أما الأذان على سطح الدار فهو شيء لم يكن في الإسلام ( مِنْ يَوْمِ الْجُمُعَةِ ) أي بعض يوم الجمعة ، وهو لصلاة الجمعة ، وسمي جمعة لاجتماع الناس فيها للصلاة ، وقد كان هذا اليوم عيدا قبل الإسلام ثم قرره الإسلام ، كما أن النيروز كان عيدا قبل الإسلام ثم قرره الإسلام. ( فَاسْعَوْا ) السعي هو المضي بسرعة وعجلة ( إِلى ذِكْرِ اللهِ ) أي وَذَرُوا الْبَيْعَ ذلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ (9) فَإِذا قُضِيَتِ الصَّلاةُ فَانْتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِنْ فَضْلِ اللهِ وَاذْكُرُوا اللهَ كَثِيراً لَعَلَّكُمْ تُفْلِحُونَ (10) وَإِذا رَأَوْا الصلاة الجمعة ( وَذَرُوا الْبَيْعَ ) أي دعوا المعاملة ، والظاهر أن « البيع » من باب المثال الغالب ، وإلا فالمراد كل عمل ينافي الذهاب إلى الصلاة ( ذلِكُمْ ) أي السعي إلى الذكر ، وترك المعاملة ( خَيْرٌ لَكُمْ ) أيها المؤمنون في دينكم ودنياكم ( إِنْ كُنْتُمْ تَعْلَمُونَ ) أي إن علمتم الأشياء لعلمتم أن السعي خير لكم.` },
            { text: "قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ", tafsir: `` },
            { text: "فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ", tafsir: `أي أديت صلاة الجمعة ( فَانْتَشِرُوا ) أي تفرقوا أيها المؤمنون ( فِي الْأَرْضِ ) بأن يذهب كل إنسان إلى عمله الموجب للانتشار والتفرق ( وَابْتَغُوا ) أي اطلبوا بالكسب وما أشبه ( مِنْ فَضْلِ اللهِ ) رزقه ولطفه ، وهذا أمر للإباحة ، لأنه بعد الحظر ، نحو قوله ( وَإِذا حَلَلْتُمْ فَاصْطادُوا ) (1) ( وَاذْكُرُوا اللهَ كَثِيراً ) بأن تكونوا متذكرين له لسانا وقلبا ، حال الابتغاء وغيره ، فإنه مجلى القلوب عن صدأ الغفلة والمعاصي ( لَعَلَّكُمْ تُفْلِحُونَ ) أي لكي تفوزوا برضاه وإحسانه.` },
            { text: "وَإِذَا رَأَوْا۟ تِجَٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًا قُلْ مَا عِندَ ٱللَّهِ خَيْرٌ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَٰرَةِ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ", tafsir: `` }
        ]
    },
    63: { // سورة المنافقون
        name: "المنافقون",
        basmalaTafsir: ``,
        verses: [
            { text: "إِذَا جَآءَكَ ٱلْمُنَٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَٰفِقِينَ لَكَٰذِبُونَ", tafsir: `يا رسول الله ( الْمُنافِقُونَ ) والمراد به عبد الله بن أبيّ ، وقد تقدم أن الجمع قد يستعمل بمعنى الجنس ، ويراد به الفرد ، وإنما يعبر بالجمع لإفادة أن من هذا وصفه فحكمه حكم ذلك الفرد الصادر منه الفعل كما أن الفرد قد يأتي بمعنى الجنس ، حيث تسلخ منه الفردية ، وتبقى الجنسية التي في ضمن الفرد ، والمنافق هو الذي يبطن الكفر ويظهر الإسلام ( قالُوا ) في محضرك ( نَشْهَدُ إِنَّكَ لَرَسُولُ اللهِ ) بأن هذا هو اعتقادنا القلبي ، لا إظهارنا اللفظي فقط ( وَاللهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ ) وهذه جملة جاء بها القرآن تمهيدا للجملة التالية ، لئلا تنصرف إلى إنكار الله سبحانه رسالته حيث يكذب المنافقين ( وَاللهُ يَشْهَدُ إِنَّ الْمُنافِقِينَ لَكاذِبُونَ ) في ادعائهم أنهم يعتقدون برسالة الرسول من أعماق قلوبهم ، فإنهم إنما آمنوا باللسان وقلبهم باق على الكفر والجحود.` },
            { text: "ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `أي هؤلاء المنافقون ( أَيْمانَهُمْ ) جمع يمين وهي القسم أي حلفهم ( جُنَّةً ) أي وقاية يتسترون بها حتى لا يصيبهم أذى من الرسول والمسلمين ( فَصَدُّوا ) أي منعوا بسبب حفظ أنفسهم على الكفر باطنا ـ بالحلف الكاذب ـ ( عَنْ سَبِيلِ اللهِ ) أي طريق دينه وثوابه لأنهم بنفاقهم يحفظون أنفسهم في زمرة المسلمين ، ثم يشاغبون خفية ، ويمنعون الناس عن الإيمان الصحيح ( إِنَّهُمْ ) أي المنافقين ( ساءَ ما كانُوا يَعْمَلُونَ (2) ذلِكَ بِأَنَّهُمْ آمَنُوا ثُمَّ كَفَرُوا فَطُبِعَ عَلى قُلُوبِهِمْ فَهُمْ لا يَفْقَهُونَ (3) وَإِذا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسامُهُمْ وَإِنْ يَقُولُوا تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبٌ مُسَنَّدَةٌ يَعْمَلُونَ ) أي بئس العمل عملهم حيث يظهرون الإيمان ويبطنون الكفر صدا عن سبيل الله.` },
            { text: "ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ", tafsir: `النفاق إنما كان بسبب أنهم ( آمَنُوا ) بألسنتهم ( ثُمَّ كَفَرُوا ) بقلوبهم ، فإن المنحرف الطبع إذا رأى خيرا أسرع إليه مخلصا وإذا رأى التصادم مع مصالحه يبقى في ظاهر الموافقة ـ حزنا ـ ويتراجع في الباطن ترجيحا لمصالحه ( فَطُبِعَ عَلى قُلُوبِهِمْ ) إذ تمرنوا على الكفر والتمادي في صفة يوجب تطبع النفس بها إذ تكون ملكة للمتمادي ، والطابع هو الله سبحانه ، الذي خلق النفس البشرية هكذا ، وإن كان الطبع بسبب نفاقهم ، والمراد بالقلوب الأنفس ( فَهُمْ لا يَفْقَهُونَ ) أي لا يفهمون حقيقة الإيمان والتقوى لأن نفوسهم انحرفت ، وإذا انحرفت النفس رأى الجميل قبيحا والقبيح جميلا.` },
            { text: "وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ قَٰتَلَهُمُ ٱللَّهُ أَنَّىٰ يُؤْفَكُونَ", tafsir: `أي نظرت إليهم يا رسول الله أو أيها الرائي ( تُعْجِبُكَ أَجْسامُهُمْ ) بحسن منظرهم وتمام خلقتهم وجمال صورهم ( وَإِنْ يَقُولُوا ) أي يتكلموا في أي شأن من الشؤون ( تَسْمَعْ لِقَوْلِهِمْ ) أي أصغيت إلى كلامهم لجميل بيانهم وفصاحة منطقهم ، فهم مع حسن المنظر وعذوبة البيان ( كَأَنَّهُمْ خُشُبٌ مُسَنَّدَةٌ ) فارغون عن الصفات الحسنة والفضائل ، كالخشبة الفارغة التي لا تتمكن أن تقف بنفسها فتستند لحائط ونحوه لتقف وتستقيم. يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ هُمُ الْعَدُوُّ فَاحْذَرْهُمْ قاتَلَهُمُ اللهُ أَنَّى يُؤْفَكُونَ (4) وَإِذا قِيلَ لَهُمْ تَعالَوْا يَسْتَغْفِرْ لَكُمْ رَسُولُ اللهِ لَوَّوْا رُؤُسَهُمْ فالخشبة التي أكلت جوفها الأرضة ظاهرها جميل وباطنها فارغ لا تتمكن أن تقف هي لركاكتها وهؤلاء كذلك لهم ظاهر من غير باطن ( يَحْسَبُونَ كُلَّ صَيْحَةٍ ) وكل نازلة ( عَلَيْهِمْ ) لجبنهم وفراغ قلوبهم عن فضيلة الإيمان ، فإن المؤمن ثابت القلب رابط الجأش أما المنافق فإنه خائف دائما أن يظهر باطنه فيفضح ، ولذا كلما حدث شيء خاف وجبن أن يقع فيه ويفضح باطنه ، والفاجعة والنازلة تسمى صيحة لارتفاع الصياح فيها من باب علاقة السبب والمسبب ( هُمُ الْعَدُوُّ ) أي أن هؤلاء المنافقين هم أعداؤك الوحيدون يا رسول الله الكاملون في العداوة إذ الكفار لظهورهم يؤمن شرهم ، أما المنافق فهو يخفى في الجماعة المؤمنة بإظهار الإيمان حيث لا يرى ولا يعرف حتى يفسد ويسبب المشاكل. ( فَاحْذَرْهُمْ ) يا رسول الله عن أن يختلطوا بالمسلمين ويطلعوا على أسرارهم ، لأنهم عرفوا بمناطق العزة ونقاط الضعف ، فهم أقدر من العدو الخارج على الإفساد والمؤامرة ( قاتَلَهُمُ اللهُ ) دعاء عليهم بأن يقتلهم الله ليستريح المسلمون من شرهم ( أَنَّى يُؤْفَكُونَ ) أي كيف يصرفون عن الحق مع الأدلة الواضحة ؟` },
            { text: "وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ", tafsir: `أي هلموا وأتوا ( يَسْتَغْفِرْ لَكُمْ رَسُولُ اللهِ ) أي يطلب لكم غفران الله لما صدر منكم من الذنب ( لَوَّوْا رُؤُسَهُمْ ) أي وَرَأَيْتَهُمْ يَصُدّ ُونَ وَهُمْ مُسْتَكْبِرُونَ (5) سَواءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَنْ يَغْفِرَ اللهُ لَهُمْ إِنَّ اللهَ لا يَهْدِي الْقَوْمَ الْفاسِقِينَ (6) هُمُ الَّذِينَ يَقُولُونَ لا تُنْفِقُوا عَلى مَنْ عِنْدَ رَسُولِ اللهِ حَتَّى يَنْفَضُّوا وَلِلَّهِ خَزائِنُ السَّماواتِ وَالْأَرْضِ حركوها حركة المعرض ، وعطفوها نحوا إلى جانب يخالف جانب القائل تكبرا وإعراضا ( وَرَأَيْتَهُمْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم أو أيها الرائي ( يَصُدُّونَ ) أي يمنعون عن سبيل الحق ( وَهُمْ مُسْتَكْبِرُونَ ) يظهرون كبرهم وأنهم لا حاجة لهم إلى استغفار الرسول. [7] وإذ كان أولئك منافقين ف ( سَواءٌ عَلَيْهِمْ ) في عدم الانتفاع وعدم غفران الله لهم ( أَسْتَغْفَرْتَ لَهُمْ ) يا رسول الله ( أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ ) فإن الاستغفار إنما ينفع المؤمن دون المنافق ( لَنْ يَغْفِرَ اللهُ لَهُمْ ) أبدا لأنهم يبطنون الكفر ( إِنَّ اللهَ لا يَهْدِي ) بالألطاف الخفية ( الْقَوْمَ الْفاسِقِينَ ) الذين خرجوا عن طاعة الله بالنفاق والشقاق.` },
            { text: "سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ", tafsir: `` },
            { text: "هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَفْقَهُونَ", tafsir: `المنافقون ( الَّذِينَ يَقُولُونَ ) بعضهم لبعض ( لا تُنْفِقُوا عَلى مَنْ عِنْدَ رَسُولِ اللهِ ) من المؤمنين أصحاب الحاجة ( حَتَّى يَنْفَضُّوا ) أي يتفرقوا عنه ، ويأتي التعليق على كلامهم هذا بقوله ( وَلِلَّهِ خَزائِنُ السَّماواتِ وَالْأَرْضِ ) التي يبذل منها لمن حوالي رسول الله صلى‌الله‌عليه‌وآله‌وسلم فقد ظن هؤلاء المنافقون أن خزائن الأرزاق والأموال بأيديهم حتى إذا قطعوا الأموال على المؤمنين يتفرقون ، وجهلوا أن الشمس وَلكِنَّ الْمُنافِقِينَ لا يَفْقَهُونَ (7) يَقُولُونَ لَئِنْ رَجَعْنا إِلَى الْمَدِينَةِ لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ وَلكِنَّ الْمُنافِقِينَ لا يَعْلَمُونَ (8) يا أَيُّهَا الَّذِينَ آمَنُوا لا تُلْهِكُمْ أَمْوالُكُمْ وَلا أَوْلادُكُمْ عَنْ والأرض والماء والهواء التي هي خزائن الأموال والأرزاق كلها بيد الله تعالى فيبذل منها على المسلمين بالزراعة والاكتساب وما أشبه ، فليس منع أولئك سببا لتفرق هؤلاء المؤمنين من حول الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَلكِنَّ الْمُنافِقِينَ لا يَفْقَهُونَ ) أي لا يفهمون أن الخزائن بيد الله تعالى.` },
            { text: "يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَعْلَمُونَ", tafsir: `هؤلاء المنافقون ( لَئِنْ رَجَعْنا إِلَى الْمَدِينَةِ ) من غزوة بني المصطلق ( لَيُخْرِجَنَّ الْأَعَزُّ ) يريدون المنافقين أنفسهم ( مِنْهَا ) أي من المدينة ( الْأَذَلَ ) يريدون الرسول صلى‌الله‌عليه‌وآله‌وسلم وأصحابه ، ويأتي الرد عليهم ( وَلِلَّهِ الْعِزَّةُ ) وهو مع المؤمنين ( وَلِرَسُولِهِ ) بإعزاز الله له ( وَلِلْمُؤْمِنِينَ ) بتمسكهم بالإسلام الموجب لسعادة الدنيا والآخرة وعزتهما ( وَلكِنَّ الْمُنافِقِينَ لا يَعْلَمُونَ ) فيظنون أن العزة لهم حيث يجدون أعوانا من المنافقين ومقدارا يسيرا من المال ، وقد دلت التجربة على ذلك ، فقد جاء الأذل ، وهو ابن أبيّ ـ إلى الأعز ـ وهو الرسول ، يعطي البراءة عما اقترفه. [10] وإذا تقدم ذكر النفاق الذي هو إبطان الكفر وإظهار الإيمان جاء السياق ليذكّر المسلمين بأن لا يفعلوا ما هو من أخلاق المنافقين من الإقبال على الدنيا ، وجعل الآخرة وراء ظهرهم ( يا أَيُّهَا الَّذِينَ آمَنُوا لا تُلْهِكُمْ ) أي لا تشغلكم ( أَمْوالُكُمْ وَلا أَوْلادُكُمْ عَنْ ذِكْرِ اللهِ وَمَنْ يَفْعَلْ ذلِكَ فَأُولئِكَ هُمُ الْخاسِرُونَ (9) وَأَنْفِقُوا مِنْ ما رَزَقْناكُمْ مِنْ قَبْلِ أَنْ يَأْتِيَ أَحَدَكُمُ الْمَوْتُ فَيَقُولَ رَبِّ لَوْ لا أَخَّرْتَنِي إِلى أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُنْ مِنَ الصَّالِحِينَ (10) وَلَنْ يُؤَخِّرَ اللهُ نَفْساً إِذا جاءَ أَجَلُها وَاللهُ خَبِيرٌ بِما تَعْمَلُونَ (11) ذِكْرِ اللهِ ) بأن تشتغلوا بها فلا تراعوا حق الله فيها ولا تحضروا للصلاة وغيرها من سائر الفرائض اشتغالا بالمال والولد. ( وَمَنْ يَفْعَلْ ذلِكَ ) الاشتغال بالمال والولد عن ذكر الله ( فَأُولئِكَ هُمُ الْخاسِرُونَ ) الذين خسروا أنفسهم إذ لا نجاة لهم في الآخرة من العذاب.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُمْ عَن ذِكْرِ ٱللَّهِ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ", tafsir: `` },
            { text: "وَأَنفِقُوا۟ مِن مَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ", tafsir: `فيما أمرنا من الخمس والزكاة والصلاة وسائر الحقوق ـ ولعله عام يشمل الإنفاق من العلم والجاه والقوة بالإضافة إلى الإنفاق من المال ـ ( مِنْ قَبْلِ أَنْ يَأْتِيَ أَحَدَكُمُ الْمَوْتُ ) أي يحضره الموت ، بأن تأتي أسبابه وعلائمه ( فَيَقُولَ ) يا ( رَبِّ لَوْ لا ) أي هلّا ( أَخَّرْتَنِي إِلى أَجَلٍ قَرِيبٍ ) بأن أبقى في الدنيا ولو مدة قليلة لأصلح شأني ( فَأَصَّدَّقَ ) أي أتصدق وأزكي مالي وأنفقه في سبيل الله ( وَأَكُنْ مِنَ الصَّالِحِينَ ) أصلي وأصوم وأحج وأبذل نفسي في سبيلك وحسب أوامرك. [12] وهل ينفع هذا الطلب ؟ كلا ( وَ ) ذلك لأنه ( لَنْ يُؤَخِّرَ اللهُ نَفْساً ) بإبقائها في الدنيا زيادة على المدة المقدرة لها ( إِذا جاءَ ) وحضر ( أَجَلُها ) فلا يتمكن من العمل الصالح ببدنه والإنفاق من ماله ( وَاللهُ خَبِيرٌ بِما تَعْمَلُونَ ) أيها البشر فلا تفعلوا ما يوجب العقاب والنكال. (64)` },
            { text: "وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ", tafsir: `` }
        ]
    }
});
